/* Questions à réponse libre importées
   Généré par import-quiz.js — ne pas éditer à la main.
   580 questions importées des quiz existants de ../ */
window.QBANK = (window.QBANK || []).concat([
  {"id":"tf-v-iac","lvl":2,"dom":"Terraform","q":"Pratique consistant à décrire l'infrastructure dans des fichiers versionnés plutôt que de la créer à la main. Quel terme (ou sigle) ?","explain":"Infrastructure as Code : reproductible, versionnable, revuable. Terraform en est l'outil le plus répandu.","accept":["iac","infrastructure as code"]},
  {"id":"tf-v-hcl","lvl":3,"dom":"Terraform","q":"Langage de configuration de Terraform (blocs, arguments, expressions). Quel sigle ?","explain":"HCL = HashiCorp Configuration Language. Une syntaxe JSON alternative existe aussi (fichiers .tf.json).","accept":["hcl","hashicorp configuration language"]},
  {"id":"tf-v-provider","lvl":2,"dom":"Terraform","q":"Plugin qui permet à Terraform de parler à l'API d'une plateforme (azurerm, aws, google…). Quel nom ?","explain":"Le provider. Téléchargé par terraform init depuis le registry, déclaré dans required_providers.","accept":["provider","fournisseur"]},
  {"id":"tf-v-module","lvl":3,"dom":"Terraform","q":"Ensemble réutilisable de fichiers .tf appelé avec des variables d'entrée et exposant des outputs. Quel nom ?","explain":"Le module. Tout dossier de config est un module ; le dossier où tu lances terraform est le root module.","accept":["module","un module"]},
  {"id":"tf-v-state","lvl":1,"dom":"Terraform","q":"Fichier où Terraform mémorise la correspondance entre ta config et les ressources réelles (par défaut terraform.tfstate). Quel nom (en anglais) ?","explain":"Le state. C'est LA pièce maîtresse : sans lui, Terraform ne sait plus ce qu'il gère. Il peut contenir des secrets en clair !","accept":["state","le state","state file","etat"]},
  {"id":"tf-v-backend","lvl":2,"dom":"Terraform","q":"Configuration qui détermine OÙ le state est stocké (local, azurerm, s3, HCP…). Quel nom ?","explain":"Le backend. Par défaut : local (terraform.tfstate sur disque). En équipe : backend distant avec verrouillage (locking).","accept":["backend","le backend"]},
  {"id":"tf-v-registry","lvl":1,"dom":"Terraform","q":"Plateforme publique HashiCorp où sont publiés providers et modules (registry.terraform.io). Quel nom ?","explain":"Le Terraform Registry. HCP Terraform offre aussi un private registry pour les modules internes d'une organisation.","accept":["registry","terraform registry","le registry","registre"]},
  {"id":"tf-v-locals","lvl":3,"dom":"Terraform","q":"Bloc qui définit des valeurs intermédiaires calculées, référencées ensuite avec local.nom. Quel mot-clé ?","explain":"locals { prefix = \"app-${var.env}\" } — évite la répétition. Déclaré « locals », référencé « local.prefix » (sans s).","accept":["locals","local"]},
  {"id":"tf-v-drift","lvl":1,"dom":"Terraform","q":"Écart entre l'infrastructure RÉELLE et ce que le state/la config croient (ex : modification manuelle dans le portail). Quel terme anglais ?","explain":"Le drift. Détecté par terraform plan (ou plan -refresh-only) : Terraform propose alors de re-aligner le réel sur la config.","accept":["drift","derive","configuration drift"]},
  {"id":"tf-v-workspace","lvl":1,"dom":"Terraform","q":"Mécanisme CLI qui permet d'avoir PLUSIEURS states isolés pour une même configuration (ex : dev / prod). Quel nom ?","explain":"Les workspaces CLI : terraform workspace new/select/list. Chaque workspace a son propre state. Celui de départ s'appelle « default ».","accept":["workspace","workspaces","espace de travail"]},
  {"id":"tf-v-destroy","lvl":2,"dom":"Terraform","q":"Quelle commande détruit TOUTES les ressources gérées par la configuration ?","explain":"terraform destroy (= apply -destroy). À la fin de chaque lab pour ne pas payer ! prevent_destroy peut bloquer une ressource critique.","accept":["terraform destroy","destroy"]},
  {"id":"tf-v-fmt","lvl":3,"dom":"Terraform","q":"Quelle commande reformate automatiquement les fichiers .tf selon les conventions ?","explain":"terraform fmt (-recursive pour les sous-dossiers, -check en CI pour vérifier sans modifier).","accept":["terraform fmt","fmt"]},
  {"id":"tf-v-tfvars","lvl":2,"dom":"Terraform","q":"Extension des fichiers qui assignent des VALEURS aux variables d'entrée (chargé automatiquement s'il s'appelle terraform.____ ) ?","explain":"terraform.tfvars (et *.auto.tfvars) sont chargés automatiquement ; les autres se passent avec -var-file=prod.tfvars.","accept":["tfvars","terraform tfvars",".tfvars"]},
  {"id":"tf-v-tfvar-env","lvl":3,"dom":"Terraform","q":"Quel préfixe de variable d'ENVIRONNEMENT permet de passer une valeur à une variable Terraform (ex : pour « region ») ?","explain":"TF_VAR_region=westeurope — pratique en CI pour ne rien écrire dans les fichiers.","accept":["tf var","tf_var_","tf var region","tfvar"]},
  {"id":"tf-v-sentinel","lvl":3,"dom":"Terraform","q":"Framework « policy as code » de HashiCorp qui autorise ou bloque les runs selon des règles (ex : interdire une région). Quel nom ?","explain":"Sentinel — s'exécute entre plan et apply dans HCP Terraform. Niveaux : advisory, soft-mandatory, hard-mandatory.","accept":["sentinel"]},
  {"id":"tf-f-init-upgrade","lvl":6,"dom":"Terraform","q":"Quelle option de terraform init met à jour les providers vers les dernières versions autorisées par les contraintes ?","explain":"terraform init -upgrade réévalue les contraintes et met à jour le lock file. Sans elle, init respecte le lock file existant.","accept":["upgrade","-upgrade","init -upgrade","terraform init -upgrade"]},
  {"id":"tf-f-replace","lvl":5,"dom":"Terraform","q":"terraform taint est déprécié. Quelle option moderne force le REMPLACEMENT d'une ressource au prochain apply ? terraform apply ____=adresse","explain":"terraform apply -replace=azurerm_linux_vm.web — planifie destroy+create de cette ressource précise.","accept":["-replace","replace","apply -replace"]},
  {"id":"tf-f-refreshonly","lvl":6,"dom":"Terraform","q":"terraform refresh est déprécié. Quelle option de plan met à jour le state depuis le réel SANS proposer de changements de config ? terraform plan ____","explain":"terraform plan/apply -refresh-only — détecte le drift et synchronise le state, sans toucher à l'infra.","accept":["-refresh-only","refresh only","refresh-only"]},
  {"id":"tf-f-state-list","lvl":4,"dom":"Terraform","q":"Quelle commande liste toutes les ressources présentes dans le state ?","explain":"terraform state list. Pour le détail d'une ressource : terraform state show <adresse>.","accept":["terraform state list","state list"]},
  {"id":"tf-f-state-mv","lvl":5,"dom":"Terraform","q":"Quelle commande renomme/déplace une ressource DANS le state sans la détruire (ancêtre du bloc moved) ?","explain":"terraform state mv ancienne.adresse nouvelle.adresse. L'alternative déclarative moderne : le bloc moved {}.","accept":["terraform state mv","state mv"]},
  {"id":"tf-f-state-rm","lvl":6,"dom":"Terraform","q":"Quelle commande retire une ressource du state SANS la détruire (Terraform cesse de la gérer) ?","explain":"terraform state rm adresse — la ressource réelle survit mais devient « unmanaged ». L'inverse d'un import.","accept":["terraform state rm","state rm"]},
  {"id":"tf-f-forceunlock","lvl":6,"dom":"Terraform","q":"Un crash a laissé le state verrouillé. Quelle commande libère le verrou (avec l'ID du lock) ?","explain":"terraform force-unlock <LOCK_ID> — uniquement après avoir vérifié qu'aucun run n'est réellement en cours.","accept":["terraform force-unlock","force-unlock","force unlock"]},
  {"id":"tf-f-ws-cmd","lvl":4,"dom":"Terraform","q":"Quelle commande crée un nouveau workspace CLI nommé « prod » ?","explain":"terraform workspace new prod (puis select/list/show/delete). Le workspace initial s'appelle « default » et ne peut pas être supprimé.","accept":["terraform workspace new prod","workspace new prod","terraform workspace new"]},
  {"id":"tf-f-ws-interp","lvl":5,"dom":"Terraform","q":"Quelle expression HCL donne le nom du workspace courant (ex : pour suffixer des noms de ressources) ?","explain":"name = \"app-${terraform.workspace}\" — permet une config unique déclinée par workspace.","accept":["terraform.workspace","terraform workspace"]},
  {"id":"tf-f-tflog","lvl":6,"dom":"Terraform","q":"Quelle variable d'environnement active les logs détaillés de Terraform (TRACE, DEBUG, INFO, WARN, ERROR) ?","explain":"TF_LOG=TRACE (le plus verbeux) + TF_LOG_PATH=fichier.log pour écrire dans un fichier. TF_LOG_CORE / TF_LOG_PROVIDER pour cibler.","accept":["tf log","tf_log"]},
  {"id":"tf-f-migrate","lvl":6,"dom":"Terraform","q":"Tu ajoutes un bloc backend distant à une config qui a déjà un state local. Quelle commande copie le state vers le nouveau backend ? terraform init ____","explain":"terraform init -migrate-state propose de copier l'état existant. -reconfigure ignore au contraire l'ancien backend sans migrer.","accept":["-migrate-state","migrate state","migrate-state","init -migrate-state"]},
  {"id":"tf-f-lookup","lvl":6,"dom":"Terraform","q":"Quelle fonction récupère une valeur dans une map avec une valeur PAR DÉFAUT si la clé n'existe pas ?","explain":"lookup(var.sizes, var.env, \"Standard_B1s\"). Sans défaut, var.sizes[var.env] suffit (mais plante si absent).","accept":["lookup"]},
  {"id":"tf-f-reqversion","lvl":5,"dom":"Terraform","q":"Quel argument du bloc terraform {} impose une version minimale de Terraform LUI-MÊME ?","explain":"terraform { required_version = \">= 1.5.0\" } — à ne pas confondre avec required_providers.","accept":["required_version","required version"]},
  {"id":"tf-f-module-out","lvl":4,"dom":"Terraform","q":"Comment référencer l'output « vnet_id » du module « network » ? (tape l'expression)","explain":"module.<nom>.<output>. Les valeurs d'un module enfant ne sont visibles que via ses outputs.","accept":["module.network.vnet_id","module network vnet id"]},
  {"id":"tf-f-output-cmd","lvl":4,"dom":"Terraform","q":"Quelle commande affiche les outputs du state (option -json pour l'intégration) ?","explain":"terraform output [nom] [-json] [-raw]. Pratique en script : terraform output -raw ip_publique.","accept":["terraform output","output"]},
  {"id":"tf-f-graph","lvl":6,"dom":"Terraform","q":"Quelle commande exporte le graphe de dépendances (format DOT/Graphviz) ?","explain":"terraform graph | dot -Tpng > graph.png — visualise l'ordre de création calculé.","accept":["terraform graph","graph"]},
  {"id":"tf-f-state-pull","lvl":4,"dom":"Terraform","q":"Quelle commande télécharge et affiche le state DISTANT en JSON sur la sortie standard ?","explain":"terraform state pull (et state push pour l'inverse — dangereux). Utile pour sauvegarder ou inspecter un backend distant.","accept":["terraform state pull","state pull"]},
  {"id":"tf-f-remote-state-ds","lvl":6,"dom":"Terraform","q":"Quel data source lit les OUTPUTS du state d'une AUTRE configuration Terraform ? data \"terraform_____\" ...","explain":"data \"terraform_remote_state\" \"net\" { backend = \"azurerm\" config = {...} } puis data.terraform_remote_state.net.outputs.vnet_id.","accept":["remote_state","terraform_remote_state","remote state"]},
  {"id":"tf-s-preventdestroy","lvl":7,"dom":"Terraform","q":"Personne ne doit pouvoir détruire la base de données de prod via Terraform, même par accident. Quel argument lifecycle ?","explain":"lifecycle { prevent_destroy = true } — tout plan qui impliquerait sa destruction échoue avec une erreur.","accept":["prevent_destroy","prevent destroy"]},
  {"id":"tf-s-ignorechanges","lvl":8,"dom":"Terraform","q":"Un outil externe modifie les tags de tes ressources et chaque plan veut les « corriger ». Quel argument lifecycle arrête ce cycle ?","explain":"lifecycle { ignore_changes = [tags] } — Terraform cesse de surveiller cet attribut précis.","accept":["ignore_changes","ignore changes"]},
  {"id":"tf-s-cbd","lvl":9,"dom":"Terraform","q":"Le remplacement d'une ressource critique doit créer la NOUVELLE avant de détruire l'ancienne (zéro interruption). Quel argument lifecycle ?","explain":"create_before_destroy = true inverse l'ordre destroy→create par défaut. Attention aux contraintes d'unicité de nom.","accept":["create_before_destroy","create before destroy"]},
  {"id":"tf-s-policy","lvl":8,"dom":"Terraform","q":"L'entreprise veut BLOQUER automatiquement tout run qui déploie hors de westeurope. Quel outil HashiCorp (policy as code) ?","explain":"Une policy Sentinel hard-mandatory évaluée entre plan et apply dans HCP Terraform. (OPA est aussi supporté.)","accept":["sentinel"]},
  {"id":"tf-c-reqprov","lvl":4,"dom":"Terraform","q":"Complète le namespace du provider officiel :","explain":"source = \"hashicorp/azurerm\" = registry.terraform.io/hashicorp/azurerm. Namespace + nom, toujours.","accept":["hashicorp"]},
  {"id":"tf-c-data","lvl":6,"dom":"Terraform","q":"Complète le préfixe de référence d'un data source :","explain":"Les data sources se référencent avec data.<type>.<nom>.<attr> — le préfixe data est le piège classique.","accept":["data"]},
  {"id":"tf-c-vartype","lvl":4,"dom":"Terraform","q":"Complète l'argument qui contraint le type :","explain":"type = string/number/bool/list(...)/map(...)/object({...}). Toujours typer ses variables — bonne pratique et question d'examen.","accept":["type"]},
  {"id":"tf-c-count-cond","lvl":5,"dom":"Terraform","q":"Complète le ternaire pour NE PAS créer la ressource :","explain":"count = condition ? 1 : 0 — le pattern « ressource conditionnelle ». Référence ensuite : azurerm_public_ip.pip[0].","accept":["0","zero"]},
  {"id":"tf-c-lifecycle","lvl":4,"dom":"Terraform","q":"Complète pour INTERDIRE la destruction de cette base :","explain":"prevent_destroy = true : tout plan destructeur échoue. Les 4 arguments lifecycle à connaître : create_before_destroy, prevent_destroy, ignore_changes, replace_triggered_by.","accept":["prevent_destroy","prevent destroy"]},
  {"id":"tf-c-dynamic","lvl":9,"dom":"Terraform","q":"Complète le mot-clé qui définit le corps de chaque bloc généré :","explain":"dynamic \"nom\" { for_each = ...  content { ... } }. Dans content, l'itérateur porte le nom du bloc (ip_restriction.value).","accept":["content"]},
  {"id":"tf-c-module","lvl":5,"dom":"Terraform","q":"Complète l'argument qui indique d'où vient le module :","explain":"source est obligatoire (registry, git, chemin local). version ne fonctionne qu'avec les sources registry.","accept":["source"]},
  {"id":"tf-c-output-sens","lvl":6,"dom":"Terraform","q":"Complète pour masquer cette valeur dans la sortie CLI :","explain":"Obligatoire si la valeur provient d'une source sensible, sinon erreur. Rappel : le state la contient quand même en clair.","accept":["sensitive"]},
  {"id":"tf-c-backend","lvl":4,"dom":"Terraform","q":"Complète le type de backend pour stocker le state dans un compte de stockage Azure :","explain":"backend \"azurerm\" — state dans un blob, avec verrouillage par lease. Un changement de backend exige terraform init (-migrate-state).","accept":["azurerm"]},
  {"id":"tf-c-import","lvl":7,"dom":"Terraform","q":"Complète l'argument qui désigne la ressource cible dans la config :","explain":"import { to = adresse, id = \"id réel\" } (Terraform 1.5+). Bonus : terraform plan -generate-config-out=gen.tf écrit la config pour toi.","accept":["to"]},
  {"id":"tf-c-moved","lvl":8,"dom":"Terraform","q":"Complète le bloc de refactoring :","explain":"moved { from, to } : le prochain apply met à jour l'adresse dans le state sans toucher à la ressource réelle.","accept":["to"]},
  {"id":"tf-c-ws-interp","lvl":5,"dom":"Terraform","q":"Complète pour insérer le nom du workspace courant :","explain":"terraform.workspace — « default » si aucun workspace créé. Permet une config unique multi-environnements.","accept":["workspace"]},
  {"id":"tf-csB-region","lvl":8,"dom":"Terraform","q":"Le RSSI exige de BLOQUER tout déploiement hors d'Europe, automatiquement, au niveau de l'organisation. Quel outil HashiCorp ?","explain":"Policy Sentinel hard-mandatory dans HCP Terraform : évaluée sur chaque run, impossible à contourner par les équipes.","accept":["sentinel"]},
  {"id":"tf-csB-legacy","lvl":9,"dom":"Terraform","q":"Des dizaines de ressources historiques ont été créées au portail. Quelle fonctionnalité les fait entrer dans Terraform sans les recréer ?","explain":"Le bloc import (avec -generate-config-out pour générer la config en masse) — l'outil de l'adoption progressive.","accept":["import","bloc import","terraform import","l import"]},
  {"id":"tf-csB-refactor","lvl":7,"dom":"Terraform","q":"La nouvelle convention de nommage impose de renommer les ressources DANS le code sans rien détruire. Quel bloc HCL ?","explain":"moved { from, to } — le refactoring déclaratif, revuable en PR, appliqué sans destroy/recreate.","accept":["moved","bloc moved","moved block"]},
  {"id":"cka-c-apiserver","lvl":2,"dom":"Kubernetes","q":"Quel composant du control plane est le SEUL à communiquer directement avec etcd et sert de point d'entrée à toutes les requêtes ?","explain":"kube-apiserver : porte d'entrée unique (REST), authentification, autorisation, admission. Tous les autres composants passent par lui — jamais directement par etcd.","accept":["kube-apiserver","apiserver","api server"]},
  {"id":"cka-c-etcd","lvl":3,"dom":"Kubernetes","q":"Quel composant stocke l'intégralité de l'état du cluster sous forme de base clé-valeur distribuée ?","explain":"etcd. C'est LA donnée à sauvegarder : un snapshot etcd suffit à restaurer tout le cluster. Sauvegarde et restauration sont au programme.","accept":["etcd"]},
  {"id":"cka-c-scheduler","lvl":1,"dom":"Kubernetes","q":"Quel composant choisit sur quel nœud placer un pod nouvellement créé, sans le démarrer lui-même ?","explain":"kube-scheduler filtre (predicates) puis note (priorities) les nœuds, et écrit le nodeName. C'est ensuite le kubelet du nœud élu qui démarre le pod.","accept":["kube-scheduler","scheduler"]},
  {"id":"cka-c-cm","lvl":2,"dom":"Kubernetes","q":"Quel composant exécute les boucles de réconciliation (node controller, replicaset controller, endpoints…) ?","explain":"kube-controller-manager regroupe tous les contrôleurs dans un seul binaire. Chacun compare l'état désiré à l'état réel et agit pour les réconcilier.","accept":["kube-controller-manager","controller-manager","controller manager"]},
  {"id":"cka-c-kubelet","lvl":3,"dom":"Kubernetes","q":"Quel agent tourne sur CHAQUE nœud, démarre les conteneurs et remonte l'état des pods à l'API server ?","explain":"Le kubelet. S'il est arrêté, le nœud passe NotReady. Il gère aussi les static pods du dossier /etc/kubernetes/manifests.","accept":["kubelet"]},
  {"id":"cka-c-kubeproxy","lvl":1,"dom":"Kubernetes","q":"Quel composant programme les règles réseau (iptables/IPVS) qui rendent les Services joignables depuis chaque nœud ?","explain":"kube-proxy traduit les Services en règles de routage. S'il est HS sur un nœud, les pods de ce nœud ne joignent plus les ClusterIP.","accept":["kube-proxy","kubeproxy"]},
  {"id":"cka-c-staticpod","lvl":2,"dom":"Kubernetes","q":"Comment appelle-t-on un pod géré directement par le kubelet à partir d'un fichier local, sans passer par l'API server (2 mots) ?","explain":"Static pod : le kubelet surveille /etc/kubernetes/manifests. C'est ainsi que tournent apiserver, etcd, scheduler et controller-manager sur un cluster kubeadm. Modifier le fichier redémarre le pod.","accept":["static pod","static pods","pod statique"]},
  {"id":"cka-c-staticpath","lvl":3,"dom":"Kubernetes","q":"Quel est le chemin par défaut du dossier des static pods sur un cluster kubeadm ?","explain":"/etc/kubernetes/manifests. Réflexe de troubleshooting : si l'API server ne répond plus, c'est là qu'on va lire et corriger son manifeste.","accept":["/etc/kubernetes/manifests","etc kubernetes manifests"]},
  {"id":"cka-c-kubeconfig","lvl":1,"dom":"Kubernetes","q":"Quel est le chemin du kubeconfig administrateur généré par kubeadm sur le control plane ?","explain":"/etc/kubernetes/admin.conf. On le copie dans ~/.kube/config. Les autres : kubelet.conf, controller-manager.conf, scheduler.conf.","accept":["/etc/kubernetes/admin.conf","etc kubernetes admin conf"]},
  {"id":"cka-c-ds","lvl":2,"dom":"Kubernetes","q":"Quel objet garantit qu'une copie d'un pod tourne sur CHAQUE nœud (agents de logs, CNI, monitoring) ?","explain":"DaemonSet. Il place automatiquement un pod sur chaque nouveau nœud, et tolère souvent les taints du control plane pour y tourner aussi.","accept":["daemonset"]},
  {"id":"cka-c-sts","lvl":3,"dom":"Kubernetes","q":"Quel objet fournit une identité réseau stable et un stockage persistant dédié à chaque réplique (bases de données) ?","explain":"StatefulSet : noms ordonnés (app-0, app-1), PVC par réplique via volumeClaimTemplates, et un headless Service pour l'identité DNS.","accept":["statefulset"]},
  {"id":"cka-c-nodeport-range","lvl":3,"dom":"Kubernetes","q":"Quelle est la plage de ports par défaut d'un Service NodePort ?","explain":"30000-32767. Modifiable par --service-node-port-range sur l'API server, mais la valeur par défaut est demandée.","accept":["30000-32767","30000 32767"]},
  {"id":"cka-c-cni","lvl":1,"dom":"Réseau","q":"Quel type de plugin fournit le réseau des pods (Calico, Flannel, Cilium…) — sigle ?","explain":"CNI. Sans plugin CNI installé, les nœuds restent NotReady et CoreDNS reste en Pending — symptôme classique après un kubeadm init.","accept":["cni","container network interface"]},
  {"id":"cka-c-coredns","lvl":2,"dom":"Réseau","q":"Quel composant assure la résolution DNS interne du cluster (nom de Service → ClusterIP) ?","explain":"CoreDNS, déployé en Deployment dans kube-system avec le Service kube-dns. Si la résolution échoue, on vérifie ses pods et sa ConfigMap.","accept":["coredns","core dns"]},
  {"id":"cka-c-sa","lvl":2,"dom":"Sécurité","q":"Quel objet fournit une identité aux PODS (par opposition aux utilisateurs humains) — 2 mots ?","explain":"Le ServiceAccount. Chaque namespace en a un « default » monté automatiquement. On le lie à des droits via RoleBinding/ClusterRoleBinding.","accept":["service account","serviceaccount","compte de service"]},
  {"id":"cka-c-cri","lvl":1,"dom":"Kubernetes","q":"Quel outil en ligne de commande permet d'inspecter conteneurs et images directement sur un nœud, quand kubectl ne répond plus ?","explain":"crictl ps, crictl logs, crictl inspect. Indispensable quand l'API server est HS : c'est le seul moyen de voir les conteneurs des static pods.","accept":["crictl"]},
  {"id":"cka-c-pdb","lvl":3,"dom":"Kubernetes","q":"Quel objet garantit qu'un nombre minimal de répliques reste disponible pendant une éviction volontaire (drain) — sigle ?","explain":"PodDisruptionBudget (minAvailable ou maxUnavailable). Un drain qui reste bloqué indéfiniment est souvent dû à un PDB trop strict.","accept":["pdb","poddisruptionbudget","pod disruption budget"]},
  {"id":"cka-k-ctx-use","lvl":1,"dom":"Kubernetes","q":"Bascule sur le contexte « k8s-c1 ». (À faire au début de CHAQUE tâche de l'examen.)","explain":"L'examen fournit cette commande en tête de chaque tâche. La lancer systématiquement évite de perdre des points en travaillant sur le mauvais cluster.","accept":["kubectl config use-context k8s-c1"]},
  {"id":"cka-k-ctx-current","lvl":2,"dom":"Kubernetes","q":"Affiche le contexte actuellement actif.","explain":"Réflexe de vérification en 1 seconde avant toute action destructrice.","accept":["kubectl config current-context"]},
  {"id":"cka-k-ctx-list","lvl":3,"dom":"Kubernetes","q":"Liste tous les contextes disponibles dans le kubeconfig.","explain":"La colonne CURRENT marque d'un astérisque le contexte actif.","accept":["kubectl config get-contexts"]},
  {"id":"cka-k-ns-default","lvl":1,"dom":"Kubernetes","q":"Change le namespace par défaut du contexte courant pour « prod ».","explain":"Gain de temps énorme sur une tâche multi-commandes : évite de répéter -n prod partout.","accept":["kubectl config set-context --current --namespace=prod"]},
  {"id":"cka-k-get-wide","lvl":2,"dom":"Kubernetes","q":"Liste les pods du namespace courant en affichant l'IP et le nœud d'exécution.","explain":"-o wide ajoute IP, NODE, NOMINATED NODE. Première commande de tout diagnostic de placement.","accept":["kubectl get pods -o wide","kubectl get pod -o wide","kubectl get po -o wide"]},
  {"id":"cka-k-get-all-ns","lvl":3,"dom":"Kubernetes","q":"Liste les pods de TOUS les namespaces.","explain":"-A est le raccourci de --all-namespaces. À utiliser dès qu'on cherche un pod sans savoir où il vit.","accept":["kubectl get pods -A","kubectl get pods --all-namespaces","kubectl get po -A","kubectl get pod -A"]},
  {"id":"cka-k-get-label","lvl":5,"dom":"Kubernetes","q":"Liste les pods portant le label « app=web ».","explain":"-l accepte aussi les négations (app!=web), les ensembles (env in (dev,prod)) et le cumul (-l app=web,tier=front).","accept":["kubectl get pods -l app=web","kubectl get pods --selector=app=web","kubectl get po -l app=web"]},
  {"id":"cka-k-show-labels","lvl":6,"dom":"Kubernetes","q":"Liste les pods en affichant tous leurs labels.","explain":"Indispensable quand un Service ne trouve pas ses pods : on compare le selector aux labels réels.","accept":["kubectl get pods --show-labels","kubectl get po --show-labels"]},
  {"id":"cka-k-sort","lvl":4,"dom":"Kubernetes","q":"Liste les pods de tous les namespaces triés par nombre de redémarrages.","explain":"--sort-by prend un JSONPath. Autre tri utile : --sort-by=.metadata.creationTimestamp pour retrouver le dernier objet créé.","accept":["kubectl get pods -A --sort-by=.status.containerStatuses[0].restartCount","kubectl get pods --all-namespaces --sort-by=.status.containerStatuses[0].restartCount"]},
  {"id":"cka-k-events","lvl":5,"dom":"Kubernetes","q":"Affiche les événements du namespace courant triés par date de création.","explain":"Les events expliquent 80 % des pods Pending ou en échec. Par défaut ils ne sont PAS triés chronologiquement — d'où le --sort-by.","accept":["kubectl get events --sort-by=.metadata.creationTimestamp","kubectl get ev --sort-by=.metadata.creationTimestamp"]},
  {"id":"cka-k-describe","lvl":1,"dom":"Kubernetes","q":"Affiche le détail complet du pod « web-1 », y compris ses événements.","explain":"La section Events en bas de describe est la première chose à lire sur un pod qui ne démarre pas.","accept":["kubectl describe pod web-1","kubectl describe po web-1"]},
  {"id":"cka-k-logs","lvl":2,"dom":"Kubernetes","q":"Affiche les logs du pod « web-1 ».","explain":"Base du diagnostic applicatif. Ajoute -f pour suivre en direct.","accept":["kubectl logs web-1"]},
  {"id":"cka-k-logs-prev","lvl":6,"dom":"Kubernetes","q":"Affiche les logs de l'instance PRÉCÉDENTE du pod « web-1 », qui vient de redémarrer.","explain":"LA commande du CrashLoopBackOff : le conteneur actuel vient de démarrer, la cause du crash est dans les logs précédents.","accept":["kubectl logs web-1 --previous","kubectl logs web-1 -p"]},
  {"id":"cka-k-logs-container","lvl":4,"dom":"Kubernetes","q":"Affiche les logs du conteneur « sidecar » dans le pod multi-conteneurs « web-1 ».","explain":"Sans -c sur un pod multi-conteneurs, kubectl refuse et liste les conteneurs disponibles.","accept":["kubectl logs web-1 -c sidecar","kubectl logs web-1 --container=sidecar"]},
  {"id":"cka-k-logs-label","lvl":5,"dom":"Kubernetes","q":"Affiche les logs de tous les pods portant le label « app=web ».","explain":"Pratique pour un Deployment multi-répliques. Ajoute --prefix pour savoir quel pod a écrit quoi.","accept":["kubectl logs -l app=web","kubectl logs --selector=app=web"]},
  {"id":"cka-k-exec","lvl":3,"dom":"Kubernetes","q":"Ouvre un shell interactif bash dans le pod « web-1 ».","explain":"Ne pas oublier le double tiret « -- » qui sépare les options kubectl de la commande à exécuter dans le conteneur.","accept":["kubectl exec -it web-1 -- bash","kubectl exec -it web-1 -- /bin/bash","kubectl exec -it web-1 -- sh","kubectl exec -it web-1 -- /bin/sh"]},
  {"id":"cka-k-run-tmp","lvl":6,"dom":"Kubernetes","q":"Lance un pod temporaire « tmp » basé sur busybox, interactif, supprimé à la sortie, pour tester le réseau.","explain":"Le couteau suisse du diagnostic réseau : depuis ce pod on teste nslookup, wget, ping. --rm nettoie automatiquement.","accept":["kubectl run tmp --image=busybox -it --rm -- sh","kubectl run tmp --image=busybox --rm -it -- sh","kubectl run tmp -it --rm --image=busybox -- sh"]},
  {"id":"cka-k-top-nodes","lvl":4,"dom":"Kubernetes","q":"Affiche la consommation CPU et mémoire des nœuds.","explain":"Exige le metrics-server. S'il renvoie une erreur, c'est souvent qu'il n'est pas installé — pas que la commande est fausse.","accept":["kubectl top nodes","kubectl top node"]},
  {"id":"cka-k-top-pods","lvl":5,"dom":"Kubernetes","q":"Affiche la consommation des pods du namespace « prod », triés par CPU décroissant.","explain":"--sort-by=cpu ou =memory. Typique d'une tâche « trouve le pod qui consomme le plus ».","accept":["kubectl top pods -n prod --sort-by=cpu","kubectl top pod -n prod --sort-by=cpu"]},
  {"id":"cka-k-dryrun","lvl":6,"dom":"Kubernetes","q":"Génère (sans créer) le YAML d'un pod « nginx » basé sur l'image nginx, dans un fichier pod.yaml.","explain":"LA technique qui fait gagner l'examen : jamais écrire un manifeste de zéro. Générer puis éditer avec vim.","accept":["kubectl run nginx --image=nginx --dry-run=client -o yaml > pod.yaml"]},
  {"id":"cka-k-create-deploy","lvl":4,"dom":"Kubernetes","q":"Crée un Deployment « web » avec l'image nginx et 3 répliques.","explain":"Ajoute --dry-run=client -o yaml pour obtenir le manifeste si la tâche demande des champs non couverts par la commande.","accept":["kubectl create deployment web --image=nginx --replicas=3"]},
  {"id":"cka-k-expose","lvl":5,"dom":"Kubernetes","q":"Expose le Deployment « web » via un Service ClusterIP sur le port 80 vers le port cible 8080.","explain":"expose reprend automatiquement les labels du Deployment comme selector — c'est plus fiable que d'écrire le Service à la main.","accept":["kubectl expose deployment web --port=80 --target-port=8080","kubectl expose deploy web --port=80 --target-port=8080"]},
  {"id":"cka-k-expose-nodeport","lvl":6,"dom":"Kubernetes","q":"Expose le pod « web » en NodePort sur le port 80, avec un Service nommé « web-svc ».","explain":"Le NodePort exact (30000-32767) est attribué automatiquement, sauf à éditer le YAML pour le fixer.","accept":["kubectl expose pod web --port=80 --type=NodePort --name=web-svc","kubectl expose po web --port=80 --type=NodePort --name=web-svc"]},
  {"id":"cka-k-create-cm","lvl":4,"dom":"Kubernetes","q":"Crée une ConfigMap « app-config » avec la clé APP_ENV valant « prod ».","explain":"Autres sources : --from-file=chemin, --from-env-file=fichier.env. Plusieurs --from-literal peuvent être cumulés.","accept":["kubectl create configmap app-config --from-literal=APP_ENV=prod","kubectl create cm app-config --from-literal=APP_ENV=prod"]},
  {"id":"cka-k-create-secret","lvl":5,"dom":"Kubernetes","q":"Crée un Secret générique « db-cred » avec la clé password valant « S3cret ».","explain":"Les types : generic, docker-registry (pour imagePullSecrets), tls. Le contenu est encodé en base64, PAS chiffré.","accept":["kubectl create secret generic db-cred --from-literal=password=S3cret"]},
  {"id":"cka-k-create-sa","lvl":6,"dom":"Sécurité","q":"Crée un ServiceAccount nommé « deployer » dans le namespace « prod ».","explain":"Depuis Kubernetes 1.24, aucun token n'est généré automatiquement : il faut créer un Secret de type kubernetes.io/service-account-token si un token statique est demandé.","accept":["kubectl create serviceaccount deployer -n prod","kubectl create sa deployer -n prod"]},
  {"id":"cka-k-create-role","lvl":4,"dom":"Sécurité","q":"Crée un Role « pod-reader » autorisant get, list et watch sur les pods, dans le namespace « dev ».","explain":"--resource accepte aussi les sous-ressources (pods/log) et --resource-name pour cibler un objet précis.","accept":["kubectl create role pod-reader --verb=get,list,watch --resource=pods -n dev","kubectl create role pod-reader --verb=get --verb=list --verb=watch --resource=pods -n dev"]},
  {"id":"cka-k-create-rb","lvl":5,"dom":"Sécurité","q":"Lie le Role « pod-reader » au ServiceAccount « dev:deployer » via un RoleBinding « read-pods » dans le namespace dev.","explain":"Syntaxe --serviceaccount=<namespace>:<nom>. Pour un utilisateur : --user=nom ; pour un groupe : --group=nom.","accept":["kubectl create rolebinding read-pods --role=pod-reader --serviceaccount=dev:deployer -n dev"]},
  {"id":"cka-k-auth-can-i","lvl":6,"dom":"Sécurité","q":"Vérifie si le ServiceAccount « deployer » du namespace dev peut créer des deployments dans ce namespace.","explain":"LA commande de validation RBAC. Le format d'usurpation est system:serviceaccount:<ns>:<nom>. Réponse : yes ou no.","accept":["kubectl auth can-i create deployments --as=system:serviceaccount:dev:deployer -n dev"]},
  {"id":"cka-k-create-ns","lvl":1,"dom":"Kubernetes","q":"Crée un namespace nommé « staging ».","explain":"Simple, mais souvent la première étape d'une tâche en plusieurs actes.","accept":["kubectl create namespace staging","kubectl create ns staging"]},
  {"id":"cka-k-create-job","lvl":4,"dom":"Kubernetes","q":"Crée un Job « compte » exécutant l'image busybox avec la commande « echo hello ».","explain":"Pour un CronJob : kubectl create cronjob nom --image=busybox --schedule=\"*/1 * * * *\" -- echo hello.","accept":["kubectl create job compte --image=busybox -- echo hello"]},
  {"id":"cka-k-create-cj","lvl":5,"dom":"Kubernetes","q":"Crée un CronJob « backup » (image busybox) s'exécutant toutes les 5 minutes avec la commande « echo save ».","explain":"Le schedule cron a 5 champs (min heure jour mois jour-semaine) — pas 6 comme NCRONTAB d'Azure Functions.","accept":["kubectl create cronjob backup --image=busybox --schedule=*/5 * * * * -- echo save","kubectl create cronjob backup --image=busybox --schedule=\"*/5 * * * *\" -- echo save"]},
  {"id":"cka-k-scale","lvl":2,"dom":"Kubernetes","q":"Passe le Deployment « web » à 5 répliques.","explain":"Fonctionne aussi sur ReplicaSet et StatefulSet. Option --current-replicas pour un scale conditionnel.","accept":["kubectl scale deployment web --replicas=5","kubectl scale deploy web --replicas=5"]},
  {"id":"cka-k-set-image","lvl":6,"dom":"Kubernetes","q":"Met à jour l'image du conteneur « nginx » du Deployment « web » vers nginx:1.27.","explain":"Syntaxe <nom-conteneur>=<image>. C'est ce qui déclenche un rolling update et crée une nouvelle révision.","accept":["kubectl set image deployment/web nginx=nginx:1.27","kubectl set image deploy/web nginx=nginx:1.27"]},
  {"id":"cka-k-rollout-status","lvl":4,"dom":"Kubernetes","q":"Suis l'avancement du déploiement en cours du Deployment « web ».","explain":"Bloque jusqu'à la fin du rollout — pratique pour vérifier qu'une mise à jour aboutit vraiment.","accept":["kubectl rollout status deployment/web","kubectl rollout status deploy/web","kubectl rollout status deployment web"]},
  {"id":"cka-k-rollout-undo","lvl":5,"dom":"Kubernetes","q":"Annule le dernier déploiement du Deployment « web » et reviens à la version précédente.","explain":"Ajoute --to-revision=N pour revenir à une révision précise, listée par kubectl rollout history.","accept":["kubectl rollout undo deployment/web","kubectl rollout undo deploy/web","kubectl rollout undo deployment web"]},
  {"id":"cka-k-rollout-history","lvl":6,"dom":"Kubernetes","q":"Affiche l'historique des révisions du Deployment « web ».","explain":"Le CHANGE-CAUSE n'est rempli que si l'annotation kubernetes.io/change-cause a été posée.","accept":["kubectl rollout history deployment/web","kubectl rollout history deploy/web","kubectl rollout history deployment web"]},
  {"id":"cka-k-rollout-restart","lvl":4,"dom":"Kubernetes","q":"Force le redémarrage progressif de tous les pods du Deployment « web » sans changer l'image.","explain":"Utile après modification d'une ConfigMap ou d'un Secret monté : les pods ne les rechargent pas automatiquement.","accept":["kubectl rollout restart deployment/web","kubectl rollout restart deploy/web","kubectl rollout restart deployment web"]},
  {"id":"cka-k-label","lvl":5,"dom":"Kubernetes","q":"Ajoute le label « env=prod » au pod « web-1 ».","explain":"Ajoute --overwrite pour écraser un label existant, ou suffixe le nom d'un tiret (env-) pour le supprimer.","accept":["kubectl label pod web-1 env=prod","kubectl label po web-1 env=prod"]},
  {"id":"cka-k-annotate","lvl":6,"dom":"Kubernetes","q":"Ajoute l'annotation « owner=osama » au deployment « web ».","explain":"Les annotations portent des métadonnées non sélectionnables (contrairement aux labels).","accept":["kubectl annotate deployment web owner=osama","kubectl annotate deploy web owner=osama"]},
  {"id":"cka-k-edit","lvl":3,"dom":"Kubernetes","q":"Édite en direct le Deployment « web » dans l'éditeur.","explain":"Rapide, mais certains champs sont immuables (selector d'un Deployment) : kubectl proposera alors de sauvegarder dans un fichier temporaire.","accept":["kubectl edit deployment web","kubectl edit deploy web"]},
  {"id":"cka-k-apply","lvl":1,"dom":"Kubernetes","q":"Applique le manifeste contenu dans le fichier app.yaml.","explain":"apply est idempotent (create ou update). replace --force recrée l'objet quand un champ immuable doit changer.","accept":["kubectl apply -f app.yaml"]},
  {"id":"cka-k-delete-now","lvl":4,"dom":"Kubernetes","q":"Supprime immédiatement le pod « web-1 » sans attendre le délai de grâce.","explain":"À réserver aux pods bloqués en Terminating. En temps normal, une suppression propre respecte le preStop et le grace period.","accept":["kubectl delete pod web-1 --grace-period=0 --force","kubectl delete po web-1 --force --grace-period=0"]},
  {"id":"cka-k-drain","lvl":5,"dom":"Kubernetes","q":"Vide le nœud « node01 » de ses pods pour maintenance, en ignorant les DaemonSets.","explain":"Sans --ignore-daemonsets, drain échoue systématiquement (les pods de DaemonSet ne peuvent pas être évincés). Ajoute --delete-emptydir-data si des pods ont des volumes emptyDir.","accept":["kubectl drain node01 --ignore-daemonsets","kubectl drain node01 --ignore-daemonsets --delete-emptydir-data"]},
  {"id":"cka-k-uncordon","lvl":6,"dom":"Kubernetes","q":"Remets le nœud « node01 » en service après maintenance.","explain":"Étape systématiquement oubliée : sans uncordon, le nœud reste SchedulingDisabled et le cluster tourne en capacité réduite.","accept":["kubectl uncordon node01"]},
  {"id":"cka-k-cordon","lvl":4,"dom":"Kubernetes","q":"Empêche la planification de nouveaux pods sur « node01 », sans toucher aux pods existants.","explain":"cordon seul = préparation en douceur. C'est drain qui expulse réellement les pods.","accept":["kubectl cordon node01"]},
  {"id":"cka-k-taint","lvl":5,"dom":"Kubernetes","q":"Ajoute au nœud « node01 » le taint « gpu=true » avec l'effet NoSchedule.","explain":"Pour retirer un taint, on répète la commande en suffixant d'un tiret : kubectl taint node node01 gpu=true:NoSchedule-","accept":["kubectl taint node node01 gpu=true:NoSchedule","kubectl taint nodes node01 gpu=true:NoSchedule"]},
  {"id":"cka-k-taint-remove","lvl":6,"dom":"Kubernetes","q":"Retire du nœud « node01 » le taint « gpu=true:NoSchedule ».","explain":"Le tiret final signifie « supprimer ». Même logique pour les labels : kubectl label node node01 env-","accept":["kubectl taint node node01 gpu=true:NoSchedule-","kubectl taint nodes node01 gpu=true:NoSchedule-"]},
  {"id":"cka-k-node-labels","lvl":4,"dom":"Kubernetes","q":"Ajoute le label « disktype=ssd » au nœud « node01 ».","explain":"Prérequis du nodeSelector : le pod ne sera placé que sur les nœuds portant ce label.","accept":["kubectl label node node01 disktype=ssd","kubectl label nodes node01 disktype=ssd"]},
  {"id":"cka-k-jsonpath","lvl":8,"dom":"Kubernetes","q":"Affiche uniquement les noms de tous les nœuds, un par ligne, via JSONPath.","explain":"Ajoute {\"\\n\"} pour le retour à la ligne. Les tâches d'examen demandent souvent d'écrire un résultat filtré dans un fichier.","accept":["kubectl get nodes -o jsonpath={.items[*].metadata.name}","kubectl get nodes -o jsonpath='{.items[*].metadata.name}'"]},
  {"id":"cka-k-custom-columns","lvl":9,"dom":"Kubernetes","q":"Affiche les pods avec deux colonnes personnalisées : NAME et l'image du premier conteneur.","explain":"custom-columns est souvent plus lisible que jsonpath pour produire un tableau demandé par l'énoncé.","accept":["kubectl get pods -o custom-columns=NAME:.metadata.name,IMAGE:.spec.containers[0].image"]},
  {"id":"cka-k-explain","lvl":5,"dom":"Kubernetes","q":"Affiche la documentation des champs de spec d'un Pod, récursivement, sans quitter le terminal.","explain":"kubectl explain est ta doc HORS onglet navigateur : plus rapide qu'une recherche web pour retrouver un nom de champ exact.","accept":["kubectl explain pod.spec --recursive","kubectl explain pods.spec --recursive"]},
  {"id":"cka-k-api-resources","lvl":6,"dom":"Kubernetes","q":"Liste toutes les ressources de l'API qui ne sont PAS namespacées.","explain":"Donne aussi les abréviations (po, deploy, svc) et l'apiVersion de chaque ressource — utile pour écrire un manifeste juste.","accept":["kubectl api-resources --namespaced=false"]},
  {"id":"cka-k-get-yaml","lvl":4,"dom":"Kubernetes","q":"Exporte le YAML complet du deployment « web » dans un fichier web.yaml.","explain":"Pratique pour repartir d'un objet existant. Le YAML contient des champs générés (status, uid) à nettoyer avant réapplication.","accept":["kubectl get deployment web -o yaml > web.yaml","kubectl get deploy web -o yaml > web.yaml"]},
  {"id":"cka-k-etcd-snapshot","lvl":7,"dom":"Kubernetes","q":"Prends un snapshot etcd dans /opt/backup.db (certificats kubeadm standards, endpoint local).","explain":"Les 3 chemins de certificats sont TOUJOURS les mêmes sur kubeadm. Apprends-les par cœur : c'est une tâche quasi garantie et chronophage si tu dois les chercher.","accept":["ETCDCTL_API=3 etcdctl snapshot save /opt/backup.db --endpoints=https://127.0.0.1:2379 --cacert=/etc/kubernetes/pki/etcd/ca.crt --cert=/etc/kubernetes/pki/etcd/server.crt --key=/etc/kubernetes/pki/etcd/server.key","etcdctl snapshot save /opt/backup.db --endpoints=https://127.0.0.1:2379 --cacert=/etc/kubernetes/pki/etcd/ca.crt --cert=/etc/kubernetes/pki/etcd/server.crt --key=/etc/kubernetes/pki/etcd/server.key"]},
  {"id":"cka-k-etcd-restore","lvl":8,"dom":"Kubernetes","q":"Restaure le snapshot /opt/backup.db dans le répertoire de données /var/lib/etcd-restore.","explain":"Après la restauration, il faut MODIFIER le static pod /etc/kubernetes/manifests/etcd.yaml pour pointer le volume hostPath sur le nouveau data-dir.","accept":["ETCDCTL_API=3 etcdctl snapshot restore /opt/backup.db --data-dir=/var/lib/etcd-restore","etcdctl snapshot restore /opt/backup.db --data-dir=/var/lib/etcd-restore"]},
  {"id":"cka-k-etcd-members","lvl":9,"dom":"Kubernetes","q":"Liste les membres du cluster etcd (avec les certificats kubeadm).","explain":"Ajoute -w table pour un affichage lisible. Permet de vérifier le quorum d'un etcd multi-nœuds.","accept":["ETCDCTL_API=3 etcdctl member list --endpoints=https://127.0.0.1:2379 --cacert=/etc/kubernetes/pki/etcd/ca.crt --cert=/etc/kubernetes/pki/etcd/server.crt --key=/etc/kubernetes/pki/etcd/server.key","etcdctl member list --endpoints=https://127.0.0.1:2379 --cacert=/etc/kubernetes/pki/etcd/ca.crt --cert=/etc/kubernetes/pki/etcd/server.crt --key=/etc/kubernetes/pki/etcd/server.key"]},
  {"id":"cka-k-kubeadm-upgrade-plan","lvl":7,"dom":"Kubernetes","q":"Affiche les versions vers lesquelles le cluster peut être mis à niveau.","explain":"Ordre d'une montée de version : upgrade plan → upgrade apply sur le control plane → drain → upgrade node → kubelet → uncordon, nœud par nœud.","accept":["kubeadm upgrade plan"]},
  {"id":"cka-k-kubeadm-upgrade-apply","lvl":8,"dom":"Kubernetes","q":"Applique la montée de version du control plane vers la v1.31.1.","explain":"Sur les nœuds workers c'est « kubeadm upgrade node », puis mise à jour du paquet kubelet et systemctl restart kubelet.","accept":["kubeadm upgrade apply v1.31.1"]},
  {"id":"cka-k-kubeadm-token","lvl":9,"dom":"Kubernetes","q":"Régénère la commande complète permettant à un nouveau nœud de rejoindre le cluster.","explain":"Les tokens kubeadm expirent au bout de 24 h : c'est la commande à connaître quand un join échoue avec « token invalide ».","accept":["kubeadm token create --print-join-command"]},
  {"id":"cka-k-csr-approve","lvl":7,"dom":"Kubernetes","q":"Approuve la demande de signature de certificat nommée « john-csr ».","explain":"Workflow : créer la CSR (base64 du .csr dans le manifeste) → kubectl get csr → approve → récupérer le certificat signé dans .status.certificate.","accept":["kubectl certificate approve john-csr"]},
  {"id":"cka-k-cert-check","lvl":8,"dom":"Kubernetes","q":"Vérifie les dates d'expiration de tous les certificats du control plane gérés par kubeadm.","explain":"Un cluster qui refuse soudain toute connexion après un an = certificats expirés. On les renouvelle avec kubeadm certs renew all.","accept":["kubeadm certs check-expiration"]},
  {"id":"cka-k-kubelet-status","lvl":5,"dom":"Kubernetes","q":"Vérifie l'état du service kubelet sur un nœud (systemd).","explain":"Réflexe n°1 sur un nœud NotReady. Puis journalctl -u kubelet pour les logs détaillés.","accept":["systemctl status kubelet"]},
  {"id":"cka-k-kubelet-logs","lvl":6,"dom":"Kubernetes","q":"Affiche les logs du kubelet en suivant les nouvelles lignes en direct.","explain":"Ajoute --no-pager et -n 50 pour un extrait rapide. C'est là qu'apparaissent les erreurs de configuration ou de certificat.","accept":["journalctl -u kubelet -f"]},
  {"id":"cka-k-crictl-ps","lvl":9,"dom":"Kubernetes","q":"Liste les conteneurs en cours sur un nœud via le runtime, quand kubectl ne répond plus.","explain":"crictl ps -a inclut les conteneurs arrêtés. Puis crictl logs <id> pour lire les logs d'un composant du control plane en panne.","accept":["crictl ps"]},
  {"id":"cka-k-get-ep","lvl":4,"dom":"Kubernetes","q":"Vérifie quelles adresses de pods sont derrière le Service « web ».","explain":"Endpoints vide = le selector du Service ne correspond à aucun pod prêt. Diagnostic n°1 d'un Service injoignable.","accept":["kubectl get endpoints web","kubectl get ep web","kubectl get endpointslices -l kubernetes.io/service-name=web"]},
  {"id":"cka-k-port-forward","lvl":5,"dom":"Kubernetes","q":"Redirige le port local 8080 vers le port 80 du Service « web ».","explain":"Permet de tester un Service sans l'exposer. Fonctionne aussi sur un pod : kubectl port-forward pod/web-1 8080:80.","accept":["kubectl port-forward service/web 8080:80","kubectl port-forward svc/web 8080:80"]},
  {"id":"cka-k-dns-test","lvl":7,"dom":"Kubernetes","q":"Depuis un pod jetable, résous le nom du Service « web » du namespace « prod » pour tester le DNS.","explain":"Si nslookup échoue pour tous les services, le problème est CoreDNS. S'il échoue pour un seul, c'est le Service ou son selector.","accept":["kubectl run tmp --image=busybox -it --rm -- nslookup web.prod.svc.cluster.local","kubectl run tmp --image=busybox --rm -it -- nslookup web.prod"]},
  {"id":"cka-k-netpol-get","lvl":6,"dom":"Kubernetes","q":"Liste les NetworkPolicies du namespace « prod ».","explain":"Quand un pod ne joint plus un autre sans raison apparente, vérifier les NetworkPolicies est un réflexe à avoir tôt.","accept":["kubectl get networkpolicies -n prod","kubectl get netpol -n prod"]},
  {"id":"cka-k-get-pv","lvl":4,"dom":"SQL","q":"Liste les PersistentVolumes du cluster.","explain":"Les PV ne sont pas namespacés. Statuts : Available, Bound, Released, Failed.","accept":["kubectl get pv","kubectl get persistentvolumes"]},
  {"id":"cka-k-get-pvc","lvl":5,"dom":"SQL","q":"Liste les PersistentVolumeClaims de tous les namespaces.","explain":"Un PVC bloqué en Pending = pas de PV correspondant, ou StorageClass absente/incorrecte.","accept":["kubectl get pvc -A","kubectl get pvc --all-namespaces"]},
  {"id":"cka-k-sc","lvl":6,"dom":"SQL","q":"Liste les StorageClasses et repère celle marquée par défaut.","explain":"La classe par défaut porte l'annotation storageclass.kubernetes.io/is-default-class=true et apparaît avec « (default) ».","accept":["kubectl get storageclass","kubectl get sc"]},
  {"id":"cka-y-pod-resources","lvl":4,"dom":"Kubernetes","q":"Complète le champ qui encadre requests et limits :","explain":"resources: requests (réservé, utilisé par le scheduler) et limits (plafond). Dépasser la limite mémoire → OOMKilled.","accept":["resources"]},
  {"id":"cka-y-probe-http","lvl":5,"dom":"Kubernetes","q":"Quelle sonde redémarre le conteneur en cas d'échec ?","explain":"livenessProbe redémarre ; readinessProbe retire seulement le pod des Endpoints ; startupProbe protège les démarrages lents.","accept":["livenessProbe","liveness probe"]},
  {"id":"cka-y-probe-ready","lvl":6,"dom":"Kubernetes","q":"Quelle sonde contrôle l'entrée du pod dans les Endpoints du Service ?","explain":"Un pod Running mais 0/1 READY échoue sa readinessProbe : il tourne mais ne reçoit aucun trafic.","accept":["readinessProbe","readiness probe"]},
  {"id":"cka-y-nodeselector","lvl":4,"dom":"Kubernetes","q":"Complète le champ le plus simple pour forcer le placement sur les nœuds portant ce label :","explain":"nodeSelector = égalité stricte. Pour des règles plus riches (OR, opérateurs, préférences), il faut nodeAffinity.","accept":["nodeSelector","node selector"]},
  {"id":"cka-y-toleration","lvl":8,"dom":"Kubernetes","q":"Complète le champ qui permet au pod d'être placé sur un nœud portant ce taint :","explain":"Attention au pluriel : « tolerations » (liste) côté pod, alors que le taint se pose sur le nœud avec kubectl taint.","accept":["tolerations","toleration"]},
  {"id":"cka-y-initcontainer","lvl":5,"dom":"Kubernetes","q":"Complète le champ des conteneurs qui doivent se terminer AVANT le démarrage de l'application :","explain":"Les initContainers s'exécutent séquentiellement jusqu'à complétion. Un pod bloqué en « Init:0/1 » attend un initContainer.","accept":["initContainers","init containers","initcontainer"]},
  {"id":"cka-y-envfrom","lvl":4,"dom":"Kubernetes","q":"Complète le champ qui importe TOUTES les clés en variables d'environnement :","explain":"envFrom évite de lister chaque clé. Les noms de clés deviennent directement les noms de variables.","accept":["envFrom","env from"]},
  {"id":"cka-y-emptydir","lvl":5,"dom":"Kubernetes","q":"Complète le type de volume éphémère lié au cycle de vie du pod :","explain":"emptyDir est créé au démarrage du pod et détruit avec lui. emptyDir: { medium: Memory } le place en RAM (tmpfs).","accept":["emptyDir","empty dir"]},
  {"id":"cka-y-svc-selector","lvl":4,"dom":"Kubernetes","q":"Complète le champ qui désigne les pods à servir :","explain":"Le selector DOIT correspondre aux labels des pods (pas à ceux du Deployment). Une erreur ici = Endpoints vide = Service muet.","accept":["selector"]},
  {"id":"cka-y-sa-pod","lvl":4,"dom":"Kubernetes","q":"Complète le champ qui attache un ServiceAccount précis au pod :","explain":"Attention : le champ est serviceAccountName (l'ancien « serviceAccount » est déprécié). Sans lui, le pod utilise le SA « default ».","accept":["serviceAccountName","service account name"]},
  {"id":"cka-t-pending-cmd","lvl":5,"dom":"Kubernetes","q":"Le pod « web-1 » est Pending. Quelle commande te donne la raison exacte ?","explain":"Le message des Events est explicite : « Insufficient cpu », « node(s) had untolerated taint », « pod has unbound immediate PersistentVolumeClaims »…","accept":["kubectl describe pod web-1","kubectl describe po web-1"]},
  {"id":"cka-t-node-cmd","lvl":4,"dom":"Kubernetes","q":"Affiche les conditions détaillées et les événements du nœud « node01 ».","explain":"Les Conditions (Ready, MemoryPressure, DiskPressure, PIDPressure) et les Events pointent la cause dans la majorité des cas.","accept":["kubectl describe node node01"]},
  {"id":"cka-t-multi-container","lvl":4,"dom":"Kubernetes","q":"Le pod « web-1 » a 3 conteneurs et n'en démarre qu'un. Quelle commande liste précisément l'état de chacun ?","explain":"describe montre pour chaque conteneur son State, Last State, Reason et Exit Code — l'information décisive.","accept":["kubectl describe pod web-1","kubectl get pod web-1 -o yaml","kubectl describe po web-1"]},
  {"id":"cka-t-cluster-info","lvl":5,"dom":"Kubernetes","q":"Affiche les adresses des composants du control plane pour vérifier que le cluster répond.","explain":"kubectl cluster-info dump donne une trace exhaustive, très utile pour un diagnostic profond (mais très verbeuse).","accept":["kubectl cluster-info"]},
  {"id":"cka-t-componentstatus","lvl":6,"dom":"Kubernetes","q":"Vérifie l'état de santé des composants du control plane via l'API de santé.","explain":"componentstatuses est déprécié : préférer kubectl get --raw /healthz (ou /livez, /readyz) qui interroge directement les endpoints de santé.","accept":["kubectl get --raw /healthz","kubectl get --raw='/healthz'","kubectl get componentstatuses","kubectl get cs"]},
  {"id":"az204-v-paas","lvl":2,"dom":"Azure","q":"Modèle cloud où tu ne gères que ton code et tes données — pas l'OS, ni le runtime, ni les serveurs (ex : App Service). Quel est ce modèle (sigle) ?","explain":"PaaS = Platform as a Service. IaaS = tu gères l'OS (VM) ; SaaS = tu utilises juste le logiciel (Office 365).","accept":["paas","platform as a service"]},
  {"id":"az204-v-iaas","lvl":3,"dom":"Azure","q":"Modèle cloud où le fournisseur gère le matériel mais TOI tu gères l'OS, les patchs et le runtime (ex : machines virtuelles). Sigle ?","explain":"IaaS = Infrastructure as a Service — le plus de contrôle, le plus de responsabilité.","accept":["iaas","infrastructure as a service"]},
  {"id":"az204-v-sla","lvl":2,"dom":"Azure","q":"Engagement contractuel de disponibilité d'un service (ex : 99,9 %). Quel sigle ?","explain":"SLA = Service Level Agreement. À savoir : le tier Basic de Redis et le plan Free d'App Service n'ont PAS de SLA.","accept":["sla","service level agreement"]},
  {"id":"az204-v-serverless","lvl":3,"dom":"Azure","q":"Modèle d'exécution où l'infrastructure scale automatiquement (jusqu'à zéro) et où tu paies à l'exécution, sans gérer de serveurs. Quel terme ?","explain":"Serverless : Azure Functions (plan Consumption), Container Apps, APIM Consumption, Cosmos DB serverless…","accept":["serverless","sans serveur"]},
  {"id":"az204-v-coldstart","lvl":1,"dom":"Azure","q":"Latence au premier appel d'une Function quand l'infrastructure doit démarrer une instance à froid. Quel terme (anglais) ?","explain":"Le cold start touche le plan Consumption. Le plan Premium l'élimine grâce aux instances pré-chauffées (pre-warmed).","accept":["cold start","coldstart","demarrage a froid"]},
  {"id":"az204-v-rg","lvl":2,"dom":"Azure","q":"Conteneur logique Azure qui regroupe des ressources partageant le même cycle de vie (créé avec « az group create »). Quel nom ?","explain":"Le resource group : supprimer le groupe supprime tout ce qu'il contient. Toute ressource vit dans exactement un groupe.","accept":["resource group","groupe de ressources","ressource group"]},
  {"id":"az204-v-mi","lvl":2,"dom":"Sécurité","q":"Identité Azure attribuée automatiquement à une ressource (app, VM…) pour s'authentifier SANS stocker de secret dans le code. Quel nom ?","explain":"La managed identity est LA réponse à « éliminer les credentials du code ». Deux types : system-assigned et user-assigned.","accept":["managed identity","identite managee","identite geree","managed identities"]},
  {"id":"az204-v-vnet","lvl":3,"dom":"Réseau","q":"Réseau privé virtuel dans Azure où tu isoles tes ressources. Quel nom court ?","explain":"VNet = Virtual Network. Pour AZ-204 : l'intégration VNet des Functions exige le plan Premium ou Dedicated.","accept":["vnet","virtual network","reseau virtuel"]},
  {"id":"az204-v-ru","lvl":3,"dom":"Azure","q":"Unité qui mesure le coût de chaque opération dans Cosmos DB (1 unité ≈ lecture d'un item de 1 Ko). Quel sigle ?","explain":"RU = Request Unit. On provisionne des RU/s (manuel ou autoscale) ou on paie à la conso (serverless). Dépassement → erreur 429.","accept":["ru","request unit","request units","ru s","unite de requete"]},
  {"id":"az204-v-ttl","lvl":1,"dom":"Azure","q":"Durée de vie au bout de laquelle une donnée (message, document, entrée de cache) expire automatiquement. Quel sigle ?","explain":"TTL = Time To Live. Présent partout : Cosmos DB, Redis, files de messages, CDN…","accept":["ttl","time to live"]},
  {"id":"az204-v-fifo","lvl":2,"dom":"Azure","q":"Ordre de traitement où le premier message arrivé est le premier traité. Quel sigle ?","explain":"FIFO = First In, First Out. Dans Service Bus, le FIFO strict est garanti par les sessions.","accept":["fifo","first in first out"]},
  {"id":"az204-v-dlq","lvl":3,"dom":"Azure","q":"File spéciale où atterrissent les messages impossibles à traiter (trop d'échecs, TTL expiré). Quel nom (sigle ou complet) ?","explain":"La Dead-Letter Queue. Dans Service Bus elle est automatique ; dans Event Grid il faut l'activer (vers un blob storage).","accept":["dlq","dead letter queue","dead letter","file de lettres mortes"]},
  {"id":"az204-v-sas","lvl":2,"dom":"Sécurité","q":"URL signée qui accorde un accès limité (permissions + durée) à une ressource de stockage sans partager la clé du compte. Quel sigle ?","explain":"SAS = Shared Access Signature. Trois types : user delegation (Entra ID, la plus sûre), service, account.","accept":["sas","shared access signature"]},
  {"id":"az204-v-jwt","lvl":3,"dom":"Sécurité","q":"Format de token signé, en 3 parties séparées par des points (header.payload.signature), utilisé par OAuth/OIDC. Quel sigle ?","explain":"JWT = JSON Web Token. Le payload contient les claims : aud (audience), iss (émetteur), exp (expiration), scp, roles…","accept":["jwt","json web token"]},
  {"id":"az204-v-entra","lvl":3,"dom":"Sécurité","q":"Quel est le nouveau nom d'Azure Active Directory (Azure AD) ?","explain":"Azure AD s'appelle Microsoft Entra ID depuis 2023. L'examen utilise le nouveau nom.","accept":["microsoft entra id","entra id","entra"]},
  {"id":"az204-v-kv","lvl":1,"dom":"Sécurité","q":"Service Azure qui stocke secrets, clés cryptographiques et certificats de façon centralisée et sécurisée. Quel nom ?","explain":"Azure Key Vault. Les 3 types d'objets : secrets, keys, certificates.","accept":["key vault","azure key vault","keyvault"]},
  {"id":"az204-v-kql","lvl":1,"dom":"Observabilité","q":"Langage de requête utilisé dans Log Analytics / Application Insights (mot-clés : where, summarize, ago…). Quel nom ou sigle ?","explain":"KQL = Kusto Query Language. Ex : requests | where success == false | summarize count() by name","accept":["kql","kusto","kusto query language"]},
  {"id":"az204-v-cdn","lvl":2,"dom":"Azure","q":"Réseau de serveurs répartis dans le monde qui met en cache le contenu statique au plus près des utilisateurs. Quel sigle ?","explain":"CDN = Content Delivery Network. Les serveurs edge s'appellent des POP (Points of Presence).","accept":["cdn","content delivery network"]},
  {"id":"az204-v-webhook","lvl":3,"dom":"Azure","q":"Mécanisme où un service t'appelle en HTTP POST sur une URL que tu exposes quand un événement se produit (mode push). Quel terme ?","explain":"Le webhook. Event Grid livre ses événements par webhook — après un handshake de validation.","accept":["webhook","web hook"]},
  {"id":"az204-v-pubsub","lvl":2,"dom":"Azure","q":"Patron de messagerie où un émetteur publie et où PLUSIEURS abonnés reçoivent chacun leur copie. Quel nom (anglais, avec un /) ?","explain":"Pub/Sub. Dans Service Bus : topics + subscriptions. Dans Event Grid : topics + event subscriptions.","accept":["pub sub","publish subscribe","pubsub","publisher subscriber"]},
  {"id":"az204-v-partkey","lvl":3,"dom":"Azure","q":"Propriété d'un document Cosmos DB qui détermine sa répartition physique entre les partitions. Quel nom ?","explain":"La partition key. À choisir avec une haute cardinalité — et elle est immuable après création du conteneur.","accept":["partition key","cle de partition","partitionkey"]},
  {"id":"az204-v-patch","lvl":2,"dom":"Azure","q":"Quelle méthode HTTP est prévue pour une mise à jour PARTIELLE d'une ressource REST ?","explain":"PATCH = partiel, PUT = remplacement complet, POST = création, DELETE = suppression, GET = lecture.","accept":["patch"]},
  {"id":"az204-v-429","lvl":1,"dom":"Azure","q":"Quel code HTTP signifie « trop de requêtes, ralentis » (renvoyé par Cosmos DB, Microsoft Graph, APIM rate-limit…) ?","explain":"429 Too Many Requests. La bonne réaction : attendre la durée du header Retry-After puis réessayer.","accept":["429","429 too many requests","too many requests"]},
  {"id":"az204-v-202","lvl":2,"dom":"Azure","q":"Quel code HTTP signifie « requête acceptée, traitement asynchrone en cours » (utilisé par le pattern async HTTP API des Durable Functions) ?","explain":"202 Accepted + une URL de statut à poller. C'est le pattern « Async HTTP APIs » des Durable Functions.","accept":["202","202 accepted","accepted"]},
  {"id":"az204-v-azlogin","lvl":3,"dom":"Azure","q":"Quelle commande Azure CLI permet de se connecter à son compte Azure ?","explain":"az login ouvre le navigateur pour s'authentifier. Ensuite : az account set --subscription pour choisir l'abonnement.","accept":["az login"]},
  {"id":"az204-v-acr","lvl":2,"dom":"Docker","q":"Service Azure privé où tu stockes et distribues tes images Docker. Quel nom (sigle accepté) ?","explain":"ACR = Azure Container Registry. Équivalent privé de Docker Hub, avec build cloud (az acr build) et ACR Tasks.","accept":["acr","azure container registry","container registry"]},
  {"id":"az204-v-slot","lvl":3,"dom":"Azure","q":"Environnement parallèle d'une App Service (ex : staging) qu'on peut échanger avec la production sans downtime. Quel nom (français ou anglais) ?","explain":"Le deployment slot. L'échange s'appelle un swap — avec préchauffage, donc zéro downtime.","accept":["deployment slot","slot","slot de deploiement","emplacement de deploiement"]},
  {"id":"az204-f-timeout-cons","lvl":5,"dom":"Azure","q":"Timeout PAR DÉFAUT d'une Azure Function en plan Consumption (en minutes) ?","explain":"5 minutes par défaut, extensible à 10 max en Consumption. Besoin de plus ? → plan Premium, Flex Consumption ou Dedicated.","accept":["5","5 min","5 minutes","cinq"]},
  {"id":"az204-f-timeout-max","lvl":6,"dom":"Azure","q":"Timeout MAXIMUM d'une Function en plan Consumption classique (en minutes) ?","explain":"10 minutes maximum. C'est LE chiffre qui déclenche « il faut changer de plan » dans les scénarios d'examen.","accept":["10","10 min","10 minutes","dix"]},
  {"id":"az204-f-plan-nocold","lvl":4,"dom":"Azure","q":"Quel plan d'hébergement Functions élimine les cold starts grâce aux instances pré-chauffées ?","explain":"Le plan Premium (EP1–EP3) : instances pre-warmed, VNet, durée illimitée. Les mots-clés « cold start » ou « VNet » à l'examen → Premium.","accept":["premium","plan premium","elastic premium"]},
  {"id":"az204-f-ncrontab","lvl":6,"dom":"Azure","q":"Combien de champs contient une expression NCRONTAB de trigger Timer (contrairement au cron Unix) ?","explain":"6 champs : {seconde} {minute} {heure} {jour} {mois} {jour-semaine}. Ex : 0 */5 * * * * = toutes les 5 minutes.","accept":["6","six"]},
  {"id":"az204-f-slots-std","lvl":4,"dom":"Azure","q":"Combien de deployment slots offre le plan App Service STANDARD ?","explain":"Standard = 5 slots, Premium et Isolated = 20. Free/Shared/Basic = 0. « Slots au moindre coût » → Standard.","accept":["5","cinq"]},
  {"id":"az204-f-slots-prem","lvl":5,"dom":"Azure","q":"Combien de deployment slots offre le plan App Service PREMIUM ?","explain":"Premium = 20 slots (comme Isolated). Standard = 5.","accept":["20","vingt"]},
  {"id":"az204-f-autoscale-tier","lvl":6,"dom":"Azure","q":"Quel est le PREMIER plan App Service (le moins cher) qui permet l'autoscale ?","explain":"Autoscale à partir de Standard. Basic ne permet que le scale manuel (3 instances max).","accept":["standard","s1","plan standard"]},
  {"id":"az204-f-autoswap-os","lvl":4,"dom":"Azure","q":"L'auto swap des deployment slots n'est supporté que sur un seul OS. Lequel ?","explain":"Auto swap = Windows uniquement. Sur Linux, il faut swapper manuellement (ou via pipeline).","accept":["windows"]},
  {"id":"az204-f-acr-geo","lvl":4,"dom":"Docker","q":"Quel SKU d'Azure Container Registry est requis pour la geo-replication et le private link ?","explain":"ACR Premium uniquement. Basic = dev, Standard = prod simple.","accept":["premium"]},
  {"id":"az204-f-aci-os","lvl":5,"dom":"Docker","q":"Les container groups ACI multi-conteneurs ne sont supportés que sur un seul OS. Lequel ?","explain":"Multi-conteneurs (sidecar) = Linux uniquement. Windows = un seul conteneur par groupe. Idem pour le montage Azure Files : Linux only.","accept":["linux"]},
  {"id":"az204-f-aci-restart","lvl":6,"dom":"Docker","q":"Quelle est la restart policy PAR DÉFAUT d'un conteneur ACI ?","explain":"Always (pour les services). OnFailure = tâches à réessayer, Never = exécution unique.","accept":["always"]},
  {"id":"az204-f-ca-keda","lvl":4,"dom":"Docker","q":"Quelle technologie open source gère l'autoscaling événementiel dans Azure Container Apps ?","explain":"KEDA (Kubernetes Event-Driven Autoscaling) : scale sur HTTP, files Service Bus, Event Hubs… jusqu'à zéro. Dapr gère la partie microservices.","accept":["keda"]},
  {"id":"az204-f-cool-min","lvl":5,"dom":"Azure","q":"Durée minimale de rétention du tier Cool avant frais de suppression anticipée (en jours) ?","explain":"Cool = 30 jours, Cold = 90, Archive = 180. Supprimer/changer de tier avant → pénalité.","accept":["30","30 jours","trente"]},
  {"id":"az204-f-archive-min","lvl":6,"dom":"Azure","q":"Durée minimale de rétention du tier Archive (en jours) ?","explain":"180 jours. Et Archive est OFFLINE : lecture impossible sans réhydratation préalable.","accept":["180","180 jours"]},
  {"id":"az204-f-rehydrate","lvl":4,"dom":"Azure","q":"Durée maximale d'une réhydratation d'un blob Archive en priorité STANDARD (en heures) ?","explain":"Standard : jusqu'à 15 h. High priority : < 1 h pour les blobs < 10 Go (plus cher).","accept":["15","15 h","15 heures","jusqu a 15"]},
  {"id":"az204-f-ragrs","lvl":5,"dom":"Azure","q":"Quelle option de redondance permet de LIRE les données sur la région secondaire (sigle) ?","explain":"RA-GRS (ou RA-GZRS) : Read-Access Geo-Redundant Storage — endpoint « -secondary » accessible en lecture.","accept":["RA-GRS","ra grs","ragrs","ra gzrs","ragzrs","read access grs"]},
  {"id":"az204-f-lease","lvl":6,"dom":"Azure","q":"Mécanisme de verrou EXCLUSIF d'écriture sur un blob (concurrence pessimiste), d'une durée de 15 à 60 s ou infinie ?","explain":"Le lease. Concurrence optimiste = ETag + If-Match ; pessimiste = lease.","accept":["lease","bail"]},
  {"id":"az204-f-cosmos-default","lvl":5,"dom":"Azure","q":"Quel est le niveau de cohérence PAR DÉFAUT d'un compte Cosmos DB ?","explain":"Session : cohérence « read your own writes » dans sa propre session. Le meilleur compromis perf/cohérence.","accept":["session"]},
  {"id":"az204-f-cosmos-bounded","lvl":6,"dom":"Azure","q":"Quel niveau de cohérence Cosmos garantit un retard de réplication BORNÉ (K versions ou T secondes max) ?","explain":"Bounded staleness — le niveau à choisir quand l'énoncé parle de « lag maximal garanti » avec distribution globale.","accept":["bounded staleness","bounded","obsolescence limitee"]},
  {"id":"az204-f-cosmos-partmax","lvl":4,"dom":"Azure","q":"Taille maximale d'une partition LOGIQUE dans Cosmos DB (en Go) ?","explain":"20 Go par partition logique. Si ta partition key concentre trop de données sur une valeur → hot partition + plafond atteint.","accept":["20","20 go","20 gb"]},
  {"id":"az204-f-cosmos-429","lvl":5,"dom":"Azure","q":"Quel code HTTP renvoie Cosmos DB quand tu dépasses les RU/s provisionnées ?","explain":"429 avec le header x-ms-retry-after-ms. Le SDK réessaie automatiquement (MaxRetryAttemptsOnRateLimitedRequests).","accept":["429","429 too many requests"]},
  {"id":"az204-f-cosmos-sproc","lvl":6,"dom":"Azure","q":"Dans quel langage s'écrivent les stored procedures, triggers et UDF de Cosmos DB ?","explain":"JavaScript, exécuté côté serveur dans une transaction limitée à UNE partition logique.","accept":["javascript","js"]},
  {"id":"az204-f-msal-public","lvl":6,"dom":"Sécurité","q":"Quelle classe MSAL utilise-t-on pour une app desktop/mobile qui ne peut PAS garder de secret ?","explain":"PublicClientApplication. Les web apps et daemons (qui ont un secret/certificat) utilisent ConfidentialClientApplication.","accept":["publicclientapplication","public client application","public client"]},
  {"id":"az204-f-flow-daemon","lvl":4,"dom":"Sécurité","q":"Quel flow OAuth 2.0 utilise un daemon/service sans utilisateur connecté ?","explain":"Client credentials : l'app s'authentifie elle-même (secret/certificat) avec des permissions APPLICATION et un scope /.default.","accept":["client credentials","client credential"]},
  {"id":"az204-f-scope-default","lvl":5,"dom":"Sécurité","q":"Avec le flow client credentials, le scope se termine obligatoirement par quel suffixe ?","explain":"ressource/.default (ex : https://graph.microsoft.com/.default) — jamais un scope granulaire comme User.Read.","accept":["/.default",".default","default"]},
  {"id":"az204-f-claim-app","lvl":6,"dom":"Sécurité","q":"Dans un access token, quel claim contient les permissions APPLICATION (daemon) — par opposition à « scp » pour les déléguées ?","explain":"roles = permissions d'application (admin consent obligatoire) ; scp = permissions déléguées (utilisateur connecté).","accept":["roles","role"]},
  {"id":"az204-f-sas-safe","lvl":4,"dom":"Sécurité","q":"Quel type de SAS est signé avec des credentials Microsoft Entra ID (recommandé par Microsoft) ?","explain":"User delegation SAS — blobs uniquement, révocable, pas besoin de la clé du compte de stockage.","accept":["user delegation","user delegation sas","delegation d utilisateur"]},
  {"id":"az204-f-sap-max","lvl":5,"dom":"Sécurité","q":"Combien de stored access policies maximum par conteneur blob ?","explain":"5 par conteneur. Elles centralisent début/expiration/permissions et permettent de révoquer les SAS liées.","accept":["5","cinq"]},
  {"id":"az204-f-kv-retention","lvl":6,"dom":"Azure","q":"Durée de rétention PAR DÉFAUT du soft delete de Key Vault (en jours) ?","explain":"90 jours par défaut (configurable 7–90). La purge protection empêche toute suppression définitive pendant cette période — et est irréversible.","accept":["90","90 jours"]},
  {"id":"az204-f-mi-shared","lvl":4,"dom":"Sécurité","q":"Quel type de managed identity peut être partagé entre plusieurs ressources Azure ?","explain":"User-assigned : ressource autonome, réutilisable sur N apps/VMs. System-assigned : liée 1:1 à sa ressource, supprimée avec elle.","accept":["user assigned","user assigned managed identity","affectee par l utilisateur","user"]},
  {"id":"az204-f-dac","lvl":5,"dom":"Sécurité","q":"Quelle classe du SDK Azure essaie en chaîne : variables d'env → managed identity → Azure CLI… (même code en local et en prod) ?","explain":"DefaultAzureCredential (package Azure.Identity). En local elle utilise az login ; en prod la managed identity. Zéro secret dans le code.","accept":["defaultazurecredential","default azure credential"]},
  {"id":"az204-f-ai-tests","lvl":6,"dom":"Observabilité","q":"Nombre maximum de tests de disponibilité (availability tests) par ressource Application Insights ?","explain":"100 tests max. Recommandation : tester depuis au moins 5 régions différentes.","accept":["100","cent"]},
  {"id":"az204-f-ai-sampling","lvl":4,"dom":"Observabilité","q":"Quel type de sampling est activé PAR DÉFAUT dans le SDK ASP.NET d'Application Insights ?","explain":"Adaptive sampling : ajuste automatiquement le volume de télémétrie. Les autres : fixed-rate (taux fixe) et ingestion (côté service).","accept":["adaptive","adaptatif","adaptive sampling"]},
  {"id":"az204-f-redis-port","lvl":5,"dom":"Azure","q":"Sur quel port Azure Cache for Redis accepte-t-il les connexions TLS/SSL ?","explain":"6380 (TLS). Le port 6379 non chiffré est désactivé par défaut.","accept":["6380"]},
  {"id":"az204-f-redis-evict","lvl":6,"dom":"Azure","q":"Quelle est la politique d'éviction PAR DÉFAUT de Redis quand la mémoire est pleine ?","explain":"volatile-lru : évince les clés AVEC expiration les moins récemment utilisées. allkeys-lru éviverait toutes les clés.","accept":["volatile-lru","volatile lru","volatilelru"]},
  {"id":"az204-f-cdn-ttl","lvl":4,"dom":"Azure","q":"TTL par défaut du cache Azure CDN (web delivery) si l'origine n'envoie pas de Cache-Control (en jours) ?","explain":"7 jours. Pour invalider avant expiration : purge de l'endpoint.","accept":["7","7 jours","sept"]},
  {"id":"az204-f-apim-header","lvl":5,"dom":"Azure","q":"Quel header HTTP transporte la clé de souscription APIM ?","explain":"Ocp-Apim-Subscription-Key (ou query string « subscription-key »). Sans clé valide sur un product protégé → 401.","accept":["Ocp-Apim-Subscription-Key","ocp apim subscription key","ocpapimsubscriptionkey"]},
  {"id":"az204-f-apim-serverless","lvl":6,"dom":"Azure","q":"Quel tier APIM est serverless, facturé à l'appel, mais sans developer portal ?","explain":"Consumption. Premium = VNet + multi-région ; Developer = complet mais sans SLA.","accept":["consumption","conso"]},
  {"id":"az204-f-eg-size","lvl":5,"dom":"Azure","q":"Taille maximale d'un événement Event Grid (en Mo) ?","explain":"1 Mo max, facturé par tranches de 64 Ko.","accept":["1","1 mo","1 mb"]},
  {"id":"az204-f-eg-retry","lvl":6,"dom":"Azure","q":"Pendant combien de temps maximum Event Grid réessaie-t-il de livrer un événement (en heures) ?","explain":"Backoff exponentiel jusqu'à 24 h, puis abandon — ou dead-letter vers un blob storage si configuré.","accept":["24","24 h","24 heures"]},
  {"id":"az204-f-eh-retention","lvl":4,"dom":"Azure","q":"Rétention maximale des événements dans Event Hubs tier STANDARD (en jours) ?","explain":"1 à 7 jours en Standard (défaut 1). Ce n'est PAS un stockage long terme → utiliser Capture pour archiver.","accept":["7","7 jours","sept"]},
  {"id":"az204-f-eh-partmax","lvl":5,"dom":"Azure","q":"Nombre maximum de partitions d'un Event Hub en tier Standard ?","explain":"32 partitions max en Standard (défaut 4). Le nombre est fixé à la création — impossible à réduire ensuite.","accept":["32","trente deux"]},
  {"id":"az204-f-eh-capture","lvl":6,"dom":"Azure","q":"Quelle fonctionnalité d'Event Hubs archive automatiquement le flux vers Blob Storage / Data Lake sans écrire de code ?","explain":"Capture : format Avro, déclenché par taille ou durée. LA réponse à « conserver les événements à long terme ».","accept":["capture","event hubs capture"]},
  {"id":"az204-f-sb-size","lvl":4,"dom":"Azure","q":"Taille maximale d'un message Service Bus en tier STANDARD (en Ko) ?","explain":"256 Ko en Standard, jusqu'à 100 Mo en Premium. À comparer : Queue Storage = 64 Ko.","accept":["256","256 ko","256 kb"]},
  {"id":"az204-f-sb-maxdeliv","lvl":5,"dom":"Azure","q":"Valeur par défaut du MaxDeliveryCount avant qu'un message Service Bus parte en dead-letter ?","explain":"10 tentatives. Autres causes de DLQ automatique : TTL expiré, erreur d'évaluation de filtre.","accept":["10","dix"]},
  {"id":"az204-f-sb-fifo","lvl":6,"dom":"Azure","q":"Quelle fonctionnalité de Service Bus garantit le FIFO strict et l'affinité de consommateur ?","explain":"Les sessions (SessionId sur les messages). Sans sessions, l'ordre n'est pas garanti.","accept":["sessions","session","les sessions"]},
  {"id":"az204-f-qs-size","lvl":5,"dom":"Azure","q":"Taille maximale d'un message Azure Queue Storage (en Ko) ?","explain":"64 Ko seulement — mais une capacité totale énorme (celle du compte de stockage, > 500 To).","accept":["64","64 ko","64 kb"]},
  {"id":"az204-f-qs-visibility","lvl":6,"dom":"Azure","q":"Durée par défaut du visibility timeout d'un message Queue Storage (en secondes) ?","explain":"30 secondes : le message redevient visible s'il n'est pas supprimé à temps. Le consommateur doit Receive PUIS Delete explicitement.","accept":["30","30 s","30 secondes","trente"]},
  {"id":"az204-s-slots-cheap","lvl":8,"dom":"Azure","q":"Ton app a besoin de deployment slots et d'autoscale, au COÛT MINIMUM. Quel plan App Service choisis-tu ?","explain":"Standard : premier tier avec slots (5) ET autoscale. Ne choisis Premium que si l'énoncé exige plus de 5 slots, plus de perf ou du VNet avancé.","accept":["standard","s1","plan standard"]},
  {"id":"az204-s-creds-code","lvl":7,"dom":"Sécurité","q":"L'audit exige de supprimer TOUTES les credentials (connection strings, secrets) du code et de la config pour accéder à Key Vault. Quelle fonctionnalité Azure utilises-tu ?","explain":"Managed identity + RBAC sur Key Vault + DefaultAzureCredential dans le code. Aucun secret nulle part.","accept":["managed identity","identite managee","identite geree","managed identities"]},
  {"id":"az204-s-mi-fleet","lvl":8,"dom":"Sécurité","q":"10 App Services doivent partager exactement les MÊMES permissions vers Key Vault, gérées en un seul endroit. Quel type de managed identity ?","explain":"Une seule user-assigned identity attachée aux 10 apps : un seul role assignment à gérer. System-assigned créerait 10 identités à autoriser une par une.","accept":["user assigned","user assigned managed identity","user"]},
  {"id":"az204-s-cosmos-ryow","lvl":9,"dom":"Azure","q":"Un utilisateur doit toujours voir immédiatement SES propres écritures, sans payer le prix de la cohérence forte. Quel niveau de cohérence ?","explain":"Session = read your own writes, dans la même session. C'est aussi le défaut de Cosmos DB.","accept":["session"]},
  {"id":"az204-s-cosmos-lag","lvl":7,"dom":"Azure","q":"Application multi-régions : les lectures ne doivent jamais avoir plus de 5 secondes de retard sur les écritures. Quel niveau de cohérence ?","explain":"Bounded staleness borne le retard (T secondes ou K versions). Strong serait trop coûteux en multi-régions ; session ne borne pas le lag global.","accept":["bounded staleness","bounded"]},
  {"id":"az204-s-queue-80gb","lvl":9,"dom":"Azure","q":"Il te faut une file simple qui stockera plus de 80 Go de messages, au moindre coût, sans besoin d'ordre ni de pub/sub. Quel service ?","explain":"Queue Storage : capacité quasi illimitée (celle du compte), très économique. Service Bus plafonne à 80 Go max par entité.","accept":["queue storage","azure queue storage","storage queue","file de stockage","queue"]},
  {"id":"az204-s-blob-react","lvl":7,"dom":"Azure","q":"Tu dois déclencher un traitement dès qu'un blob est créé dans un compte de stockage, en mode push serverless. Quel service d'événements ?","explain":"Event Grid : system topic du compte de stockage, événement Microsoft.Storage.BlobCreated, handler = Function/webhook. Réactif et facturé à l'événement.","accept":["event grid","eventgrid","azure event grid"]},
  {"id":"az204-s-iot-stream","lvl":8,"dom":"Azure","q":"Des milliers de capteurs envoient 1 million d'événements par seconde à analyser en streaming (compatible Kafka). Quel service d'ingestion ?","explain":"Event Hubs : conçu pour l'ingestion massive, partitions, consumer groups, endpoint Kafka. Event Grid = événements discrets, pas du streaming.","accept":["event hubs","event hub","azure event hubs","eventhub","eventhubs"]},
  {"id":"az204-s-eh-archive","lvl":9,"dom":"Azure","q":"Le flux Event Hubs doit être archivé automatiquement dans Data Lake SANS écrire de code. Quelle fonctionnalité ?","explain":"Event Hubs Capture — archive en Avro vers Blob/ADLS, par fenêtre de taille ou de temps.","accept":["capture","event hubs capture"]},
  {"id":"az204-s-livemetrics","lvl":8,"dom":"Observabilité","q":"Pendant un déploiement, tu veux surveiller les requêtes/échecs en quasi temps réel (~1 s) SANS consommer de stockage. Quelle fonctionnalité d'App Insights ?","explain":"Live Metrics : latence ~1 seconde, données non persistées, aucun impact sur les coûts de stockage.","accept":["live metrics","livemetrics","live metrics stream","metriques en direct"]},
  {"id":"az204-s-sas-revoke","lvl":9,"dom":"Sécurité","q":"Tu dois pouvoir RÉVOQUER des SAS distribuées à des partenaires sans régénérer la clé du compte de stockage. Que fallait-il associer aux SAS ?","explain":"Une stored access policy sur le conteneur : supprimer/modifier la policy révoque toutes les SAS qui y sont liées.","accept":["stored access policy","stored access policies","politique d acces stockee"]},
  {"id":"az204-s-apim-mock","lvl":9,"dom":"Azure","q":"Le backend n'est pas encore développé mais les équipes front doivent tester l'API. Quelle policy APIM renvoie des réponses simulées ?","explain":"mock-response : renvoie les exemples/schémas définis dans la spec de l'API sans appeler de backend.","accept":["mock response","mock-response","mockresponse","mock"]},
  {"id":"az204-s-apim-jwt","lvl":7,"dom":"Azure","q":"Chaque requête entrante doit présenter un token Entra ID valide, rejeté en 401 sinon — sans modifier le backend. Quelle policy APIM ?","explain":"validate-jwt en inbound, avec l'openid-config du tenant. Le backend reste inchangé : APIM fait le travail.","accept":["validate jwt","validate-jwt","validatejwt"]},
  {"id":"az204-s-acr-build","lvl":9,"dom":"Docker","q":"Tu dois builder une image Docker et la pousser dans ACR depuis une machine SANS Docker installé. Quelle commande CLI (3 mots) ?","explain":"az acr build -r monregistry -t app:v1 . — le build s'exécute dans le cloud (ACR Tasks) puis l'image est poussée automatiquement.","accept":["az acr build"]},
  {"id":"az204-s-cosmos-ttl","lvl":8,"dom":"Azure","q":"Les documents d'un conteneur Cosmos doivent être supprimés automatiquement 30 jours après leur dernière modification. Quelle fonctionnalité ?","explain":"TTL au niveau conteneur (2592000 s) — la suppression est gratuite en RU prioritaires (best effort avec les RU restantes).","accept":["ttl","time to live"]},
  {"id":"az204-s-graph-select","lvl":9,"dom":"Azure","q":"Quel query parameter OData limite les champs renvoyés par Microsoft Graph (ex : ne récupérer que displayName et mail) ?","explain":"$select=displayName,mail — réduit la taille des réponses et le risque de throttling. $filter filtre les lignes, $select les colonnes.","accept":["select","$select"]},
  {"id":"az204-s-cacheaside","lvl":9,"dom":"Azure","q":"Pattern de cache : lire le cache ; si absent, lire la base puis peupler le cache avec un TTL. Quel nom (anglais) ?","explain":"Cache-aside — LE pattern à connaître. Attention aussi : le ConnectionMultiplexer StackExchange.Redis doit être un singleton réutilisé.","accept":["cache aside","cache-aside","cacheaside"]},
  {"id":"az204-s-cdn-update","lvl":7,"dom":"Azure","q":"Tu déploies une nouvelle version de tes fichiers JS mais le CDN sert encore l'ancienne. Quelle action pour forcer la mise à jour immédiate ?","explain":"Purge de l'endpoint CDN (ou versionner les URLs des assets). Sinon il faut attendre l'expiration du TTL.","accept":["purge","purger","purge du cache","purge de l endpoint"]},
  {"id":"az204-v-tenant","lvl":1,"dom":"Sécurité","q":"Instance dédiée de Microsoft Entra ID qui représente une organisation et contient ses utilisateurs, groupes et app registrations. Quel nom ?","explain":"Le tenant. Une app « multitenant » peut être utilisée par les utilisateurs d'autres organisations. Chaque tenant a un ID (GUID) et un domaine *.onmicrosoft.com.","accept":["tenant","locataire"]},
  {"id":"az204-v-subscription","lvl":2,"dom":"Azure","q":"Conteneur de FACTURATION Azure auquel sont rattachées toutes les ressources (tu en as un actif pour t'entraîner). Quel nom ?","explain":"La subscription. Hiérarchie : tenant → subscriptions → resource groups → ressources. La facture tombe au niveau de la subscription.","accept":["subscription","abonnement","souscription"]},
  {"id":"az204-v-rest","lvl":1,"dom":"Azure","q":"Style d'architecture d'API basé sur HTTP : des ressources identifiées par des URLs et manipulées via GET/POST/PUT/DELETE. Quel sigle ?","explain":"REST. Toutes les APIs Azure sont REST — les SDK et la CLI ne sont que des enrobages par-dessus.","accept":["rest","restful","representational state transfer"]},
  {"id":"az204-v-cors","lvl":2,"dom":"Azure","q":"Mécanisme de sécurité des navigateurs qui bloque les appels JavaScript vers un AUTRE domaine, sauf si le serveur les autorise explicitement. Quel sigle ?","explain":"CORS = Cross-Origin Resource Sharing. À configurer côté serveur (App Service, Functions, APIM policy cors, compte de stockage) quand une SPA appelle ton API.","accept":["cors","cross origin resource sharing"]},
  {"id":"az204-v-scopedef","lvl":2,"dom":"Sécurité","q":"Permission granulaire qu'une application demande (ex : « User.Read » pour lire le profil). Quel terme anglais ?","explain":"Le scope. Demandé à l'acquisition du token, il apparaît dans le claim « scp » (délégué). Consentement statique (/.default) ou incrémental.","accept":["scope","scopes","etendue"]},
  {"id":"az204-v-claimdef","lvl":3,"dom":"Sécurité","q":"Information portée par un token JWT : aud, iss, exp, scp, roles… Comment s'appelle chacune de ces paires ?","explain":"Un claim. aud = à qui le token est destiné, iss = qui l'a émis, exp = expiration, scp/roles = permissions.","accept":["claim","claims","revendication"]},
  {"id":"az204-v-bicep","lvl":2,"dom":"Terraform","q":"Langage déclaratif de Microsoft qui simplifie l'écriture des templates ARM pour déployer l'infrastructure « as code ». Quel nom ?","explain":"Bicep se compile en JSON ARM. Infrastructure as Code = décrire les ressources dans des fichiers versionnés au lieu de cliquer dans le portail.","accept":["bicep"]},
  {"id":"az204-v-snapshot","lvl":2,"dom":"Azure","q":"Copie en LECTURE SEULE d'un blob figée à un instant T, stockée à côté de l'original. Quel terme anglais ?","explain":"Le snapshot (manuel, à la demande) — à distinguer du versioning (automatique à chaque écriture, si activé).","accept":["snapshot","instantane"]},
  {"id":"az204-v-dockerfile","lvl":3,"dom":"Docker","q":"Fichier texte qui décrit les étapes de construction d'une image de conteneur (FROM, COPY, RUN, CMD…). Quel nom ?","explain":"Le Dockerfile. az acr build l'utilise pour builder dans le cloud. FROM = image de base — sa mise à jour peut déclencher un ACR Task automatique.","accept":["dockerfile","docker file"]},
  {"id":"az204-v-appserviceplan","lvl":1,"dom":"Azure","q":"Ressource qui définit les machines sous-jacentes (SKU, région, nombre d'instances) et que PLUSIEURS web apps peuvent partager. Quel nom ?","explain":"L'App Service plan. On scale le PLAN, pas l'app : toutes les apps du plan partagent (et se disputent) ses instances.","accept":["app service plan","plan app service","appservice plan","service plan"]},
  {"id":"az204-f-workerruntime","lvl":4,"dom":"Azure","q":"Quel app setting indique au runtime Functions le langage utilisé (dotnet-isolated, node, python…) ?","explain":"FUNCTIONS_WORKER_RUNTIME. Avec AzureWebJobsStorage et FUNCTIONS_EXTENSION_VERSION, c'est un des settings clés d'une Function App.","accept":["FUNCTIONS_WORKER_RUNTIME","functions worker runtime"]},
  {"id":"az204-f-taskhub","lvl":5,"dom":"Azure","q":"Comment s'appelle l'espace de stockage (dans le storage account) où Durable Functions persiste l'état des orchestrations ?","explain":"Le task hub : queues + tables + blobs qui portent l'historique. Deux apps partageant un storage doivent avoir des task hubs différents.","accept":["task hub","taskhub"]},
  {"id":"az204-f-coretools","lvl":6,"dom":"Azure","q":"Quel outil en ligne de commande permet de créer et d'exécuter des Azure Functions EN LOCAL (commandes func init, func start) ?","explain":"Azure Functions Core Tools. func init → func new → func start, puis func azure functionapp publish pour déployer.","accept":["core tools","azure functions core tools","func"]},
  {"id":"az204-f-storagev2","lvl":6,"dom":"Azure","q":"Quel « kind » de compte de stockage est recommandé aujourd'hui pour un usage général (blobs + files + queues + tables, tous les tiers) ?","explain":"StorageV2 (general-purpose v2). Les comptes Premium (block blob, page blob, file) sont des cas de perf spécifiques.","accept":["storagev2","storage v2","general purpose v2","gpv2","standard general purpose v2"]},
  {"id":"az204-f-cosmos-serverless","lvl":4,"dom":"Azure","q":"Quel mode de facturation Cosmos DB ne provisionne AUCUN RU/s et facture uniquement les RU consommées (idéal trafic intermittent) ?","explain":"Serverless — mais limité à une seule région et 50 Go/conteneur. Trafic soutenu → provisioned (manuel ou autoscale).","accept":["serverless","sans serveur"]},
  {"id":"az204-f-graph-batchmax","lvl":4,"dom":"Azure","q":"Combien de requêtes maximum peut contenir un batch Microsoft Graph (POST /$batch) ?","explain":"20 requêtes par batch — chacune avec son id pour corréler les réponses. Réduit les allers-retours et le risque de throttling.","accept":["20","vingt"]},
  {"id":"az204-f-graph-url","lvl":5,"dom":"Azure","q":"Quelle est l'URL de base de l'API Microsoft Graph (version stable) ?","explain":"https://graph.microsoft.com/v1.0 (et /beta pour les préversions — jamais en prod). Un seul endpoint pour tout Microsoft 365 / Entra.","accept":["https://graph.microsoft.com/v1.0","graph microsoft com v1 0","graph microsoft com"]},
  {"id":"az204-f-imds","lvl":4,"dom":"Sécurité","q":"Quelle adresse IP magique expose le service de métadonnées (IMDS) où une VM/app récupère les tokens de sa managed identity ?","explain":"169.254.169.254 — non routable, accessible uniquement depuis la ressource. En pratique, DefaultAzureCredential fait l'appel pour toi.","accept":["169.254.169.254","169 254 169 254"]},
  {"id":"az204-f-ai-standardtest","lvl":5,"dom":"Observabilité","q":"Quel type de test de disponibilité App Insights a remplacé l'ancien « URL ping test » (requête unique + validation TLS) ?","explain":"Le standard test. Pour des parcours multi-étapes : TrackAvailability() dans une Azure Function.","accept":["standard test","standard","test standard"]},
  {"id":"az204-f-redis-sla","lvl":6,"dom":"Azure","q":"Quel est le PREMIER tier d'Azure Cache for Redis qui offre un SLA (2 nœuds répliqués) ?","explain":"Standard = réplication + SLA 99,9 %. Basic = 1 nœud sans SLA (dev/test). Persistance et clustering → Premium.","accept":["standard"]},
  {"id":"az204-f-redis-persist","lvl":4,"dom":"Azure","q":"Quel tier Redis minimum permet la PERSISTANCE des données (RDB/AOF) et le placement en VNet ?","explain":"Premium. Un cache Basic/Standard qui redémarre perd tout — le cache doit toujours être reconstructible depuis la source de vérité.","accept":["premium"]},
  {"id":"az204-f-apim-namedvalues","lvl":5,"dom":"Azure","q":"Comment s'appellent les constantes réutilisables (éventuellement secrètes ou liées à Key Vault) qu'on référence dans les policies APIM avec {{...}} ?","explain":"Les named values : centralisent URLs, clés, configs — utilisées dans les policies via {{ma-valeur}}.","accept":["named values","named value","valeurs nommees"]},
  {"id":"az204-f-eg-systemtopic","lvl":4,"dom":"Azure","q":"Comment s'appellent les topics Event Grid intégrés qui exposent les événements natifs des services Azure (Storage, Resource Group…) ?","explain":"System topics — créés sur la ressource source. Tes propres événements → custom topics. Multi-tenant à grande échelle → event domains.","accept":["system topics","system topic","topics systeme"]},
  {"id":"az204-f-eg-domains","lvl":5,"dom":"Azure","q":"Quelle fonctionnalité Event Grid regroupe des milliers de topics sous un même endpoint pour publier vers de nombreux tenants/clients ?","explain":"Les event domains : un endpoint de publication, jusqu'à 100 000 topics, gestion centralisée des autorisations par topic.","accept":["event domains","event domain","domaines d evenements"]},
  {"id":"az204-f-eh-readers","lvl":6,"dom":"Azure","q":"Combien de lecteurs simultanés MAXIMUM par partition dans un même consumer group Event Hubs ?","explain":"5 max — mais la bonne pratique est UN seul lecteur actif par partition par consumer group (sinon doublons garantis).","accept":["5","cinq"]},
  {"id":"az204-f-sb-autofwd","lvl":4,"dom":"Azure","q":"Fonctionnalité Service Bus qui déplace automatiquement les messages d'une queue/subscription vers une autre entité (chaînage) ?","explain":"Auto-forwarding : découple les topologies (ex : fan-in de plusieurs subscriptions vers une queue de traitement).","accept":["auto forwarding","autoforwarding","auto forward","transfert automatique"]},
  {"id":"az204-f-qs-ttl","lvl":5,"dom":"Azure","q":"TTL par défaut d'un message Azure Queue Storage (en jours) ?","explain":"7 jours ; -1 = n'expire jamais. À comparer au visibility timeout (30 s par défaut) qui, lui, masque temporairement le message pendant son traitement.","accept":["7","7 jours","sept"]},
  {"id":"az204-f-ca-secretref","lvl":4,"dom":"Docker","q":"Dans Container Apps, quel préfixe utilise une variable d'environnement pour référencer un secret de l'app ?","explain":"secretref:mon-secret. Les secrets peuvent aussi référencer Key Vault via la managed identity de l'app.","accept":["secretref","secretref:","secret ref"]},
  {"id":"az204-s-ai-cost","lvl":7,"dom":"Observabilité","q":"La facture App Insights explose à cause du volume de télémétrie. Quelle technique réduit le volume tout en gardant des données statistiquement représentatives ?","explain":"Le sampling (adaptive par défaut en ASP.NET, fixed-rate sinon). App Insights conserve les items corrélés d'une même opération pour garder les traces cohérentes.","accept":["sampling","echantillonnage","le sampling"]},
  {"id":"az204-s-apim-corspol","lvl":8,"dom":"Azure","q":"Une SPA appelle ton API via APIM et le navigateur bloque la requête cross-origin. Quelle policy APIM ajouter ?","explain":"La policy cors en inbound (allowed-origins, allowed-methods, allowed-headers). C'est APIM qui répond au preflight OPTIONS.","accept":["cors","policy cors","la policy cors"]},
  {"id":"az204-s-cli-swap","lvl":8,"dom":"Azure","q":"Écris la commande CLI (sans les paramètres) qui échange le slot staging avec la production d'une web app : az webapp … ?","explain":"az webapp deployment slot swap -g MonRG -n monapp --slot staging --target-slot production.","accept":["az webapp deployment slot swap","deployment slot swap","slot swap"]},
  {"id":"az204-s-cli-acrbuild","lvl":9,"dom":"Azure","q":"Écris la commande CLI (3 mots après « az ») qui build une image dans le cloud ET la pousse dans ton registre : az … ?","explain":"az acr build -r monregistry -t app:v1 . — pas besoin de Docker en local, le build tourne dans ACR Tasks.","accept":["az acr build","acr build"]},
  {"id":"az204-c-blob-meta","lvl":6,"dom":"Azure","q":"Complète : quelle méthode écrit les métadonnées du blob ? (tape le nom)","explain":"SetMetadataAsync — côté HTTP ce sont les headers x-ms-meta-*. GetPropertiesAsync les relit (avec les propriétés système).","accept":["SetMetadataAsync","set metadata async","SetMetadata"]},
  {"id":"az204-c-cosmos-pk","lvl":4,"dom":"Azure","q":"Complète : quelle classe indique la partition cible ? (tape le nom)","explain":"new PartitionKey(valeur). La fournir évite une opération cross-partition coûteuse en RU.","accept":["PartitionKey","partition key"]},
  {"id":"az204-c-cosmos-param","lvl":5,"dom":"Azure","q":"Complète : quelle méthode lie la valeur du paramètre @s ?","explain":"QueryDefinition.WithParameter — requête paramétrée = pas d'injection et meilleures perfs.","accept":["WithParameter","with parameter"]},
  {"id":"az204-c-msal-secret","lvl":6,"dom":"Azure","q":"Complète : quelle méthode fournit le secret client ?","explain":"WithClientSecret — ou WithCertificate(cert), recommandé en production. Réservé aux confidential clients.","accept":["WithClientSecret","with client secret"]},
  {"id":"az204-c-kv-cred","lvl":4,"dom":"Azure","q":"Complète : quelle classe d'Azure.Identity fonctionne en local ET en prod sans stocker de secret ?","explain":"DefaultAzureCredential : chaîne env vars → managed identity → Azure CLI… Même code partout.","accept":["DefaultAzureCredential","default azure credential"]},
  {"id":"az204-c-durable-activity","lvl":5,"dom":"Azure","q":"Complète : quelle méthode appelle une activity function ?","explain":"CallActivityAsync — l'orchestrateur délègue tout le vrai travail (I/O, calculs) aux activities.","accept":["CallActivityAsync","call activity async"]},
  {"id":"az204-c-durable-event","lvl":8,"dom":"Azure","q":"Complète : quelle méthode attend un événement externe (l'approbation) ?","explain":"WaitForExternalEvent + durable timer + Task.WhenAny = le pattern human interaction avec escalade.","accept":["WaitForExternalEvent","wait for external event"]},
  {"id":"az204-c-sb-complete","lvl":4,"dom":"Azure","q":"Complète : quelle méthode confirme le traitement en mode peek-lock ?","explain":"CompleteMessageAsync supprime le message. Les alternatives : AbandonMessageAsync, DeadLetterMessageAsync, DeferMessageAsync.","accept":["CompleteMessageAsync","complete message async"]},
  {"id":"az204-c-redis-set","lvl":6,"dom":"Azure","q":"Complète : quelle méthode StackExchange.Redis écrit une valeur AVEC un TTL ?","explain":"StringSetAsync(clé, valeur, expiry). Le 3e paramètre est le TTL — indispensable pour le cache-aside.","accept":["StringSetAsync","string set async","StringSet"]},
  {"id":"az204-c-ai-track","lvl":5,"dom":"Azure","q":"Complète : quelle méthode envoie un événement custom ?","explain":"TrackEvent — et sa famille : TrackMetric, TrackException, TrackDependency, TrackTrace, TrackAvailability.","accept":["TrackEvent","track event"]},
  {"id":"az204-c-apim-jwtpol","lvl":7,"dom":"Azure","q":"Complète le nom de la policy qui valide le token Entra ID :","explain":"validate-jwt en inbound — vérifie signature, audience, émetteur, claims. 401 si invalide, sans toucher le backend.","accept":["validate-jwt","validate jwt","validatejwt"]},
  {"id":"az204-csA-tier","lvl":7,"dom":"Azure","q":"Les images des produits retirés du catalogue (consultées rarement, environ une fois par mois, mais qui doivent rester disponibles IMMÉDIATEMENT) doivent coûter moins cher. Quel access tier ?","explain":"Cool : accès rare mais online (lecture immédiate), durée min 30 jours. Archive serait moins cher mais OFFLINE — incompatible avec « disponibles immédiatement ».","accept":["cool"]},
  {"id":"az204-csB-ingest","lvl":9,"dom":"Azure","q":"Quel service Azure pour ingérer les 20 000 événements/seconde des capteurs ?","explain":"Event Hubs est conçu pour le streaming massif : partitions, consumer groups, compatibilité Kafka. Event Grid ne convient pas au streaming continu.","accept":["event hubs","event hub","azure event hubs","eventhubs","eventhub"]},
  {"id":"az204-csB-archive","lvl":7,"dom":"Azure","q":"Comment archiver le flux 5 ans pour l'audit, SANS écrire de code ?","explain":"Event Hubs Capture écrit automatiquement vers Blob/Data Lake (Avro). La rétention native (max 7 j en Standard) ne suffit pas pour 5 ans.","accept":["capture","event hubs capture"]},
  {"id":"az204-csC-quota","lvl":8,"dom":"Azure","q":"Chaque partenaire a un plafond de 100 000 appels PAR MOIS selon son contrat. Quelle policy APIM (nom) ?","explain":"quota / quota-by-key = plafond de volume sur longue période (renouvelé au mois) → 403. rate-limit ne gère que les pics courts → 429.","accept":["quota","quota-by-key","quota by key"]},
  {"id":"az400-v-mttr","lvl":3,"dom":"CI/CD","q":"Quelle métrique mesure le temps moyen nécessaire pour restaurer le service après un incident (sigle) ?","explain":"MTTR — Mean Time To Restore/Recovery. Une des 4 métriques DORA, appelée « time to recovery » dans les dashboards Azure DevOps.","accept":["mttr","mean time to restore","mean time to recovery","time to restore"]},
  {"id":"az400-v-iac","lvl":2,"dom":"Terraform","q":"Décrire l'infrastructure dans des fichiers versionnés et déployés automatiquement. Quel terme (sigle) ?","explain":"Infrastructure as Code : ARM, Bicep, Terraform, Azure Machine Configuration. Au programme du domaine pipelines (50-55 %).","accept":["iac","infrastructure as code"]},
  {"id":"az400-v-drift","lvl":1,"dom":"Terraform","q":"Écart entre la configuration déclarée et l'état réel des serveurs/ressources (souvent dû à des modifications manuelles). Quel terme anglais ?","explain":"Le configuration drift. Contré par la desired state configuration (Azure Automation State Configuration, Azure Machine Configuration) qui ré-applique l'état voulu.","accept":["drift","configuration drift","derive"]},
  {"id":"az400-v-bluegreen","lvl":2,"dom":"CI/CD","q":"Quelle stratégie utilise DEUX environnements identiques, déploie sur l'inactif puis bascule tout le trafic d'un coup (rollback = rebascule) ?","explain":"Bascule instantanée et rollback immédiat, au prix de deux environnements. Sur App Service, les deployment slots + swap sont l'implémentation native.","accept":["blue green","bluegreen","bleu vert"]},
  {"id":"az400-v-canary","lvl":3,"dom":"CI/CD","q":"Quelle stratégie expose d'abord la nouvelle version à un petit pourcentage d'instances, surveille les métriques, puis étend progressivement ?","explain":"Le « canari dans la mine » : petit périmètre d'abord pour limiter le rayon d'impact. La stratégie « canary » existe nativement dans les deployment jobs YAML.","accept":["canary","canari"]},
  {"id":"az400-v-ring","lvl":1,"dom":"CI/CD","q":"Quelle stratégie livre par cercles d'utilisateurs de plus en plus larges (interne → early adopters → tous), chaque cercle servant de validation ?","explain":"Forme de progressive exposure : ring 0 (équipe), ring 1 (beta), ring 2 (production générale). Chaque anneau est une porte de qualité.","accept":["ring","anneaux","anneau","ring based","deploiement en anneaux"]},
  {"id":"az400-v-featureflag","lvl":2,"dom":"CI/CD","q":"Quel mécanisme découple le DÉPLOIEMENT du code de son ACTIVATION (livrer désactivé, activer progressivement, couper sans redéployer) ?","explain":"Deploy ≠ release. Le kill switch permet de couper une fonctionnalité en secondes, sans rollback de déploiement. Implémentation Azure : App Configuration Feature Manager.","accept":["feature flag","feature flags","feature toggle","indicateur de fonctionnalite"]},
  {"id":"az400-v-gitflow","lvl":1,"dom":"CI/CD","q":"Quelle stratégie de branches fait intégrer tout le monde très fréquemment dans UNE branche principale, via des branches de feature de 1-2 jours maximum ?","explain":"Trunk-based = la pratique qui corrèle le mieux avec les hautes performances DORA. Les branches longues créent des merges douloureux et retardent l'intégration.","accept":["trunk based","trunk based development","trunk"]},
  {"id":"az400-v-lfs","lvl":2,"dom":"CI/CD","q":"Quelle extension Git stocke les gros fichiers binaires hors du dépôt, en ne gardant qu'un pointeur texte dans l'historique (sigle) ?","explain":"Git LFS (Large File Storage). Alternative citée au programme : git-fat. Sans cela, chaque version d'un binaire alourdit définitivement le clone.","accept":["lfs","git lfs","large file storage"]},
  {"id":"az400-v-scalar","lvl":3,"dom":"CI/CD","q":"Quel outil (cité au programme) optimise les TRÈS grands dépôts Git via clone partiel, sparse-checkout et maintenance en arrière-plan ?","explain":"Scalar configure automatiquement les optimisations Git (partial clone, sparse checkout, prefetch) pour les dépôts massifs.","accept":["scalar"]},
  {"id":"az400-v-cve","lvl":3,"dom":"Sécurité","q":"Identifiant public standardisé d'une vulnérabilité connue (ex : CVE-2021-44228 pour Log4Shell). Quel sigle ?","explain":"CVE. Le scoring associé s'appelle CVSS. Dependabot signale les dépendances affectées par des CVE connues.","accept":["cve","common vulnerabilities and exposures"]},
  {"id":"az400-v-sbom","lvl":1,"dom":"Sécurité","q":"Inventaire complet des composants et dépendances d'un livrable, qui permet de répondre en minutes à « suis-je impacté par cette CVE ? ». Quel sigle ?","explain":"Le SBOM répond à « suis-je impacté par cette CVE ? » en quelques minutes. Souvent généré dans le pipeline (formats SPDX, CycloneDX).","accept":["sbom","software bill of materials"]},
  {"id":"az400-v-mi","lvl":3,"dom":"Sécurité","q":"Identité Azure attachée à une ressource, sans aucun secret à gérer ni faire tourner. Quel nom ?","explain":"Managed identity (system-assigned ou user-assigned). Le référentiel demande explicitement de savoir CHOISIR entre service principal et managed identity.","accept":["managed identity","identite manageee","identite managee","identite geree"]},
  {"id":"az400-v-kv","lvl":3,"dom":"Sécurité","q":"Service Azure centralisant secrets, clés et certificats, intégrable aux variable groups d'Azure DevOps. Quel nom ?","explain":"Azure Key Vault. Un variable group peut être lié à un Key Vault : les secrets sont lus au runtime, jamais stockés dans le pipeline.","accept":["key vault","azure key vault","keyvault"]},
  {"id":"az400-v-kql","lvl":1,"dom":"Observabilité","q":"Langage de requête d'Azure Monitor Logs / Application Insights (where, summarize, project, ago…). Quel sigle ?","explain":"KQL — explicitement au programme (« interrogate logs using basic KQL queries »). À savoir lire ET écrire simplement.","accept":["kql","kusto","kusto query language"]},
  {"id":"az400-v-webhook","lvl":1,"dom":"CI/CD","q":"Mécanisme d'intégration où un service envoie un POST HTTP vers une URL que tu exposes dès qu'un événement survient. Quel terme ?","explain":"Le webhook (« service hooks » dans Azure DevOps). Au programme : « configure integration by using webhooks ».","accept":["webhook","web hook","service hook"]},
  {"id":"az400-f-trigger-none","lvl":5,"dom":"CI/CD","q":"Quelle valeur donner à « trigger » pour désactiver complètement le déclenchement automatique d'un pipeline ?","explain":"trigger: none — typique d'un pipeline appelé uniquement manuellement ou par un autre pipeline (resource pipelines).","accept":["none","trigger none"]},
  {"id":"az400-f-pathfilter","lvl":6,"dom":"CI/CD","q":"Dans un monorepo, quel mécanisme du trigger évite de déclencher un pipeline quand le dossier concerné n'a pas changé (2 mots) ?","explain":"trigger: paths: include/exclude. Économise des minutes d'agent et évite les builds inutiles — question classique sur les monorepos.","accept":["path filters","path filter","filtres de chemin","paths"]},
  {"id":"az400-f-vargroup","lvl":4,"dom":"CI/CD","q":"Quel objet de la Library regroupe des variables réutilisables entre plusieurs pipelines et peut être lié à un Key Vault (2 mots) ?","explain":"Library → Variable groups, référencé par « variables: - group: MonGroupe ». Lié à Key Vault, il lit les secrets au runtime sans les dupliquer.","accept":["variable group","groupe de variables","variable groups"]},
  {"id":"az400-f-outputvar","lvl":5,"dom":"CI/CD","q":"Quel type de variable faut-il déclarer (isOutput=true) pour transmettre une valeur calculée d'un job A vers un job B (2 mots) ?","explain":"echo '##vso[task.setvariable variable=maVar;isOutput=true]valeur' puis $[ dependencies.JobA.outputs['step.maVar'] ]. Le dependsOn est obligatoire.","accept":["output variable","variable de sortie","output"]},
  {"id":"az400-f-agent-timeout","lvl":6,"dom":"CI/CD","q":"Quel est le timeout d'un job sur agent Microsoft-hosted avec le niveau gratuit (projet privé), en minutes ?","explain":"Projet privé gratuit : 60 min. Avec un job parallèle payant : jusqu'à 360 min. Projets publics : 360 min. Les agents self-hosted n'ont pas de limite imposée.","accept":["60","60 min","60 minutes","soixante"]},
  {"id":"az400-f-free-minutes","lvl":4,"dom":"CI/CD","q":"Combien de minutes gratuites d'agent Microsoft-hosted par mois offre un projet PRIVÉ Azure DevOps ?","explain":"1 job parallèle gratuit et 1 800 min/mois en privé. Les projets publics ont 10 jobs parallèles gratuits et des minutes illimitées.","accept":["1800","1 800","1800 minutes"]},
  {"id":"az400-f-matrix","lvl":4,"dom":"CI/CD","q":"Quelle stratégie de job exécute le même job en parallèle avec des combinaisons de variables (plusieurs OS, plusieurs versions de runtime) ?","explain":"strategy: matrix: { linux: {...}, windows: {...} } — chaque entrée devient un job parallèle. « maxParallel » plafonne la concurrence.","accept":["matrix","matrice"]},
  {"id":"az400-f-cond-func","lvl":6,"dom":"CI/CD","q":"Quelle fonction de condition exécute un step dans TOUS les cas, y compris après une annulation du job ?","explain":"always() s'exécute même en cas d'annulation. succeededOrFailed() s'exécute après succès ou échec mais PAS si le job est annulé — nuance testée à l'examen.","accept":["always","always()"]},
  {"id":"az400-f-cond-default","lvl":4,"dom":"CI/CD","q":"Quelle est la condition PAR DÉFAUT d'un step si aucune n'est précisée ?","explain":"Par défaut, un échec interrompt la suite. C'est pourquoi les steps de publication de résultats de tests portent souvent condition: succeededOrFailed().","accept":["succeeded","succeeded()"]},
  {"id":"az400-f-environment","lvl":4,"dom":"CI/CD","q":"Quel objet d'Azure Pipelines représente une cible logique de déploiement et porte l'historique, les checks et les approbations ?","explain":"L'environment est le point où l'on attache les approbations et les checks — c'est le mécanisme de contrôle des déploiements en YAML.","accept":["environment","environnement","environments"]},
  {"id":"az400-f-publish-artifact","lvl":5,"dom":"CI/CD","q":"Quelle tâche moderne publie un artefact de pipeline (plus rapide que l'ancienne PublishBuildArtifacts) ?","explain":"PublishPipelineArtifact utilise un stockage optimisé et déduplique. Le raccourci YAML est « - publish: $(Build.ArtifactStagingDirectory) artifact: drop ».","accept":["PublishPipelineArtifact","publish pipeline artifact"]},
  {"id":"az400-f-upstream","lvl":6,"dom":"CI/CD","q":"Quel réglage d'un feed Azure Artifacts relaie et met en cache les packages d'une source publique comme nuget.org (2 mots) ?","explain":"Les packages publics utilisés sont sauvegardés dans ton feed — protection contre la suppression amont, et un seul endpoint à configurer côté développeurs.","accept":["upstream source","upstream sources","upstream","source amont"]},
  {"id":"az400-f-cache","lvl":5,"dom":"CI/CD","q":"Quelle tâche accélère les builds en réutilisant les dépendances téléchargées entre exécutions ?","explain":"Cache@2 avec key: 'npm | \"$(Agent.OS)\" | package-lock.json'. La clé DOIT dépendre du lock file, sinon le cache devient obsolète.","accept":["Cache@2","cache","tache cache"]},
  {"id":"az400-f-flaky","lvl":6,"dom":"CI/CD","q":"Comment appelle-t-on un test qui réussit ou échoue de façon non déterministe, sans changement de code (terme anglais) ?","explain":"Les tests flaky détruisent la confiance dans la CI. Azure DevOps peut les détecter (re-runs) et les signaler dans les rapports — « monitor pipeline health » au programme.","accept":["flaky","flaky test","test flaky","instable"]},
  {"id":"az400-f-testresults","lvl":4,"dom":"CI/CD","q":"Quelle tâche publie les résultats de tests pour qu'ils apparaissent dans l'onglet Tests du run ?","explain":"PublishTestResults alimente les analyses (tendances, flaky). Pour la couverture, c'est PublishCodeCoverageResults (formats Cobertura ou JaCoCo).","accept":["PublishTestResults","publish test results"]},
  {"id":"az400-f-loadtest","lvl":6,"dom":"CI/CD","q":"Quel service Azure exécute des tests de CHARGE à grande échelle (compatible scripts JMeter) intégrables au pipeline ?","explain":"Azure Load Testing pour les tests de charge (au programme : « local tests, unit tests, integration tests, and load tests »). Test Plans concerne les tests manuels/exploratoires.","accept":["azure load testing","load testing"]},
  {"id":"az400-f-cherrypick","lvl":6,"dom":"Git","q":"Quelle commande Git applique UN commit précis d'une branche sur une autre (typiquement pour un hotfix) ?","explain":"git cherry-pick <sha> — le cœur du « hotfix path plan » : corriger sur main puis reporter sur la branche de release (ou l'inverse).","accept":["git cherry-pick","cherry-pick","cherry pick"]},
  {"id":"az400-f-bisect","lvl":5,"dom":"Git","q":"Quelle commande Git trouve par dichotomie le commit ayant introduit un bug ?","explain":"git bisect start / bad / good : recherche binaire dans l'historique. Cité au programme (« recover specific data by using Git commands »).","accept":["git bisect","bisect"]},
  {"id":"az400-f-reflog","lvl":6,"dom":"Git","q":"Quelle commande Git permet de retrouver un commit « perdu » après un reset ou une suppression de branche ?","explain":"git reflog liste tous les déplacements de HEAD, même ceux sortis de l'historique : on récupère le SHA puis git checkout/cherry-pick.","accept":["git reflog","reflog"]},
  {"id":"az400-f-codeql","lvl":4,"dom":"CI/CD","q":"Quel moteur d'analyse statique (SAST) de GitHub traite le code comme une base de données interrogeable pour trouver des vulnérabilités ?","explain":"CodeQL alimente le code scanning. Le référentiel cite même l'exécution d'une analyse CodeQL dans un conteneur.","accept":["codeql"]},
  {"id":"az400-f-pushprotection","lvl":5,"dom":"CI/CD","q":"Quelle fonctionnalité du secret scanning BLOQUE le push contenant un secret, avant qu'il n'entre dans l'historique (2 mots) ?","explain":"C'est la prévention plutôt que la détection : le secret n'atteint jamais le dépôt, ce qui évite toute la procédure de révocation/réécriture.","accept":["push protection"]},
  {"id":"az400-f-securefiles","lvl":5,"dom":"Sécurité","q":"Quel mécanisme de la Library stocke de façon chiffrée un certificat ou un keystore, récupéré ensuite par DownloadSecureFile ?","explain":"Secure files : stockage chiffré des fichiers sensibles (certificats, profils de provisioning, clés SSH), avec contrôle d'accès par pipeline. Au programme.","accept":["secure files","secure file","fichiers securises"]},
  {"id":"az400-f-svc-connection","lvl":6,"dom":"Sécurité","q":"Quelle méthode d'authentification d'une service connection vers Azure n'exige AUCUN secret à stocker ni à faire tourner (nom complet ou sigle) ?","explain":"La fédération élimine le secret. À défaut, service principal avec certificat, puis avec secret (à faire tourner). Jamais de compte nominatif.","accept":["workload identity federation","oidc","federation d identite de charge de travail","openid connect"]},
  {"id":"az400-f-kql-basics","lvl":5,"dom":"CI/CD","q":"Quel opérateur KQL agrège les données (équivalent d'un GROUP BY) ?","explain":"where = filtrer les lignes, project = choisir les colonnes, extend = ajouter une colonne calculée, summarize = agréger, order by = trier.","accept":["summarize"]},
  {"id":"az400-f-appinsights-tables","lvl":4,"dom":"Observabilité","q":"Quelle table Application Insights contient les appels SORTANTS (SQL, HTTP, stockage) ?","explain":"requests = appels entrants, dependencies = appels sortants, exceptions, traces (logs), customEvents/customMetrics, availabilityResults, pageViews.","accept":["dependencies"]},
  {"id":"az400-f-actiongroup","lvl":5,"dom":"Observabilité","q":"Quel objet Azure Monitor définit ce qui se passe quand une alerte se déclenche (e-mail, SMS, webhook, Logic App…) — 2 mots ?","explain":"Une alert rule (condition) + un action group (réaction). Le même action group est réutilisable par de nombreuses alertes.","accept":["action group","action groups","groupe d actions"]},
  {"id":"az400-f-insights-types","lvl":6,"dom":"Observabilité","q":"Quelle solution Azure Monitor surveille spécifiquement les clusters de conteneurs (AKS) ?","explain":"Le référentiel cite explicitement VM Insights, Container Insights, Monitor for Storage et Monitor for Networks — savoir associer chaque cible à sa solution.","accept":["container insights"]},
  {"id":"az400-f-workbook","lvl":4,"dom":"Observabilité","q":"Quel objet Azure Monitor est un rapport interactif combinant texte, requêtes KQL, métriques et graphiques (à ne pas confondre avec le runbook) ?","explain":"À distinguer du runbook (script Azure Automation) et du dashboard (vue épinglée). Le workbook est le format de rapport analytique riche.","accept":["workbook","workbooks","classeur"]},
  {"id":"az400-f-boards-github","lvl":4,"dom":"CI/CD","q":"Quelle syntaxe faut-il mentionner dans un message de commit GitHub pour le lier au work item Azure Boards n°123 ?","explain":"La syntaxe AB#<id> crée le lien de traçabilité. « Fixes AB#123 » ferme même le work item. Intégration Boards ↔ GitHub explicitement au programme.","accept":["AB#123","AB#","ab 123"]},
  {"id":"az400-f-analytics","lvl":4,"dom":"CI/CD","q":"Quel service alimente les widgets de rapports avancés et l'export Power BI dans Azure DevOps (via ses vues et OData) ?","explain":"Analytics est le moteur de reporting d'Azure DevOps (CFD, vélocité, burndown, lead/cycle time) et la source des jeux de données Power BI.","accept":["analytics","analytics views"]},
  {"id":"az400-s-hotfix","lvl":7,"dom":"CI/CD","q":"Un bug critique est en production, mais main contient déjà des features non validées. Depuis quel point de départ crées-tu la branche de hotfix ?","explain":"« Design a hotfix path plan » est au programme. Partir du tag de prod garantit qu'on ne livre QUE le correctif, sans embarquer de code non validé.","accept":["tag","le tag","tag de production","tag de la version en production","depuis le tag"]},
  {"id":"az400-s-zero-downtime","lvl":9,"dom":"CI/CD","q":"Une App Service doit être mise à jour sans aucune interruption : on déploie sur un emplacement de staging, on préchauffe, puis on effectue une opération. Comment s'appelle-t-elle ?","explain":"« Plan for minimizing downtime by using load balancing, rolling deployments, and deployment slot usage and swap » — le swap est l'implémentation blue-green d'App Service.","accept":["swap","echange","le swap"]},
  {"id":"az400-s-required-template","lvl":7,"dom":"Sécurité","q":"La sécurité veut garantir que TOUS les pipelines exécutent un scan avant la production, sans dépendre de la bonne volonté des équipes. Quel check attaches-tu à l'environment (2 mots) ?","explain":"Le contrôle technique bat la consigne écrite : le déploiement est refusé si le pipeline n'étend pas le template obligatoire.","accept":["required template","template requis","required templates"]},
  {"id":"az400-s-mi-vs-spn","lvl":7,"dom":"Sécurité","q":"Une VM Azure exécutant un agent self-hosted doit accéder à Key Vault, sans aucun secret à stocker ni faire tourner. Quel type d'identité choisis-tu ?","explain":"Dès que la charge s'exécute SUR une ressource Azure, la managed identity est la bonne réponse. Le service principal reste pour l'externe (GitHub Actions sans OIDC).","accept":["managed identity","identite manageee","identite managee","identite geree"]},
  {"id":"az400-s-dsc","lvl":9,"dom":"Terraform","q":"Un parc de VMs doit rester conforme à une configuration précise, avec réévaluation et correction automatique du drift. Quelle technologie Azure (nom actuel ou son prédécesseur) ?","explain":"Ces deux technologies sont nommées dans le référentiel. La DSC applique et REMET en conformité, contrairement à un script exécuté une seule fois.","accept":["azure machine configuration","machine configuration","azure automation state configuration","state configuration","dsc"]},
  {"id":"az400-s-ade","lvl":9,"dom":"Terraform","q":"Les développeurs doivent créer eux-mêmes des environnements de test conformes depuis un catalogue de templates approuvés, sans passer par l'équipe plateforme. Quel service Azure ?","explain":"Azure Deployment Environments est explicitement au programme (« for on-demand self-deployment ») : self-service encadré par un catalogue d'IaC validé.","accept":["azure deployment environments","deployment environments"]},
  {"id":"az400-c-yaml-trigger","lvl":6,"dom":"CI/CD","q":"Complète le mot-clé qui limite le déclenchement à certains dossiers :","explain":"trigger: paths: include/exclude — indispensable en monorepo pour ne builder que le service modifié.","accept":["paths","path"]},
  {"id":"az400-c-yaml-pool","lvl":4,"dom":"CI/CD","q":"Complète la clé qui désigne une image d'agent Microsoft-hosted :","explain":"pool: vmImage: pour les agents Microsoft-hosted ; pool: name: MonPool pour un pool self-hosted.","accept":["vmImage","vm image"]},
  {"id":"az400-c-yaml-deployjob","lvl":5,"dom":"CI/CD","q":"Complète le mot-clé qui déclare un job de déploiement (au lieu de « job ») :","explain":"« - deployment: » active l'historique par environment, les checks et les stratégies. Un « - job: » classique n'a rien de tout ça.","accept":["deployment"]},
  {"id":"az400-c-yaml-strategy","lvl":7,"dom":"CI/CD","q":"Complète le hook qui bascule le trafic vers la nouvelle version :","explain":"Ordre des hooks : preDeploy → deploy → routeTraffic → postRouteTraffic → on: success|failure. postRouteTraffic sert à surveiller APRÈS la bascule.","accept":["routeTraffic","route traffic"]},
  {"id":"az400-c-yaml-condition","lvl":6,"dom":"CI/CD","q":"Complète la condition qui s'exécute après un succès OU un échec (mais pas si annulé) :","explain":"succeededOrFailed() est LE choix pour publier des résultats de tests. always() irait plus loin en s'exécutant aussi après une annulation.","accept":["succeededOrFailed","succeeded or failed"]},
  {"id":"az400-c-yaml-template","lvl":4,"dom":"CI/CD","q":"Complète le mot-clé qui insère un template de steps :","explain":"- template: chemin.yml avec parameters. Pour imposer un template parent (gouvernance), c'est « extends: » au niveau du pipeline.","accept":["template"]},
  {"id":"az400-c-yaml-vargroup","lvl":5,"dom":"CI/CD","q":"Complète pour référencer un variable group de la Library :","explain":"variables: - group: NomDuGroupe. Un groupe lié à Key Vault résout les secrets au runtime sans jamais les stocker dans le YAML.","accept":["group"]},
  {"id":"az400-c-yaml-secret-env","lvl":9,"dom":"CI/CD","q":"Complète le mot-clé qui rend une variable SECRÈTE disponible au script :","explain":"Les secrets ne sont pas injectés automatiquement dans l'environnement : le mapping explicite via env: est obligatoire. (« with: » est la syntaxe GitHub Actions.)","accept":["env"]},
  {"id":"az400-c-yaml-output","lvl":7,"dom":"CI/CD","q":"Complète pour rendre la variable consommable par un AUTRE job :","explain":"isOutput=true + un « name: » sur le step, puis dans le job dépendant : $[ dependencies.JobA.outputs['setver.ver'] ].","accept":["isOutput","is output"]},
  {"id":"az400-c-yaml-matrix","lvl":6,"dom":"CI/CD","q":"Complète la stratégie qui duplique le job par combinaison :","explain":"Chaque entrée devient un job parallèle avec ses variables. maxParallel limite la concurrence si les jobs parallèles sont comptés.","accept":["matrix"]},
  {"id":"az400-c-yaml-cache","lvl":8,"dom":"CI/CD","q":"Sur quel fichier baser la clé de cache des dépendances npm ?","explain":"Le LOCK file décrit les versions exactes : il change dès qu'une dépendance change. Baser la clé sur package.json manquerait les mises à jour transitives.","accept":["package-lock.json","package lock json","package-lock"]},
  {"id":"az400-c-yaml-publish","lvl":4,"dom":"CI/CD","q":"Complète le raccourci YAML qui publie un artefact de pipeline :","explain":"« - publish: chemin / artifact: nom » est le raccourci de PublishPipelineArtifact. Le raccourci inverse est « - download: ».","accept":["publish"]},
  {"id":"az400-c-yaml-resource-repo","lvl":9,"dom":"CI/CD","q":"Complète le type de ressource permettant d'utiliser des templates d'un autre dépôt :","explain":"resources: repositories: puis « extends: template: prod.yml@templates ». Épingler un tag (ref) évite qu'une modif du template casse tous les pipelines.","accept":["repositories"]},
  {"id":"az400-c-gha-on","lvl":5,"dom":"CI/CD","q":"Complète le mot-clé GitHub Actions qui définit les déclencheurs :","explain":"« on: » est l'équivalent de trigger/pr d'Azure Pipelines. Autres valeurs utiles : workflow_dispatch (manuel), schedule (cron).","accept":["on"]},
  {"id":"az400-c-gha-runs-on","lvl":6,"dom":"CI/CD","q":"Complète la clé qui désigne le runner GitHub :","explain":"runs-on: est l'équivalent de « pool: vmImage: ». Pour un runner self-hosted : runs-on: [self-hosted, linux].","accept":["runs-on","runs on"]},
  {"id":"az400-c-gha-secret","lvl":4,"dom":"CI/CD","q":"Complète le contexte qui accède aux secrets du dépôt :","explain":"${{ secrets.NOM }}. Les variables non sensibles passent par ${{ vars.NOM }}, et le contexte github porte les métadonnées de l'événement.","accept":["secrets"]},
  {"id":"az400-c-gha-oidc","lvl":7,"dom":"CI/CD","q":"Complète la permission nécessaire pour que le workflow demande un jeton OIDC :","explain":"permissions: id-token: write autorise la demande du jeton OIDC — la clé de l'authentification sans secret vers Azure (azure/login).","accept":["id-token","id token"]},
  {"id":"az400-c-gha-needs","lvl":5,"dom":"CI/CD","q":"Complète la clé qui crée une dépendance entre jobs GitHub Actions :","explain":"« needs: » est l'équivalent GitHub du « dependsOn: » d'Azure Pipelines. Sans lui, les jobs partent en parallèle.","accept":["needs"]},
  {"id":"az400-c-kql-fail","lvl":6,"dom":"CI/CD","q":"Complète l'opérateur d'agrégation :","explain":"summarize est le GROUP BY de KQL. La séquence where → summarize → order by est le squelette à reconnaître.","accept":["summarize"]},
  {"id":"az400-c-kql-bin","lvl":9,"dom":"CI/CD","q":"Complète la fonction qui regroupe par tranches d'une heure :","explain":"bin(timestamp, 1h) découpe en intervalles réguliers — indispensable pour tracer une série temporelle avec render timechart.","accept":["bin"]},
  {"id":"az400-c-kql-join","lvl":7,"dom":"CI/CD","q":"Complète l'opérateur qui corrèle deux tables par identifiant d'opération :","explain":"join on operation_Id relie une requête échouée à son exception — la base du traçage distribué. union empile des tables au lieu de les corréler.","accept":["join"]},
  {"id":"az400-c-git-lfs","lvl":4,"dom":"Git","q":"Complète le filtre à utiliser pour stocker ces fichiers hors du dépôt :","explain":"filter=lfs diff=lfs merge=lfs -text : Git remplace le contenu par un pointeur et stocke le binaire dans LFS.","accept":["lfs"]},
  {"id":"az400-c-git-hotfix","lvl":8,"dom":"Git","q":"Complète la commande qui applique ce seul commit sur main :","explain":"Le chemin de hotfix canonique : brancher depuis le TAG de prod, corriger, livrer, puis cherry-pick vers main pour ne pas perdre le correctif.","accept":["cherry-pick","cherry pick"]},
  {"id":"az400-c-git-undo","lvl":5,"dom":"Git","q":"Complète la commande sûre sur une branche partagée :","explain":"revert crée un commit inverse : l'historique reste intact pour tous. reset réécrirait l'historique et casserait les dépôts des collègues.","accept":["revert"]},
  {"id":"az400-c-bicep-param","lvl":9,"dom":"CI/CD","q":"Complète le mot-clé Bicep qui déclare un paramètre d'entrée :","explain":"param = entrée (surchargeable au déploiement), var = variable calculée interne, output = valeur de sortie.","accept":["param"]},
  {"id":"az400-c-whatif","lvl":7,"dom":"Terraform","q":"Complète la commande qui PRÉVISUALISE les changements sans les appliquer (équivalent du plan Terraform) :","explain":"az deployment group what-if montre les créations/modifications/suppressions avant application — la porte de validation IaC en CI.","accept":["what-if","what if","whatif"]},
  {"id":"az400-c-mermaid","lvl":6,"dom":"CI/CD","q":"Complète le mot-clé Mermaid qui déclare un diagramme de flux orienté :","explain":"graph LR (left-right) ou graph TD (top-down) — « flowchart » fonctionne aussi. Mermaid est explicitement cité au programme pour la documentation.","accept":["graph","flowchart"]},
  {"id":"az400-c-ab-link","lvl":4,"dom":"CI/CD","q":"Complète la syntaxe qui relie ce commit GitHub à un work item Azure Boards :","explain":"AB#<id> crée le lien de traçabilité GitHub → Azure Boards ; « Fixes AB#123 » ferme même le work item à la fusion. « #123 » référencerait une issue GitHub.","accept":["AB#","ab"]},
  {"id":"az400-csA-metrics","lvl":7,"dom":"CI/CD","q":"La direction veut mesurer objectivement le progrès de la transformation. Quel jeu de 4 métriques standard proposes-tu (nom du référentiel) ?","explain":"DORA : deployment frequency, lead time for changes, change failure rate, time to restore. Elles équilibrent vitesse ET stabilité — un dashboard Azure DevOps peut les afficher.","accept":["dora","metriques dora","dora metrics","les 4 metriques dora"]},
  {"id":"az400-csB-secret","lvl":7,"dom":"CI/CD","q":"Fabrikam veut supprimer TOUS les secrets stockés dans les pipelines pour l'authentification vers Azure. Quelle méthode d'authentification sans secret recommandes-tu (nom ou sigle) ?","explain":"La workload identity federation (OIDC) : le pipeline échange un jeton de confiance contre un jeton Entra. Plus aucun secret à stocker ni à faire tourner.","accept":["workload identity federation","oidc","federation d identite de charge de travail","openid connect"]},
  {"id":"az400-csC-slo","lvl":7,"dom":"CI/CD","q":"Contoso veut un critère objectif pour arbitrer entre livrer de nouvelles features et fiabiliser la plateforme. Quel mécanisme SRE proposes-tu (2 mots) ?","explain":"L'error budget dérivé du SLO : tant qu'il reste du budget, on livre ; épuisé, la priorité bascule automatiquement vers la fiabilité. Fin des débats subjectifs.","accept":["error budget","budget d erreur","budget erreur"]},
  {"id":"az900-cl-iaas","lvl":3,"dom":"Azure","q":"Modèle de service où le fournisseur gère le matériel (serveurs, réseau) mais où TU gères le système d'exploitation et tout ce qui est au-dessus. Quel sigle ?","explain":"IaaS = Infrastructure as a Service. Exemple type : les machines virtuelles Azure. Le plus de contrôle, mais le plus de responsabilité.","accept":["IaaS","infrastructure as a service"]},
  {"id":"az900-cl-paas","lvl":1,"dom":"Azure","q":"Modèle de service où tu ne gères QUE ton application et tes données — le fournisseur gère l'OS, le runtime et l'infrastructure. Quel sigle ?","explain":"PaaS = Platform as a Service. Exemples : Azure App Service, Azure SQL Database. Idéal pour les développeurs qui veulent juste déployer leur code.","accept":["PaaS","platform as a service"]},
  {"id":"az900-cl-saas","lvl":2,"dom":"Azure","q":"Modèle où tu utilises un logiciel prêt à l'emploi via Internet, sans rien gérer du tout (ex : Microsoft 365, Outlook.com). Quel sigle ?","explain":"SaaS = Software as a Service. Tu n'es responsable que de tes données, de tes comptes et de tes appareils.","accept":["SaaS","software as a service"]},
  {"id":"az900-cl-serverless","lvl":3,"dom":"Azure","q":"Modèle d'exécution où tu écris juste du code, sans jamais voir de serveur, facturé à l'exécution (ex : Azure Functions). Quel terme ?","explain":"Serverless : les serveurs existent bien sûr, mais leur gestion est totalement invisible pour toi. Tu paies à l'exécution, et ça descend à zéro sans trafic.","accept":["serverless","sans serveur"]},
  {"id":"az900-cl-private","lvl":2,"dom":"Azure","q":"Modèle de déploiement où l'infrastructure cloud est réservée à UNE seule organisation (sur site ou hébergée). Quel nom ?","explain":"Le cloud privé : contrôle maximal et conformité facilitée, mais c'est toi qui portes le coût et la maintenance du matériel.","accept":["cloud prive","prive","private cloud"]},
  {"id":"az900-cl-hybrid","lvl":3,"dom":"Azure","q":"Modèle qui combine un environnement sur site (ou cloud privé) ET le cloud public, reliés entre eux. Quel nom ?","explain":"Le cloud hybride : garder certaines données sur site (réglementation, existant) tout en profitant du cloud public pour le reste. Le modèle le plus répandu en entreprise.","accept":["cloud hybride","hybride","hybrid cloud"]},
  {"id":"az900-cl-capex","lvl":1,"dom":"Azure","q":"Dépense d'INVESTISSEMENT initiale (acheter des serveurs, construire un datacenter), amortie dans le temps. Quel sigle anglais ?","explain":"CapEx = Capital Expenditure. Le cloud remplace ce modèle par l'OpEx : payer au fil de l'usage, sans capital initial.","accept":["CapEx","capital expenditure"]},
  {"id":"az900-cl-opex","lvl":2,"dom":"Azure","q":"Dépense de FONCTIONNEMENT payée au fil de la consommation (l'abonnement cloud, l'électricité). Quel sigle anglais ?","explain":"OpEx = Operational Expenditure. C'est LE modèle économique du cloud : pas d'investissement initial, on paie ce qu'on consomme.","accept":["OpEx","operational expenditure"]},
  {"id":"az900-cl-ha","lvl":1,"dom":"Azure","q":"Capacité d'un système à rester DISPONIBLE et opérationnel malgré les pannes, souvent mesurée en % de temps de fonctionnement. Quel terme ?","explain":"La haute disponibilité (high availability) : obtenue par la redondance — plusieurs instances, plusieurs zones. Mesurée en « nines » : 99,9 %, 99,99 %…","accept":["haute disponibilite","high availability","disponibilite"]},
  {"id":"az900-cl-elasticity","lvl":3,"dom":"Azure","q":"Capacité d'un système à ajuster AUTOMATIQUEMENT ses ressources quand la demande monte ou descend. Quel terme ?","explain":"L'élasticité = la scalabilité rendue automatique (autoscaling). Le site e-commerce absorbe le Black Friday puis redescend tout seul — et la facture aussi.","accept":["elasticite","elasticity","elastique"]},
  {"id":"az900-cl-dr","lvl":2,"dom":"Azure","q":"Capacité à restaurer les systèmes et les données après un incident majeur (incendie, panne régionale). Quel terme (français ou anglais) ?","explain":"La reprise après sinistre (disaster recovery) : sauvegardes, réplication géographique, plans de bascule. Le cloud la rend abordable grâce à ses régions multiples.","accept":["reprise apres sinistre","disaster recovery","reprise d activite","dr"]},
  {"id":"az900-cl-shared","lvl":3,"dom":"Azure","q":"Modèle qui définit ce qui relève du FOURNISSEUR cloud et ce qui reste À TA CHARGE selon le type de service (IaaS/PaaS/SaaS). Quel nom (3 mots) ?","explain":"Le modèle de responsabilité partagée — un incontournable de l'examen. Plus tu montes vers le SaaS, plus le fournisseur prend en charge.","accept":["responsabilite partagee","modele de responsabilite partagee","shared responsibility"]},
  {"id":"az900-ar-region","lvl":1,"dom":"Azure","q":"Zone géographique contenant un ou plusieurs datacenters Azure reliés entre eux (ex : France Centre, West Europe). Quel terme ?","explain":"La région : l'unité géographique de base d'Azure (60+ dans le monde). Tu choisis une région pour la latence, la conformité et le prix — qui varient de l'une à l'autre.","accept":["region","une region"]},
  {"id":"az900-ar-az","lvl":2,"dom":"Azure","q":"À l'intérieur d'une région : datacenter(s) physiquement séparé(s), avec alimentation, refroidissement et réseau indépendants. Quel terme (français ou anglais) ?","explain":"La zone de disponibilité protège d'une panne de datacenter ENTIER. Les régions qui les proposent en ont au moins 3.","accept":["zone de disponibilite","availability zone","zones de disponibilite"]},
  {"id":"az900-ar-az-min","lvl":5,"dom":"Azure","q":"Combien de zones de disponibilité au MINIMUM dans une région qui les prend en charge ?","explain":"Au moins 3 zones, pour permettre un quorum et survivre à la perte d'une zone. Toutes les régions ne les proposent pas.","accept":["3","trois"]},
  {"id":"az900-ar-rg","lvl":3,"dom":"Azure","q":"Conteneur logique qui regroupe des ressources Azure partageant le même cycle de vie. Quel nom (français ou anglais) ?","explain":"Le groupe de ressources. Supprimer le groupe supprime tout son contenu — pratique pour les environnements de test.","accept":["groupe de ressources","resource group"]},
  {"id":"az900-ar-sub","lvl":1,"dom":"Azure","q":"Unité de FACTURATION et de gestion à laquelle toutes les ressources sont rattachées. Quel nom ?","explain":"L'abonnement : la frontière de facturation et de quotas. Une organisation en a souvent plusieurs (prod, dev, par département…).","accept":["abonnement","subscription","souscription"]},
  {"id":"az900-ar-mg","lvl":2,"dom":"Azure","q":"Niveau AU-DESSUS des abonnements, qui permet d'appliquer des politiques et des accès à plusieurs abonnements d'un coup. Quel nom ?","explain":"Le management group. Hiérarchie complète : management group → abonnement → groupe de ressources → ressource.","accept":["groupe d administration","management group","groupes d administration"]},
  {"id":"az900-ar-vm","lvl":3,"dom":"Azure","q":"Service Azure qui fournit un serveur virtualisé dont TU contrôles le système d'exploitation (IaaS). Quel nom ?","explain":"La machine virtuelle : l'IaaS de base. Contrôle total de l'OS — et responsabilité totale des patchs et de la sécurité de l'OS.","accept":["machine virtuelle","virtual machine","vm","machines virtuelles"]},
  {"id":"az900-ar-vmss","lvl":5,"dom":"Azure","q":"Service qui gère un GROUPE de VM identiques avec équilibrage de charge et mise à l'échelle automatique. Quel nom (anglais accepté) ?","explain":"Les VM Scale Sets : ajouter/retirer automatiquement des VM identiques selon la charge. La brique IaaS de l'élasticité.","accept":["vm scale set","virtual machine scale sets","scale set","groupes de machines virtuelles identiques"]},
  {"id":"az900-ar-appservice","lvl":1,"dom":"Azure","q":"Service PaaS pour héberger des applications web et des API sans gérer de serveurs. Quel nom ?","explain":"App Service : tu déploies ton code, Azure gère l'infrastructure, l'OS et la montée en charge.","accept":["app service","azure app service"]},
  {"id":"az900-ar-aci","lvl":4,"dom":"Azure","q":"Service qui exécute UN conteneur rapidement, sans orchestrateur ni VM à gérer, facturé à la seconde. Quel nom ?","explain":"Azure Container Instances : le moyen le plus simple de lancer un conteneur dans Azure.","accept":["container instances","azure container instances","aci"]},
  {"id":"az900-ar-aks","lvl":2,"dom":"Azure","q":"Service Azure d'ORCHESTRATION de conteneurs basé sur Kubernetes. Quel sigle ?","explain":"AKS = Azure Kubernetes Service : pour gérer des flottes de conteneurs (déploiement, scaling, réseau) — quand ACI ne suffit plus.","accept":["aks","azure kubernetes service"]},
  {"id":"az900-ar-functions","lvl":3,"dom":"Azure","q":"Service SERVERLESS qui exécute du code en réponse à des événements, facturé à l'exécution. Quel nom ?","explain":"Azure Functions : du code déclenché par un événement (requête HTTP, minuteur, message), sans aucun serveur à gérer.","accept":["functions","azure functions"]},
  {"id":"az900-ar-vnet","lvl":1,"dom":"Réseau","q":"Réseau privé dans Azure où tes ressources communiquent de façon isolée. Quel nom (sigle accepté) ?","explain":"Le réseau virtuel (VNet) : l'équivalent cloud de ton réseau d'entreprise, découpé en sous-réseaux (subnets).","accept":["reseau virtuel","virtual network","vnet"]},
  {"id":"az900-ar-peering","lvl":4,"dom":"Réseau","q":"Mécanisme qui relie DEUX réseaux virtuels pour qu'ils communiquent via le réseau privé de Microsoft (jamais par Internet). Quel terme anglais ?","explain":"Le peering fonctionne aussi entre régions différentes (global peering). Le trafic reste sur le backbone Microsoft.","accept":["peering","vnet peering","appairage"]},
  {"id":"az900-ar-er","lvl":2,"dom":"Réseau","q":"Connexion PRIVÉE et dédiée entre ton datacenter et Azure, qui ne transite JAMAIS par Internet public. Quel nom ?","explain":"ExpressRoute : bande passante garantie, latence stable, sécurité maximale — et coût bien supérieur au VPN.","accept":["expressroute","express route"]},
  {"id":"az900-ar-nsg","lvl":3,"dom":"Réseau","q":"Filtre de trafic réseau par règles (autoriser/refuser, port, source, destination) appliqué à un sous-réseau ou une carte réseau. Quel sigle ?","explain":"Le NSG : le pare-feu de base, gratuit, par règles à 5 éléments. Ex : bloquer le port 3389 (RDP) depuis Internet.","accept":["nsg","network security group","groupe de securite reseau"]},
  {"id":"az900-ar-blob","lvl":2,"dom":"Azure","q":"Service de stockage d'OBJETS pour données non structurées : images, vidéos, sauvegardes, documents. Quel nom ?","explain":"Le stockage Blob (Binary Large Object) : des fichiers de toute taille accessibles par URL, avec des niveaux d'accès pour optimiser les coûts.","accept":["blob","blob storage","stockage blob"]},
  {"id":"az900-ar-files","lvl":3,"dom":"Azure","q":"Service de PARTAGES de fichiers réseau (SMB) dans le cloud, montables comme un lecteur réseau classique. Quel nom ?","explain":"Azure Files remplace le serveur de fichiers d'entreprise : le lecteur Z: de tes utilisateurs, mais hébergé dans Azure.","accept":["azure files","files","fichiers azure"]},
  {"id":"az900-ar-azcopy","lvl":5,"dom":"Azure","q":"Outil en LIGNE DE COMMANDE optimisé pour copier des fichiers vers/depuis le stockage Azure. Quel nom ?","explain":"AzCopy : transferts massifs scriptables. Son pendant graphique est Azure Storage Explorer.","accept":["azcopy","az copy"]},
  {"id":"az900-ar-migrate","lvl":5,"dom":"Azure","q":"Service Azure qui ÉVALUE et orchestre la migration de tes serveurs, bases et applications sur site vers Azure. Quel nom ?","explain":"Azure Migrate : découverte du parc, estimation des coûts, compatibilité, puis pilotage de la migration. Le point de départ de tout projet de migration.","accept":["azure migrate","migrate"]},
  {"id":"az900-ar-databox","lvl":6,"dom":"Azure","q":"Appareil PHYSIQUE que Microsoft t'expédie pour transférer des dizaines de téraoctets vers Azure quand le réseau est trop lent. Quel nom ?","explain":"Data Box : on copie les données localement sur l'appareil, on le renvoie, Microsoft les charge dans ton compte de stockage.","accept":["data box","azure data box","databox"]},
  {"id":"az900-ar-entra","lvl":1,"dom":"Sécurité","q":"Service d'identité et d'annuaire cloud de Microsoft (anciennement Azure Active Directory). Quel nom actuel ?","explain":"Microsoft Entra ID : les comptes, l'authentification et les accès de tout l'écosystème Microsoft (Azure, M365).","accept":["microsoft entra id","entra id","entra"]},
  {"id":"az900-ar-mfa","lvl":2,"dom":"Sécurité","q":"Mécanisme qui exige AU MOINS DEUX preuves d'identité (mot de passe + code sur téléphone, par exemple). Quel sigle ?","explain":"La MFA bloque l'immense majorité des compromissions de comptes : voler un mot de passe ne suffit plus.","accept":["mfa","multifactor authentication","authentification multifacteur","multi factor authentication"]},
  {"id":"az900-ar-sso","lvl":3,"dom":"Sécurité","q":"Se connecter UNE seule fois et accéder à toutes ses applications sans retaper de mot de passe. Quel sigle ?","explain":"Le SSO : moins de mots de passe = moins de risques et moins de friction. Fourni par Entra ID pour des milliers d'applications.","accept":["sso","single sign on","authentification unique"]},
  {"id":"az900-ar-condaccess","lvl":6,"dom":"Sécurité","q":"Fonctionnalité d'Entra ID qui applique des règles « SI… ALORS » sur les connexions (si hors du réseau → exiger MFA ; si appareil inconnu → bloquer). Quel nom (2 mots) ?","explain":"L'accès conditionnel évalue des signaux (lieu, appareil, risque) et impose la réponse adaptée. Le cœur du contrôle d'accès moderne.","accept":["acces conditionnel","conditional access"]},
  {"id":"az900-ar-rbac","lvl":1,"dom":"Sécurité","q":"Système Azure qui attribue des RÔLES (Lecteur, Contributeur, Propriétaire…) à des utilisateurs sur un périmètre donné. Quel sigle ?","explain":"Le RBAC : QUI (identité) peut faire QUOI (rôle) sur QUEL périmètre (scope). Toujours donner le minimum nécessaire.","accept":["rbac","role based access control","controle d acces en fonction du role"]},
  {"id":"az900-ar-did","lvl":6,"dom":"Sécurité","q":"Stratégie de sécurité en COUCHES successives (physique, identité, périmètre, réseau, calcul, application, données) pour qu'aucune défense seule ne soit critique. Quel nom ?","explain":"La défense en profondeur : si une couche cède, les suivantes tiennent. L'attaquant doit toutes les franchir.","accept":["defense en profondeur","defense in depth"]},
  {"id":"az900-ar-defender","lvl":4,"dom":"Sécurité","q":"Service Azure qui évalue en continu ta POSTURE de sécurité (score, recommandations) et protège tes charges de travail. Quel nom ?","explain":"Microsoft Defender for Cloud : le « secure score », des recommandations concrètes et la protection des workloads (serveurs, stockage, conteneurs).","accept":["defender for cloud","microsoft defender for cloud","defender"]},
  {"id":"az900-go-pricingcalc","lvl":2,"dom":"SRE","q":"Outil en ligne gratuit qui ESTIME le coût mensuel futur des ressources Azure que tu prévois de déployer. Quel nom (2-3 mots) ?","explain":"La calculatrice de prix : tu composes ton architecture, elle chiffre. À ne pas confondre avec la calculatrice TCO (comparaison avec l'existant).","accept":["calculatrice de prix","pricing calculator","calculateur de prix"]},
  {"id":"az900-go-tco","lvl":3,"dom":"SRE","q":"Outil qui COMPARE le coût de ton datacenter actuel avec le coût équivalent dans Azure (matériel, électricité, personnel inclus). Quel sigle ?","explain":"La calculatrice TCO (Total Cost of Ownership) : l'outil pour convaincre une direction en chiffrant les économies d'une migration.","accept":["tco","calculatrice tco","total cost of ownership","tco calculator"]},
  {"id":"az900-go-costmgmt","lvl":1,"dom":"SRE","q":"Service Azure qui ANALYSE tes dépenses réelles, crée des budgets et envoie des alertes de dépassement. Quel nom ?","explain":"Cost Management : la vigie des dépenses EN COURS. Calculatrice de prix = avant ; Cost Management = pendant.","accept":["cost management","gestion des couts","microsoft cost management"]},
  {"id":"az900-go-tags","lvl":2,"dom":"SRE","q":"Étiquettes clé/valeur (ex : « departement = marketing ») posées sur les ressources pour les organiser et ventiler les coûts. Quel terme ?","explain":"Les tags : LE mécanisme de ventilation des coûts et d'organisation transverse (par projet, environnement, propriétaire…).","accept":["tags","tag","balises","etiquettes"]},
  {"id":"az900-go-policy","lvl":3,"dom":"Sécurité","q":"Service qui impose des RÈGLES sur les ressources (régions autorisées, tailles interdites, tags obligatoires) et audite la conformité. Quel nom ?","explain":"Azure Policy définit ce qui a le DROIT d'exister dans ton environnement. Complémentaire du RBAC (qui définit qui peut agir).","accept":["azure policy","policy"]},
  {"id":"az900-go-lock","lvl":1,"dom":"Sécurité","q":"Mécanisme qui empêche la SUPPRESSION ou la MODIFICATION accidentelle d'une ressource, même par son propriétaire. Quel nom (français ou anglais) ?","explain":"Le verrou de ressource : il s'applique à TOUT le monde, y compris les propriétaires, tant qu'il n'est pas retiré explicitement.","accept":["verrou","resource lock","lock","verrous de ressources"]},
  {"id":"az900-go-cloudshell","lvl":3,"dom":"Azure","q":"Terminal accessible directement DANS LE NAVIGATEUR depuis le portail, avec Azure CLI et PowerShell préinstallés, sans rien installer. Quel nom ?","explain":"Cloud Shell : un shell prêt à l'emploi (Bash ou PowerShell) depuis n'importe quel navigateur, déjà authentifié.","accept":["cloud shell","azure cloud shell","cloudshell"]},
  {"id":"az900-go-arc","lvl":6,"dom":"Azure","q":"Service qui ÉTEND la gestion Azure (policies, RBAC, inventaire) à des serveurs situés HORS d'Azure — sur site ou chez d'autres clouds. Quel nom ?","explain":"Azure Arc projette tes serveurs on-premises et multi-cloud DANS le portail Azure : une gouvernance unique pour tout le parc.","accept":["azure arc","arc"]},
  {"id":"az900-go-advisor","lvl":1,"dom":"Observabilité","q":"Service GRATUIT qui analyse tes ressources et te donne des RECOMMANDATIONS personnalisées (coûts, sécurité, fiabilité, performance). Quel nom ?","explain":"Azure Advisor : ton consultant intégré. Ses 5 catégories : fiabilité, sécurité, performances, coûts, excellence opérationnelle.","accept":["advisor","azure advisor"]},
  {"id":"az900-go-servicehealth","lvl":2,"dom":"Observabilité","q":"Service qui t'informe des INCIDENTS de la plateforme Azure et des MAINTENANCES planifiées qui concernent TES régions et services. Quel nom (2 mots) ?","explain":"Service Health : « est-ce qu'AZURE a un problème ? ». Personnalisé selon tes abonnements, avec alertes configurables.","accept":["service health","azure service health"]},
  {"id":"az900-go-monitor","lvl":3,"dom":"Observabilité","q":"Plateforme centrale qui collecte MÉTRIQUES et JOURNAUX de toutes tes ressources, avec tableaux de bord et alertes. Quel nom ?","explain":"Azure Monitor : le socle de l'observabilité. Log Analytics (requêtes KQL) et Application Insights (performance applicative) en font partie.","accept":["azure monitor","monitor"]},
  {"id":"awsd-v-codepipeline","lvl":2,"dom":"AWS","q":"Quel service AWS orchestre les étapes d'un pipeline CI/CD (source → build → test → déploiement) ?","explain":"CodePipeline est l'orchestrateur. CodeBuild compile, CodeDeploy déploie, CodeCommit héberge le Git — ne pas confondre leurs rôles, c'est la base du domaine SDLC (22 %).","accept":["CodePipeline","codepipeline","aws codepipeline"]},
  {"id":"awsd-v-codebuild","lvl":3,"dom":"AWS","q":"Quel service AWS compile le code, exécute les tests et produit les artefacts, piloté par un fichier buildspec ?","explain":"CodeBuild : service de build managé, facturé à la minute, configuré par buildspec.yml à la racine du dépôt.","accept":["CodeBuild","codebuild","aws codebuild"]},
  {"id":"awsd-v-codedeploy","lvl":1,"dom":"AWS","q":"Quel service AWS automatise le déploiement applicatif sur EC2, Lambda ou ECS, piloté par un fichier appspec ?","explain":"CodeDeploy gère les stratégies (in-place, blue/green, canary, linear) et les hooks du cycle de vie via appspec.yml (EC2) ou appspec.yaml (Lambda/ECS).","accept":["CodeDeploy","codedeploy","aws codedeploy"]},
  {"id":"awsd-v-codeartifact","lvl":2,"dom":"AWS","q":"Quel service AWS héberge des dépôts de packages privés (npm, pip, Maven, NuGet) avec des sources amont publiques ?","explain":"CodeArtifact = l'équivalent d'Azure Artifacts. Organisation : domaine → dépôt → packages, avec upstream vers npmjs/PyPI/Maven Central.","accept":["CodeArtifact","codeartifact","aws codeartifact"]},
  {"id":"awsd-v-buildspec","lvl":3,"dom":"CI/CD","q":"Comment s'appelle le fichier YAML qui décrit les phases d'un build CodeBuild ?","explain":"buildspec.yml à la racine du dépôt (ou défini en ligne dans le projet). Ses phases : install, pre_build, build, post_build.","accept":["buildspec.yml","buildspec","buildspec.yml","buildspec yml","buildspec yaml"]},
  {"id":"awsd-v-appspec","lvl":1,"dom":"CI/CD","q":"Comment s'appelle le fichier qui décrit comment CodeDeploy doit déployer l'application et quels hooks exécuter ?","explain":"appspec.yml (EC2/on-premises, avec sections files et hooks) ou appspec.yaml (Lambda/ECS, avec resources et hooks).","accept":["appspec.yml","appspec","appspec.yml","appspec yml","appspec yaml"]},
  {"id":"awsd-v-cfn","lvl":2,"dom":"Terraform","q":"Quel service AWS natif déploie l'infrastructure as code à partir de templates JSON ou YAML déclaratifs ?","explain":"CloudFormation. Concepts : template (le code), stack (l'instance déployée), change set (l'aperçu), StackSet (multi-comptes/régions).","accept":["CloudFormation","cloudformation","aws cloudformation","cfn"]},
  {"id":"awsd-v-cdk","lvl":3,"dom":"Terraform","q":"Quel framework AWS permet de définir l'infrastructure en TypeScript, Python ou Java, puis la compile (synthétise) en CloudFormation ?","explain":"L'AWS CDK : `cdk synth` génère le template CloudFormation, `cdk deploy` le déploie. Idéal quand on veut des boucles et de l'abstraction.","accept":["AWS CDK","cdk","aws cdk","cloud development kit"]},
  {"id":"awsd-v-sam","lvl":1,"dom":"Terraform","q":"Quelle extension de CloudFormation simplifie la définition d'applications serverless (Lambda, API Gateway, DynamoDB) ?","explain":"AWS SAM : une syntaxe raccourcie (Transform: AWS::Serverless-2016-10-31) qui se transforme en CloudFormation classique au déploiement.","accept":["AWS SAM","sam","aws sam","serverless application model"]},
  {"id":"awsd-v-changeset","lvl":3,"dom":"Terraform","q":"Quel objet CloudFormation permet de PRÉVISUALISER les modifications avant de les appliquer (équivalent du terraform plan) ?","explain":"Le change set liste les ressources ajoutées, modifiées ou remplacées. Crucial : il signale les remplacements (Replacement: True) qui détruisent la ressource.","accept":["change set","changeset","change sets"]},
  {"id":"awsd-v-drift","lvl":1,"dom":"Terraform","q":"Comment appelle-t-on l'écart entre la configuration décrite dans la stack et l'état réel des ressources (suite à une modification manuelle) ?","explain":"Le drift. CloudFormation propose la détection de drift ; AWS Config peut aussi surveiller la conformité en continu.","accept":["drift","derive","configuration drift"]},
  {"id":"awsd-v-stackset","lvl":2,"dom":"Terraform","q":"Quel objet CloudFormation déploie une même stack sur PLUSIEURS comptes et régions en une seule opération ?","explain":"Les StackSets : self-managed (rôles IAM que tu crées) ou service-managed (via AWS Organizations, avec auto-déploiement sur les nouveaux comptes).","accept":["StackSet","stackset","stack set","stacksets"]},
  {"id":"awsd-v-ssm","lvl":3,"dom":"AWS","q":"Quel service AWS regroupe Parameter Store, Session Manager, Run Command, Patch Manager et Automation ?","explain":"AWS Systems Manager (SSM). Omniprésent au DOP : configuration, accès sans SSH, patching, automatisation de la remédiation.","accept":["Systems Manager","systems manager","ssm","aws systems manager"]},
  {"id":"awsd-v-session-manager","lvl":1,"dom":"AWS","q":"Quelle fonctionnalité de Systems Manager ouvre un shell sur une instance SANS clé SSH, sans port 22 ouvert ni bastion ?","explain":"Session Manager : accès via l'agent SSM, tracé dans CloudTrail et enregistrable dans S3/CloudWatch Logs. LA réponse aux questions « supprimer les bastions et les clés SSH ».","accept":["Session Manager","session manager"]},
  {"id":"awsd-v-parameter-store","lvl":2,"dom":"AWS","q":"Quel composant de Systems Manager stocke des paramètres de configuration hiérarchiques, dont des SecureString chiffrées par KMS, gratuitement en tier standard ?","explain":"Parameter Store : gratuit (standard), mais SANS rotation automatique. Secrets Manager coûte plus cher mais gère la rotation native.","accept":["Parameter Store","parameter store","ssm parameter store"]},
  {"id":"awsd-v-secrets-manager","lvl":3,"dom":"Sécurité","q":"Quel service AWS stocke des secrets AVEC rotation automatique native (notamment pour RDS) ?","explain":"Secrets Manager. La distinction Parameter Store / Secrets Manager est une question quasi certaine : rotation automatique = Secrets Manager.","accept":["Secrets Manager","secrets manager","aws secrets manager"]},
  {"id":"awsd-v-cloudwatch","lvl":1,"dom":"Observabilité","q":"Quel service AWS collecte métriques, logs et déclenche des alarmes ?","explain":"CloudWatch : Metrics, Logs, Alarms, Dashboards, Logs Insights, Contributor Insights. Le cœur du domaine monitoring (15 %).","accept":["CloudWatch","cloudwatch","amazon cloudwatch"]},
  {"id":"awsd-v-cloudtrail","lvl":2,"dom":"AWS","q":"Quel service AWS enregistre QUI a fait QUOI sur l'API AWS (audit des appels d'API) ?","explain":"CloudTrail = audit des actions (qui/quoi/quand). CloudWatch = santé et performances. Confusion classique à l'examen.","accept":["CloudTrail","cloudtrail","aws cloudtrail"]},
  {"id":"awsd-v-config","lvl":3,"dom":"Sécurité","q":"Quel service AWS enregistre l'historique de configuration des ressources et évalue leur conformité via des règles ?","explain":"AWS Config : configuration items, règles managées ou custom, remédiation automatique via SSM Automation, conformance packs, agrégateur multi-comptes.","accept":["AWS Config","aws config","config"]},
  {"id":"awsd-v-eventbridge","lvl":1,"dom":"AWS","q":"Quel service AWS route les événements (changements d'état, appels d'API, planifications) vers des cibles comme Lambda ou SNS ?","explain":"EventBridge (ex-CloudWatch Events) : le pivot du domaine « réponse aux incidents » — détecter un événement puis déclencher une remédiation automatique.","accept":["EventBridge","eventbridge","amazon eventbridge","cloudwatch events"]},
  {"id":"awsd-v-sns","lvl":2,"dom":"AWS","q":"Quel service AWS diffuse un message en mode publication/abonnement vers plusieurs abonnés (e-mail, SMS, Lambda, SQS) ?","explain":"SNS = pub/sub, push, un message vers N abonnés. SQS = file, pull, un message consommé par un seul lecteur.","accept":["SNS","sns","amazon sns","simple notification service"]},
  {"id":"awsd-v-sqs","lvl":3,"dom":"AWS","q":"Quel service AWS fournit des files de messages permettant de découpler les composants et d'absorber les pics de charge ?","explain":"SQS : standard (débit illimité, ordre non garanti, at-least-once) ou FIFO (ordre garanti, exactly-once, 300-3000 msg/s).","accept":["SQS","sqs","amazon sqs","simple queue service"]},
  {"id":"awsd-v-xray","lvl":1,"dom":"Observabilité","q":"Quel service AWS fournit le traçage distribué pour suivre une requête à travers plusieurs microservices ?","explain":"X-Ray : service map, segments et sous-segments, analyse des latences. ServiceLens combine X-Ray, CloudWatch metrics et logs.","accept":["X-Ray","x-ray","xray","aws x-ray"]},
  {"id":"awsd-v-guardduty","lvl":2,"dom":"Sécurité","q":"Quel service AWS détecte les menaces en analysant CloudTrail, les VPC Flow Logs et les logs DNS par machine learning ?","explain":"GuardDuty = détection de menaces (comportement anormal, IP malveillante). Inspector = vulnérabilités logicielles. Macie = données sensibles dans S3.","accept":["GuardDuty","guardduty","amazon guardduty"]},
  {"id":"awsd-v-inspector","lvl":3,"dom":"Sécurité","q":"Quel service AWS scanne en continu les vulnérabilités (CVE) des instances EC2, images ECR et fonctions Lambda ?","explain":"Amazon Inspector : scan de vulnérabilités logicielles et d'exposition réseau, déclenché automatiquement à chaque nouveau déploiement ou nouvelle CVE publiée.","accept":["Amazon Inspector","inspector","amazon inspector"]},
  {"id":"awsd-v-macie","lvl":1,"dom":"Sécurité","q":"Quel service AWS découvre et classe les données sensibles (PII, cartes bancaires) stockées dans S3 ?","explain":"Macie utilise le ML pour repérer les données sensibles dans S3 — la réponse aux scénarios de conformité RGPD/PCI.","accept":["Macie","macie","amazon macie"]},
  {"id":"awsd-v-securityhub","lvl":2,"dom":"Sécurité","q":"Quel service AWS centralise et priorise les résultats de GuardDuty, Inspector, Macie et Config selon des standards (CIS, PCI DSS) ?","explain":"Security Hub = la vue unifiée de la posture de sécurité, multi-comptes, avec actions personnalisées vers EventBridge pour la remédiation.","accept":["Security Hub","security hub","aws security hub","securityhub"]},
  {"id":"awsd-v-organizations","lvl":3,"dom":"Sécurité","q":"Quel service AWS gère plusieurs comptes de façon centralisée, avec facturation consolidée et unités d'organisation (OU) ?","explain":"AWS Organizations : la base de toute stratégie multi-comptes, et le support des SCP, des StackSets service-managed et des politiques de sauvegarde.","accept":["AWS Organizations","organizations","aws organizations"]},
  {"id":"awsd-v-scp","lvl":1,"dom":"Sécurité","q":"Quel type de politique AWS Organizations définit le PLAFOND maximal de permissions d'un compte ou d'une OU (sigle) ?","explain":"Une SCP ne DONNE jamais de droit : elle limite ce que les politiques IAM peuvent accorder. Même l'utilisateur root du compte membre y est soumis.","accept":["SCP","scp","service control policy","service control policies"]},
  {"id":"awsd-v-asg","lvl":2,"dom":"AWS","q":"Quel service AWS ajuste automatiquement le nombre d'instances EC2 et remplace celles qui deviennent défaillantes (sigle) ?","explain":"L'Auto Scaling Group : min/max/desired, launch template, health checks (EC2 ou ELB), politiques de scaling et lifecycle hooks.","accept":["Auto Scaling Group","asg","auto scaling group","ec2 auto scaling","auto scaling"]},
  {"id":"awsd-v-route53","lvl":1,"dom":"Réseau","q":"Quel service AWS gère le DNS avec des politiques de routage (pondéré, latence, basculement, géolocalisation) ?","explain":"Route 53 : routage pondéré (canary/blue-green), failover (avec health checks) et latence. Un pilier de la résilience multi-régions.","accept":["Route 53","route 53","route53","amazon route 53"]},
  {"id":"awsd-v-bluegreen","lvl":2,"dom":"CI/CD","q":"Quelle stratégie déploie sur un environnement parallèle complet puis bascule tout le trafic d'un coup, avec rollback immédiat ?","explain":"Blue/green : deux environnements, bascule par DNS ou par target group ELB. CodeDeploy le supporte nativement pour EC2, Lambda et ECS.","accept":["blue/green","blue green","blue/green","bluegreen","bleu vert"]},
  {"id":"awsd-v-canary","lvl":3,"dom":"CI/CD","q":"Quelle stratégie envoie d'abord un petit pourcentage du trafic vers la nouvelle version, puis bascule le reste après une période d'observation ?","explain":"Canary. Chez CodeDeploy Lambda/ECS : Canary10Percent5Minutes = 10 % pendant 5 min, puis 100 %. Le linear, lui, monte par paliers réguliers.","accept":["canary","canari"]},
  {"id":"awsd-v-appconfig","lvl":2,"dom":"CI/CD","q":"Quel composant de Systems Manager déploie progressivement des changements de CONFIGURATION applicative, avec rollback automatique sur alarme CloudWatch ?","explain":"AppConfig : valide la config (JSON Schema ou Lambda), la déploie par paliers et revient en arrière si une alarme se déclenche. Sans redéployer le code.","accept":["AppConfig","appconfig","aws appconfig","ssm appconfig"]},
  {"id":"awsd-v-ecr","lvl":1,"dom":"Docker","q":"Quel service AWS héberge les images de conteneurs privées, avec scan de vulnérabilités et politiques de cycle de vie ?","explain":"ECR : scan à la poussée (basic) ou continu via Inspector (enhanced), lifecycle policies pour purger les vieilles images, réplication inter-régions.","accept":["ECR","ecr","amazon ecr","elastic container registry"]},
  {"id":"awsd-v-instance-profile","lvl":1,"dom":"Sécurité","q":"Quel objet IAM permet d'attacher un rôle à une instance EC2 pour qu'elle obtienne des credentials temporaires sans clés stockées ?","explain":"L'instance profile est le conteneur du rôle attaché à l'EC2. Les credentials sont récupérés via l'IMDS (169.254.169.254) — l'équivalent de la managed identity Azure.","accept":["instance profile","profil d instance","iam instance profile"]},
  {"id":"awsd-v-sts","lvl":2,"dom":"Sécurité","q":"Quel service AWS délivre les credentials temporaires lors d'un AssumeRole (sigle) ?","explain":"STS : AssumeRole, AssumeRoleWithWebIdentity (OIDC pour GitHub Actions !), GetSessionToken. Les credentials expirent (15 min à 12 h).","accept":["STS","sts","security token service","aws sts"]},
  {"id":"awsd-v-kms","lvl":1,"dom":"AWS","q":"Quel service AWS gère les clés de chiffrement utilisées par S3, EBS, RDS, Secrets Manager (sigle) ?","explain":"KMS : clés managées par AWS ou par le client (CMK), avec key policies, rotation annuelle automatique et traçabilité dans CloudTrail.","accept":["KMS","kms","aws kms","key management service"]},
  {"id":"awsd-v-mttr","lvl":2,"dom":"AWS","q":"Quelle métrique mesure le temps moyen de restauration du service après un incident (sigle) ?","explain":"MTTR. Le domaine « réponse aux incidents » (14 %) vise justement à le réduire par la détection et la remédiation automatiques.","accept":["MTTR","mttr","mean time to recovery","mean time to restore"]},
  {"id":"awsd-f-buildspec-artifacts","lvl":6,"dom":"CI/CD","q":"Quelle section du buildspec définit les fichiers à transmettre à l'étape suivante du pipeline ?","explain":"La section artifacts (files, base-directory, discard-paths). Sans elle, le build produit des logs mais aucun livrable exploitable.","accept":["artifacts"]},
  {"id":"awsd-f-buildspec-reports","lvl":4,"dom":"CI/CD","q":"Quelle section du buildspec publie les résultats de tests et la couverture de code dans la console CodeBuild ?","explain":"reports: avec un report group, des files et un file-format (JUNITXML, CUCUMBERJSON, COBERTURAXML, JACOCOXML…). Alimente les tendances de tests.","accept":["reports","report groups"]},
  {"id":"awsd-f-appspec-hooks-ecs","lvl":6,"dom":"CI/CD","q":"Dans un déploiement blue/green ECS, quel hook permet de tester la nouvelle version sur le listener de TEST avant toute bascule (nom exact) ?","explain":"Ordre ECS : BeforeInstall → AfterInstall → AfterAllowTestTraffic → BeforeAllowTraffic → AfterAllowTraffic. Le listener de test permet de valider sans exposer les vrais utilisateurs.","accept":["AfterAllowTestTraffic","after allow test traffic"]},
  {"id":"awsd-f-codeartifact-upstream","lvl":4,"dom":"AWS","q":"Quel mécanisme d'un dépôt CodeArtifact relaie et met en cache les packages d'une source publique comme npmjs ou PyPI (2 mots) ?","explain":"L'upstream : un seul endpoint pour les développeurs, mise en cache locale des packages publics, protection contre leur suppression amont.","accept":["upstream repository","upstream","upstream repositories","source amont"]},
  {"id":"awsd-f-cfn-sections","lvl":5,"dom":"Terraform","q":"Quelle est la SEULE section obligatoire d'un template CloudFormation ?","explain":"Resources. Toutes les autres (Parameters, Mappings, Conditions, Outputs, Metadata, Transform, Description) sont facultatives.","accept":["Resources","resources"]},
  {"id":"awsd-f-cfn-sub","lvl":4,"dom":"Terraform","q":"Quelle fonction intrinsèque CloudFormation permet d'insérer des variables dans une chaîne, par exemple \"arn:aws:s3:::${NomBucket}\" ?","explain":"!Sub. Bien plus lisible que !Join. Variante avec map de substitution : !Sub ['texte ${cle}', {cle: valeur}].","accept":["!Sub","sub","!sub","fn::sub","fn sub"]},
  {"id":"awsd-f-cfn-deletionpolicy","lvl":4,"dom":"Terraform","q":"Quel attribut CloudFormation empêche la suppression d'une ressource critique (base de données) quand la stack est supprimée ?","explain":"DeletionPolicy: Retain (garder) ou Snapshot (sauvegarder avant suppression). UpdateReplacePolicy fait de même lors d'un remplacement.","accept":["DeletionPolicy","deletionpolicy","deletion policy"]},
  {"id":"awsd-f-cfn-updatepolicy","lvl":6,"dom":"Terraform","q":"Quel attribut CloudFormation contrôle la mise à jour progressive des instances d'un Auto Scaling Group (rolling update) ?","explain":"UpdatePolicy avec AutoScalingRollingUpdate (MinInstancesInService, MaxBatchSize, PauseTime, WaitOnResourceSignals) — le rolling deployment natif de CloudFormation.","accept":["UpdatePolicy","updatepolicy","update policy"]},
  {"id":"awsd-f-beanstalk-swap","lvl":6,"dom":"AWS","q":"Quelle opération Elastic Beanstalk réalise un blue/green en échangeant les URL de deux environnements ?","explain":"Swap Environment URLs : les CNAME sont échangés, la bascule est quasi instantanée et réversible. Attention aux migrations de base de données.","accept":["swap cname","swap environment urls","swap url","swap"]},
  {"id":"awsd-f-ebextensions","lvl":4,"dom":"AWS","q":"Quel dossier du code source permet de personnaliser la configuration d'un environnement Elastic Beanstalk (fichiers .config) ?","explain":".ebextensions/*.config (YAML ou JSON) : packages, files, commands, container_commands, option_settings, ressources CloudFormation additionnelles.","accept":[".ebextensions","ebextensions"]},
  {"id":"awsd-f-asg-lifecycle","lvl":5,"dom":"AWS","q":"Quel mécanisme d'un Auto Scaling Group met une instance en pause (état Pending:Wait ou Terminating:Wait) pour exécuter une action avant sa mise en service ou sa suppression (2 mots) ?","explain":"Le lifecycle hook : installer l'app avant la mise en service, ou récupérer les logs avant la terminaison. On termine par CompleteLifecycleAction.","accept":["lifecycle hook","lifecycle hooks","hook de cycle de vie"]},
  {"id":"awsd-f-asg-warmpool","lvl":6,"dom":"AWS","q":"Quelle fonctionnalité d'ASG maintient un pool d'instances pré-initialisées et arrêtées, pour un scale-out quasi instantané (2 mots) ?","explain":"Les warm pools réduisent drastiquement le temps de démarrage quand le bootstrap est long, en ne payant que le stockage des instances arrêtées.","accept":["warm pool","warm pools","pool chaud"]},
  {"id":"awsd-f-asg-refresh","lvl":4,"dom":"AWS","q":"Quelle opération d'ASG remplace progressivement toutes les instances par lots pour appliquer un nouveau launch template (2 mots) ?","explain":"Instance refresh : MinHealthyPercentage, InstanceWarmup et checkpoints. C'est le rolling update natif de l'ASG, avec rollback possible.","accept":["instance refresh","rafraichissement d instances"]},
  {"id":"awsd-f-alb-deregistration","lvl":4,"dom":"AWS","q":"Quel réglage d'un target group laisse aux connexions en cours le temps de se terminer avant de retirer une cible (2 mots, terme anglais) ?","explain":"Deregistration delay (ex-connection draining), 300 s par défaut. Trop long = déploiements lents ; trop court = requêtes coupées.","accept":["deregistration delay","connection draining","delai de desinscription"]},
  {"id":"awsd-f-dynamodb-global","lvl":5,"dom":"AWS","q":"Quelle fonctionnalité DynamoDB fournit une réplication multi-régions active/active (2 mots) ?","explain":"Global Tables : écriture dans n'importe quelle région, résolution des conflits en last-writer-wins. Base d'une architecture multi-site active/active.","accept":["Global Tables","global tables","global table","tables globales"]},
  {"id":"awsd-f-sqs-dlq","lvl":4,"dom":"AWS","q":"Quel paramètre de la redrive policy SQS détermine après combien d'échecs un message part en dead-letter queue ?","explain":"maxReceiveCount dans la redrive policy. La DLQ doit être du même type (standard/FIFO) que la file source.","accept":["maxReceiveCount","maxreceivecount","max receive count"]},
  {"id":"awsd-f-cw-metric-filter","lvl":6,"dom":"AWS","q":"Quel objet CloudWatch Logs transforme un motif texte trouvé dans les logs en métrique numérique, sur laquelle on peut poser une alarme (2 mots) ?","explain":"Metric filter : compte les occurrences (ex : « ERROR ») et publie une métrique custom. C'est LA façon d'alarmer sur un contenu de log.","accept":["metric filter","metric filters","filtre de metrique"]},
  {"id":"awsd-f-cw-composite","lvl":4,"dom":"AWS","q":"Quel type d'alarme CloudWatch combine plusieurs alarmes par une expression logique (AND/OR) pour réduire le bruit (2 mots) ?","explain":"L'alarme composite ne notifie que si plusieurs conditions sont réunies — l'antidote à la fatigue d'alerte lors d'incidents en cascade.","accept":["composite alarm","composite alarms","alarme composite"]},
  {"id":"awsd-f-cw-anomaly","lvl":6,"dom":"AWS","q":"Quelle fonctionnalité CloudWatch apprend le comportement normal d'une métrique et alarme sur les écarts, sans seuil fixe (2 mots) ?","explain":"Anomaly detection : bande de confiance apprise par ML. Idéal pour les métriques saisonnières où un seuil statique génère trop de faux positifs.","accept":["anomaly detection","detection d anomalies"]},
  {"id":"awsd-f-s3-objectlock","lvl":5,"dom":"Sécurité","q":"Quelle fonctionnalité S3 empêche la suppression ou la modification d'objets pendant une durée définie, en mode WORM (2 mots) ?","explain":"S3 Object Lock : mode Governance (contournable avec une permission spéciale) ou Compliance (personne, pas même root). Exige le versioning.","accept":["Object Lock","object lock","s3 object lock","verrouillage d objets"]},
  {"id":"awsd-f-cloudtrail-validation","lvl":6,"dom":"AWS","q":"Quelle option de CloudTrail permet de prouver qu'un fichier de log n'a pas été modifié après son écriture (3 mots) ?","explain":"Log file validation génère des fichiers digest signés. Combiné à S3 Object Lock, il garantit l'intégrité exigée par les audits.","accept":["log file validation","validation des fichiers journaux","log file integrity validation"]},
  {"id":"awsd-c-buildspec-version","lvl":6,"dom":"AWS","q":"Complète la clé obligatoire en tête d'un buildspec :","explain":"version: 0.2 est la syntaxe actuelle (0.1 exécutait chaque commande dans son propre shell — les variables ne se propageaient pas).","accept":["version"]},
  {"id":"awsd-c-buildspec-artifacts","lvl":4,"dom":"AWS","q":"Complète la section qui déclare les fichiers à transmettre à l'étape suivante :","explain":"base-directory évite de reproduire l'arborescence complète ; discard-paths: yes aplatit la structure.","accept":["artifacts"]},
  {"id":"awsd-c-appspec-ec2","lvl":5,"dom":"AWS","q":"Complète la section qui déclare les scripts du cycle de vie :","explain":"Chaque hook accepte location, timeout et runas. La section files ne concerne que les déploiements EC2/on-premises.","accept":["hooks"]},
  {"id":"awsd-c-appspec-lambda","lvl":9,"dom":"AWS","q":"Complète le hook exécuté AVANT que le trafic ne soit envoyé à la nouvelle version :","explain":"Lambda n'a que deux hooks : BeforeAllowTraffic et AfterAllowTraffic. Chacun pointe vers une fonction de validation qui appelle PutLifecycleEventHookExecutionStatus.","accept":["BeforeAllowTraffic","before allow traffic"]},
  {"id":"awsd-c-cfn-condition","lvl":7,"dom":"Terraform","q":"Complète l'attribut qui ne crée cette ressource que si la condition est vraie :","explain":"Condition: NomCondition sur une ressource = création conditionnelle. On peut aussi l'utiliser dans un Output ou avec !If dans une propriété.","accept":["Condition","condition"]},
  {"id":"awsd-c-cfn-deletionpolicy","lvl":4,"dom":"Terraform","q":"Complète l'attribut qui déclenche une sauvegarde avant suppression de la ressource :","explain":"DeletionPolicy: Snapshot (ou Retain). Sans lui, supprimer la stack détruit la base et ses données — définitivement.","accept":["DeletionPolicy","deletionpolicy","deletion policy"]},
  {"id":"awsd-c-cfn-stackset","lvl":7,"dom":"Terraform","q":"Complète le modèle de permission requis pour l'auto-deployment via AWS Organizations :","explain":"L'auto-deployment sur les nouveaux comptes d'une OU n'existe qu'en SERVICE_MANAGED. En SELF_MANAGED, tu fournis toi-même les rôles IAM.","accept":["SERVICE_MANAGED","service managed","service-managed"]},
  {"id":"awsd-c-logs-parse","lvl":9,"dom":"AWS","q":"Complète l'opérateur qui extrait des champs d'un message non structuré :","explain":"parse avec un glob (ou une regex) transforme un log texte en champs exploitables — indispensable quand l'application ne logue pas en JSON.","accept":["parse"]},
  {"id":"awsd-c-cw-alarm-cli","lvl":4,"dom":"AWS","q":"Complète le paramètre qui définit la durée (en secondes) de chaque période d'évaluation :","explain":"period × evaluation-periods = la fenêtre totale. Ici 2 périodes de 300 s : l'alarme se déclenche après 10 minutes de dépassement continu.","accept":["period"]},
  {"id":"awsd-c-asg-hook-cli","lvl":7,"dom":"AWS","q":"Complète le verbe de la commande qui libère l'instance du hook :","explain":"complete-lifecycle-action avec CONTINUE (ou ABANDON). Sans cet appel, l'instance reste en Pending:Wait jusqu'au timeout du hook.","accept":["complete"]},
  {"id":"awsd-csA-secrets","lvl":8,"dom":"AWS","q":"Les mots de passe de base de données sont en clair dans les fichiers de configuration déployés. Quel service AWS recommandes-tu pour les stocker AVEC rotation automatique ?","explain":"Secrets Manager pour la rotation native RDS. Parameter Store SecureString conviendrait pour des secrets sans besoin de rotation, et gratuitement.","accept":["Secrets Manager","secrets manager","aws secrets manager"]},
  {"id":"awsd-csA-metrics","lvl":9,"dom":"AWS","q":"La direction veut mesurer objectivement le progrès de la transformation. Quel référentiel de 4 métriques proposes-tu (sigle) ?","explain":"DORA : fréquence de déploiement, lead time, change failure rate, MTTR. Sur AWS, on les dérive des événements CodePipeline/CodeDeploy captés par EventBridge.","accept":["DORA","dora","metriques dora","dora metrics"]},
  {"id":"awsd-csB-region","lvl":8,"dom":"AWS","q":"Aucune ressource ne doit pouvoir être créée hors d'Europe, même par un administrateur de compte. Quel type de politique Organizations utilises-tu (sigle) ?","explain":"Une SCP avec condition aws:RequestedRegion s'impose à tous les principals du compte membre, root inclus. Une policy IAM serait contournable par un admin local.","accept":["SCP","scp","service control policy"]},
  {"id":"awsd-csC-trace","lvl":9,"dom":"AWS","q":"Une requête lente traverse 12 microservices. Quel service AWS permet de localiser le maillon responsable par traçage distribué ?","explain":"X-Ray corrèle les segments par trace ID et affiche la service map. Sans lui, analyser 12 services indépendamment revient à deviner.","accept":["X-Ray","x-ray","xray","aws x-ray"]},
  {"id":"clf-co-iaas","lvl":3,"dom":"AWS","q":"Modèle où AWS fournit l'infrastructure (serveurs, réseau) et où TU gères le système d'exploitation (ex : EC2). Quel sigle ?","explain":"IaaS : le maximum de contrôle et de responsabilité. EC2 en est l'exemple type chez AWS.","accept":["IaaS","infrastructure as a service"]},
  {"id":"clf-co-paas","lvl":1,"dom":"AWS","q":"Modèle où tu déploies juste ton code, la plateforme gérant l'OS et l'infrastructure (ex : Elastic Beanstalk). Quel sigle ?","explain":"PaaS : Elastic Beanstalk déploie ton application et gère pour toi les serveurs, l'équilibrage et le scaling en dessous.","accept":["PaaS","platform as a service"]},
  {"id":"clf-co-saas","lvl":2,"dom":"AWS","q":"Modèle où tu utilises un logiciel fini via Internet sans rien administrer. Quel sigle ?","explain":"SaaS : le fournisseur gère tout, tu utilises. Tu restes responsable de tes données et de tes accès.","accept":["SaaS","software as a service"]},
  {"id":"clf-co-capex","lvl":3,"dom":"AWS","q":"Dépense d'investissement initiale (acheter des serveurs), que le cloud permet d'éviter. Quel sigle anglais ?","explain":"CapEx → OpEx : la transformation économique centrale du cloud. Pas d'avance de capital, une dépense au fil de l'usage.","accept":["CapEx","capital expenditure"]},
  {"id":"clf-co-elasticity","lvl":1,"dom":"AWS","q":"Capacité à ajuster AUTOMATIQUEMENT les ressources à la demande (à la hausse comme à la baisse). Quel terme ?","explain":"L'élasticité : le duo Auto Scaling + paiement à l'usage. On absorbe les pics sans payer les creux.","accept":["elasticite","elasticity"]},
  {"id":"clf-co-ha","lvl":2,"dom":"AWS","q":"Capacité d'un système à rester opérationnel malgré les pannes, obtenue par la redondance multi-AZ. Quel terme (2 mots) ?","explain":"La haute disponibilité : chez AWS, elle passe d'abord par le déploiement sur plusieurs zones de disponibilité.","accept":["haute disponibilite","high availability"]},
  {"id":"clf-co-serverless-def","lvl":3,"dom":"AWS","q":"Modèle où tu exécutes du code sans provisionner ni gérer de serveurs, facturé à l'exécution (ex : Lambda). Quel terme ?","explain":"Serverless : AWS gère toute l'infrastructure, tu fournis le code. Lambda, Fargate, DynamoDB, S3 relèvent de cette famille.","accept":["serverless","sans serveur"]},
  {"id":"clf-se-iam","lvl":1,"dom":"Sécurité","q":"Service AWS qui gère les utilisateurs, groupes, rôles et permissions d'accès aux ressources. Quel sigle ?","explain":"IAM (Identity and Access Management) : le contrôle d'accès de tout AWS. Gratuit, global (pas lié à une région).","accept":["IAM","identity and access management"]},
  {"id":"clf-se-leastpriv","lvl":2,"dom":"Sécurité","q":"Principe de sécurité consistant à n'accorder QUE les permissions strictement nécessaires à une tâche. Quel nom (3 mots) ?","explain":"Le moindre privilège : commencer par zéro permission et ajouter le minimum. La réponse attendue dès qu'une question parle de permissions excessives.","accept":["moindre privilege","principe du moindre privilege","least privilege"]},
  {"id":"clf-se-mfa","lvl":3,"dom":"Sécurité","q":"Mécanisme exigeant une DEUXIÈME preuve d'identité en plus du mot de passe (application, clé physique). Quel sigle ?","explain":"La MFA : à activer en priorité sur le root et les comptes à privilèges. Bloque l'essentiel des compromissions de comptes.","accept":["MFA","multi factor authentication","authentification multifacteur"]},
  {"id":"clf-se-guardduty","lvl":1,"dom":"AWS","q":"Service de DÉTECTION DES MENACES qui analyse par machine learning les logs (CloudTrail, DNS, flux réseau) pour repérer les comportements malveillants. Quel nom ?","explain":"GuardDuty = le détecteur de menaces : compte compromis, minage de crypto, IP malveillantes. Activation en un clic, sans agent.","accept":["guardduty","amazon guardduty"]},
  {"id":"clf-se-inspector","lvl":2,"dom":"AWS","q":"Service qui SCANNE les instances EC2 et les images de conteneurs à la recherche de VULNÉRABILITÉS logicielles (CVE). Quel nom ?","explain":"Inspector = vulnérabilités (logiciels non patchés, exposition réseau). À distinguer de GuardDuty (menaces actives) et Macie (données sensibles).","accept":["inspector","amazon inspector"]},
  {"id":"clf-se-macie","lvl":3,"dom":"AWS","q":"Service qui découvre et classifie les DONNÉES SENSIBLES (données personnelles, numéros de carte) stockées dans S3. Quel nom ?","explain":"Macie = données sensibles dans S3, par machine learning. La réponse aux scénarios RGPD/PII.","accept":["macie","amazon macie"]},
  {"id":"clf-se-waf","lvl":1,"dom":"AWS","q":"Pare-feu APPLICATIF qui filtre les requêtes web malveillantes (injection SQL, XSS) devant CloudFront ou un load balancer. Quel sigle ?","explain":"Le WAF travaille au niveau 7 (contenu des requêtes HTTP). Shield = volumétrie DDoS ; WAF = attaques applicatives. Distinction très testée.","accept":["WAF","aws waf","web application firewall"]},
  {"id":"clf-se-kms","lvl":2,"dom":"AWS","q":"Service AWS de création et gestion des CLÉS de chiffrement, intégré à S3, EBS, RDS… Quel sigle ?","explain":"KMS gère les clés (création, rotation, permissions) — chaque utilisation est tracée dans CloudTrail. CloudHSM existe pour le matériel dédié.","accept":["KMS","key management service","aws kms"]},
  {"id":"clf-se-secrets","lvl":4,"dom":"AWS","q":"Service qui stocke des SECRETS (mots de passe de bases, clés d'API) avec ROTATION automatique. Quel nom (2 mots) ?","explain":"Secrets Manager : fini les mots de passe dans le code — l'application les récupère à l'exécution, et la rotation est automatisée.","accept":["secrets manager","aws secrets manager"]},
  {"id":"clf-se-cloudtrail","lvl":3,"dom":"AWS","q":"Service qui enregistre QUI a fait QUOI sur l'API AWS (chaque appel, chaque console) à des fins d'audit. Quel nom ?","explain":"CloudTrail = le journal d'audit : qui, quoi, quand, depuis où. À ne pas confondre avec CloudWatch (métriques et performances).","accept":["cloudtrail","aws cloudtrail"]},
  {"id":"clf-se-config","lvl":6,"dom":"AWS","q":"Service qui enregistre l'HISTORIQUE de configuration des ressources et évalue leur CONFORMITÉ à des règles. Quel nom (2 mots) ?","explain":"AWS Config répond à « cette ressource est-elle restée conforme dans le temps ? » — bucket public, chiffrement absent, etc.","accept":["aws config","config"]},
  {"id":"clf-se-artifact","lvl":5,"dom":"Sécurité","q":"Portail en libre-service où télécharger les RAPPORTS de conformité d'AWS (ISO, SOC, PCI) pour tes auditeurs. Quel nom ?","explain":"AWS Artifact : les preuves de conformité d'AWS, à la demande. La réponse dès qu'un auditeur demande « les certifications d'AWS ».","accept":["artifact","aws artifact"]},
  {"id":"clf-te-region","lvl":1,"dom":"AWS","q":"Zone géographique AWS composée de plusieurs zones de disponibilité isolées (ex : eu-west-3 à Paris). Quel terme ?","explain":"La région AWS : on choisit selon la latence, la conformité, le prix et la disponibilité des services. Paris = eu-west-3.","accept":["region","une region"]},
  {"id":"clf-te-az","lvl":2,"dom":"AWS","q":"Un ou plusieurs datacenters isolés au sein d'une région, avec alimentation et réseau indépendants. Quel terme (sigle accepté) ?","explain":"L'AZ : l'unité de résilience d'AWS. Chaque région en compte AU MOINS 3, reliées par des liens à très faible latence.","accept":["zone de disponibilite","availability zone","az"]},
  {"id":"clf-te-az-min","lvl":6,"dom":"AWS","q":"Combien de zones de disponibilité au minimum dans chaque région AWS ?","explain":"Minimum 3 AZ par région (contrairement à Azure où certaines régions n'en ont pas). Déployer sur ≥ 2 AZ = la base de la haute disponibilité.","accept":["3","trois"]},
  {"id":"clf-te-ec2","lvl":3,"dom":"AWS","q":"Service de MACHINES VIRTUELLES d'AWS, dont tu contrôles le système d'exploitation. Quel sigle ?","explain":"EC2 (Elastic Compute Cloud) : l'IaaS d'AWS. Familles d'instances : usage général, optimisées calcul, mémoire, stockage…","accept":["EC2","elastic compute cloud","amazon ec2"]},
  {"id":"clf-te-lambda","lvl":1,"dom":"AWS","q":"Service SERVERLESS qui exécute du code en réponse à des événements, facturé à la milliseconde d'exécution. Quel nom ?","explain":"Lambda : zéro serveur à gérer, mise à l'échelle automatique, facturation à l'exécution. Limite de durée : 15 minutes par exécution.","accept":["lambda","aws lambda"]},
  {"id":"clf-te-fargate","lvl":6,"dom":"AWS","q":"Moteur SERVERLESS pour ECS/EKS : les conteneurs tournent sans qu'on gère AUCUNE instance EC2. Quel nom ?","explain":"Fargate = conteneurs sans serveurs : tu paies la tâche (vCPU/mémoire), AWS gère les machines. « Conteneurs sans gérer d'instances » → Fargate.","accept":["fargate","aws fargate"]},
  {"id":"clf-te-beanstalk","lvl":4,"dom":"AWS","q":"Service PaaS qui déploie automatiquement une application web (code fourni) en gérant serveurs, équilibrage et scaling. Quel nom (2 mots) ?","explain":"Elastic Beanstalk : tu fournis le code, il provisionne tout — tout en te laissant l'accès aux ressources sous-jacentes.","accept":["elastic beanstalk","beanstalk"]},
  {"id":"clf-te-s3","lvl":2,"dom":"AWS","q":"Service de stockage d'OBJETS d'AWS, quasi illimité, où les fichiers sont rangés dans des « buckets ». Quel sigle ?","explain":"S3 (Simple Storage Service) : durabilité de « 11 neufs » (99,999999999 %), l'épine dorsale du stockage AWS.","accept":["S3","simple storage service","amazon s3"]},
  {"id":"clf-te-ebs","lvl":6,"dom":"AWS","q":"Stockage en mode BLOC attaché à une instance EC2, comme un disque dur virtuel persistant. Quel sigle ?","explain":"EBS (Elastic Block Store) : le disque des EC2, persistant indépendamment de l'instance, sauvegardable par snapshots.","accept":["EBS","elastic block store"]},
  {"id":"clf-te-rds","lvl":3,"dom":"AWS","q":"Service de bases de données RELATIONNELLES managées (MySQL, PostgreSQL, SQL Server…) : AWS gère les sauvegardes, les correctifs et la réplication. Quel sigle ?","explain":"RDS = le SQL managé. Multi-AZ pour la haute dispo, read replicas pour la montée en charge en lecture.","accept":["RDS","relational database service"]},
  {"id":"clf-te-aurora","lvl":4,"dom":"AWS","q":"Base relationnelle MAISON d'AWS, compatible MySQL et PostgreSQL, jusqu'à 5 fois plus performante. Quel nom ?","explain":"Aurora : la base relationnelle cloud-native d'AWS (réplication sur 6 copies, 3 AZ). Existe en version Serverless.","accept":["aurora","amazon aurora"]},
  {"id":"clf-te-dynamo","lvl":1,"dom":"AWS","q":"Base NoSQL clé-valeur SERVERLESS d'AWS, à latence milliseconde quelle que soit l'échelle. Quel nom ?","explain":"DynamoDB : le NoSQL massivement scalable, sans serveur à gérer. « NoSQL » ou « clé-valeur » dans l'énoncé → DynamoDB.","accept":["dynamodb","dynamo db","amazon dynamodb"]},
  {"id":"clf-te-redshift","lvl":6,"dom":"AWS","q":"ENTREPÔT DE DONNÉES (data warehouse) d'AWS pour l'analytique sur des pétaoctets. Quel nom ?","explain":"Redshift = l'analytique décisionnelle à grande échelle. « Data warehouse » ou « analyse de données massives » → Redshift.","accept":["redshift","amazon redshift"]},
  {"id":"clf-te-vpc","lvl":2,"dom":"Réseau","q":"Réseau PRIVÉ virtuel isolé dans AWS où tu déploies tes ressources. Quel sigle ?","explain":"Le VPC (Virtual Private Cloud) : ton réseau dans AWS, découpé en sous-réseaux publics et privés répartis sur les AZ.","accept":["VPC","virtual private cloud"]},
  {"id":"clf-te-route53","lvl":3,"dom":"Réseau","q":"Service DNS managé d'AWS (résolution de noms, routage, health checks). Quel nom ?","explain":"Route 53 : DNS + politiques de routage (latence, failover, géolocalisation) + enregistrement de domaines.","accept":["route 53","route53","amazon route 53"]},
  {"id":"clf-te-cloudfront","lvl":1,"dom":"Réseau","q":"Réseau de diffusion de contenu (CDN) d'AWS qui met le contenu en cache dans les emplacements périphériques mondiaux. Quel nom ?","explain":"CloudFront : servir images, vidéos et sites au plus près des utilisateurs via 400+ edge locations. « Réduire la latence mondiale d'un site » → CloudFront.","accept":["cloudfront","amazon cloudfront"]},
  {"id":"clf-te-dx","lvl":5,"dom":"Réseau","q":"Connexion réseau PRIVÉE et dédiée entre ton datacenter et AWS, qui ne passe PAS par Internet. Quel nom (2 mots) ?","explain":"Direct Connect = l'équivalent AWS d'ExpressRoute : bande passante garantie, latence stable, hors Internet public. Le VPN site-à-site est l'alternative chiffrée via Internet.","accept":["direct connect","aws direct connect"]},
  {"id":"clf-te-elb","lvl":6,"dom":"Réseau","q":"Service qui répartit automatiquement le trafic entrant entre plusieurs instances (souvent multi-AZ). Quel sigle ?","explain":"L'ELB : la répartition de charge, brique de la haute disponibilité avec l'Auto Scaling. Variantes : ALB (HTTP), NLB (TCP), GLB.","accept":["ELB","elastic load balancing","load balancer","equilibreur de charge"]},
  {"id":"clf-te-sqs","lvl":2,"dom":"AWS","q":"Service de FILES D'ATTENTE de messages qui découple les composants d'une application. Quel sigle ?","explain":"SQS : le producteur dépose, le consommateur traite à son rythme. Découplage et absorption des pics — souvent cité avec le Well-Architected.","accept":["SQS","simple queue service"]},
  {"id":"clf-te-sns","lvl":3,"dom":"AWS","q":"Service de notifications PUB/SUB : un message publié est diffusé à tous les abonnés (e-mail, SMS, Lambda, SQS). Quel sigle ?","explain":"SNS = un vers plusieurs (push). SQS = file consommée par un lecteur (pull). Le duo revient sans cesse à l'examen.","accept":["SNS","simple notification service"]},
  {"id":"clf-te-eventbridge","lvl":4,"dom":"AWS","q":"Bus d'ÉVÉNEMENTS serverless qui route les événements AWS et applicatifs vers des cibles selon des règles. Quel nom ?","explain":"EventBridge : l'architecture événementielle managée (ex : « instance arrêtée → notifier »). Successeur de CloudWatch Events.","accept":["eventbridge","amazon eventbridge"]},
  {"id":"clf-te-cw","lvl":1,"dom":"AWS","q":"Service de SUPERVISION d'AWS : métriques, logs, alarmes, tableaux de bord. Quel nom ?","explain":"CloudWatch = la santé et les performances (CPU, latence, logs applicatifs). CloudTrail = l'audit des actions. Ne jamais les confondre.","accept":["cloudwatch","amazon cloudwatch"]},
  {"id":"clf-te-cfn","lvl":5,"dom":"AWS","q":"Service d'Infrastructure as Code d'AWS : décrire les ressources dans des templates JSON/YAML et déployer des stacks. Quel nom ?","explain":"CloudFormation : l'IaC natif AWS — environnements répétables, versionnés, sans clics. (Terraform est l'équivalent multi-cloud.)","accept":["cloudformation","aws cloudformation"]},
  {"id":"clf-bi-calc","lvl":1,"dom":"AWS","q":"Outil qui ESTIME le coût mensuel d'une architecture AVANT de la déployer. Quel nom (2 mots) ?","explain":"L'AWS Pricing Calculator : chiffrer un projet futur. À distinguer de Cost Explorer, qui analyse les dépenses passées.","accept":["pricing calculator","calculateur de prix","aws pricing calculator","calculatrice de prix"]},
  {"id":"clf-bi-costexplorer","lvl":2,"dom":"AWS","q":"Outil qui VISUALISE et analyse tes dépenses AWS passées, avec prévisions. Quel nom (2 mots) ?","explain":"Cost Explorer : graphiques des coûts réels par service, compte, tag — et une prévision à 12 mois.","accept":["cost explorer","aws cost explorer"]},
  {"id":"clf-bi-budgets","lvl":4,"dom":"AWS","q":"Outil qui envoie des ALERTES quand tes dépenses (réelles ou prévues) dépassent un seuil défini. Quel nom ?","explain":"AWS Budgets : alertes par e-mail/SNS dès qu'un seuil est franchi ou prévu de l'être. Il alerte, il ne bloque pas.","accept":["budgets","aws budgets"]},
  {"id":"clf-bi-tam","lvl":4,"dom":"AWS","q":"Interlocuteur technique DÉDIÉ inclus dans le plan de support Enterprise. Quel sigle ?","explain":"Le TAM : conseil proactif, revues d'architecture, accompagnement. « TAM » dans l'énoncé = plan Enterprise, réflexe immédiat.","accept":["TAM","technical account manager"]},
  {"id":"clf-bi-trusted","lvl":3,"dom":"AWS","q":"Service qui inspecte ton compte et émet des RECOMMANDATIONS (coûts, performance, sécurité, tolérance aux pannes, limites de service). Quel nom (2 mots) ?","explain":"Trusted Advisor : le consultant automatique d'AWS. Vérifications de base gratuites ; l'ensemble complet exige Business ou Enterprise.","accept":["trusted advisor","aws trusted advisor"]},
  {"id":"j1-0","lvl":5,"dom":"AWS","q":"Un fichier a les droits <code>-rwxr-xr--</code>. Donne l'équivalent en octal.","explain":"rwx=7 (propriétaire), r-x=5 (groupe), r--=4 (autres) → 754.","accept":["754"]},
  {"id":"j1-1","lvl":6,"dom":"AWS","q":"Pourquoi une clé privée SSH doit être en <code>600</code> et pas <code>644</code> ?","explain":"600 = lecture/écriture pour le propriétaire uniquement. SSH refuse même d'utiliser une clé aux permissions trop ouvertes (644 laisse groupe/autres lire).","accept":["lecture","personne d'autre","ssh refuse","trop ouvert","propriétaire seul"]},
  {"id":"j1-2","lvl":4,"dom":"AWS","q":"Un serveur dans un conteneur Docker écoute en <code>127.0.0.1</code>. Le port est publié avec <code>-p 8080:8080</code> mais rien ne répond. Pourquoi ?","explain":"Le trafic arrive via l'interface réseau virtuelle du conteneur (eth0), pas via 127.0.0.1 (loopback = seulement le conteneur lui-même). Il faut écouter sur 0.0.0.0 pour que le port publié fonctionne.","accept":["interface virtuelle","eth0","pas 127.0.0.1","loopback","seulement lui-même"]},
  {"id":"j1-3","lvl":5,"dom":"AWS","q":"Différence essentielle entre <code>git merge</code> et <code>git rebase</code> sur l'historique ?","explain":"merge : garde l'historique réel (commit de fusion à 2 parents), rien n'est réécrit. rebase : rejoue les commits par-dessus la cible → historique linéaire mais SHA réécrits.","accept":["merge garde","rebase réécrit","commit de fusion","linéaire","réécrit l'historique"]},
  {"id":"j1-4","lvl":6,"dom":"AWS","q":"Règle d'or : quand ne JAMAIS faire un <code>git rebase</code> sur une branche ?","explain":"Jamais rebase une branche que quelqu'un d'autre a déjà pull/fetch — ça casse son historique local et force un push --force destructeur.","accept":["déjà partagée","déjà poussée","quelqu'un d'autre","pull","fetch"]},
  {"id":"j1-5","lvl":4,"dom":"AWS","q":"En IAM AWS, quelle est LA différence entre un <b>User</b> et un <b>Role</b> ?","explain":"Un Role n'a pas de credentials permanents : il est emprunté temporairement (via STS/AssumeRole), typiquement par un service (EC2, Lambda). Un User a des credentials fixes (mot de passe, access keys).","accept":["credentials temporaires","empruntable","pas de credentials permanents","temporaire"]},
  {"id":"j1-6","lvl":5,"dom":"AWS","q":"Pourquoi préférer un Role IAM à des Access Keys sur une EC2 ? (2 raisons)","explain":"1) Les Access Keys statiques peuvent fuiter (ex: commit Git) et ne se révoquent pas seules. 2) Un Role donne des credentials temporaires auto-renouvelés via l'instance metadata (IMDS) — rien à stocker ni committer.","accept":["fuite","rotation automatique","temporaire","pas de secret","auto-révoque"]},
  {"id":"j1-7","lvl":6,"dom":"AWS","q":"Par défaut, IAM autorise ou refuse une action non mentionnée dans aucune policy ?","explain":"Deny par défaut (implicit deny). Il faut un Allow explicite pour autoriser quoi que ce soit — c'est ce qui rend le least privilege fiable.","accept":["refuse","deny","implicit deny","interdit"]},
  {"id":"j1-8","lvl":4,"dom":"AWS","q":"Ordre de priorité entre explicit Deny, explicit Allow, et implicit Deny ?","explain":"explicit Deny > explicit Allow > implicit Deny (par défaut). Un Deny écrit quelque part gagne toujours, même s'il y a un Allow ailleurs.","accept":["explicit deny","deny > allow","deny gagne toujours"]},
  {"id":"j1-9","lvl":5,"dom":"AWS","q":"En Azure RBAC, quels sont les 4 niveaux de scope hiérarchique, du plus large au plus précis ?","explain":"Management Group → Subscription → Resource Group → Resource. Les permissions héritent automatiquement vers le bas.","accept":["management group","subscription","resource group","resource"]},
  {"id":"j1-10","lvl":6,"dom":"AWS","q":"Azure sépare 'quelles permissions' et 'à qui/où'. Comment s'appellent ces deux objets ?","explain":"Role Definition (le quoi : ex Reader, Contributor, ou un rôle custom) + Role Assignment (le lien principal + rôle + scope).","accept":["role definition","role assignment"]},
  {"id":"j1-11","lvl":4,"dom":"AWS","q":"Quel est l'équivalent Azure d'un IAM Role AWS attaché à une EC2 (identité empruntée par une ressource, pas un humain) ?","explain":"Managed Identity — system-assigned ou user-assigned, credentials temporaires auto-gérés, comme un IAM Role côté AWS.","accept":["managed identity"]},
  {"id":"j1-12","lvl":5,"dom":"AWS","q":"Un rôle custom Azure a un champ <code>AssignableScopes</code>. À quoi sert-il concrètement ?","explain":"Il verrouille le rôle lui-même pour qu'il ne puisse être assigné QUE dans ce périmètre — impossible de l'assigner ailleurs même par erreur (différent d'AWS où le scope est dans le Resource de chaque Statement).","accept":["verrouille","limite où","empêche d'assigner ailleurs","restreint le périmètre"]},
  {"id":"j1-13","lvl":6,"dom":"AWS","q":"Une commande JSON générée en WSL plante avec 'invalid control character' sur une ligne coupée bizarrement. Quelle est la cause la plus probable ?","explain":"CRLF vs LF : un outil Windows (ex: az.exe appelé depuis WSL) renvoie des lignes terminées par \\r\\n. Le \\r invisible casse le JSON généré dynamiquement. Fix : | tr -d '\\r'.","accept":["crlf","\\r","retour chariot","windows linux","carriage return"]},
  {"id":"j1-14","lvl":4,"dom":"AWS","q":"Dans une commande d'exemple, on voit <code>--assignee &lt;appId-obtenu-avant&gt;</code>. Que se passe-t-il si tu tapes ça tel quel dans bash ?","explain":"< et > sont des opérateurs de redirection en bash (lire/écrire un fichier), pas un simple espace réservé. Bash cherche un fichier nommé 'appId-obtenu-avant' → erreur. Il faut remplacer entièrement par la vraie valeur.","accept":["redirection","erreur","no such file","chevrons"]},
  {"id":"j2-0","lvl":5,"dom":"AWS","q":"Qu'est-ce qui détermine réellement si un subnet AWS est 'public' ou 'privé' ?","explain":"Uniquement sa Route Table : une route 0.0.0.0/0 → igw-xxxxx le rend public. Le nom donné au subnet n'a aucune valeur technique.","accept":["route table","table de routage","route vers igw","0.0.0.0/0"]},
  {"id":"j2-1","lvl":6,"dom":"AWS","q":"Ta VPC est en <code>10.0.0.0/16</code>, ton subnet en <code>10.0.1.0/24</code>. Combien d'adresses IP utilisables (AWS réserve 5) ?","explain":"256 adresses totales en /24, moins les 5 réservées par AWS (réseau, routeur, DNS, futur usage, broadcast) = 251.","accept":["251"]},
  {"id":"j2-2","lvl":4,"dom":"AWS","q":"À quoi sert un NAT Gateway concrètement ?","explain":"Il permet à une ressource dans un subnet privé de sortir sur internet (mises à jour, appels API...) sans jamais être accessible en entrée depuis internet.","accept":["sortie internet","trafic sortant","sans exposer","sans être accessible","masque l'ip"]},
  {"id":"j2-3","lvl":5,"dom":"AWS","q":"Pourquoi le NAT Gateway doit être placé dans un subnet PUBLIC et non privé ?","explain":"Le NAT a lui-même besoin d'une IP publique (Elastic IP) et d'une route vers l'IGW pour relayer le trafic — dans un subnet privé, il serait coincé sans sortie, comme la ressource qu'il est censé aider.","accept":["besoin d'une route vers l'igw","lui-même a besoin de sortir","ip publique"]},
  {"id":"j2-4","lvl":6,"dom":"AWS","q":"Un Security Group est 'stateful'. Concrètement, qu'est-ce que ça change pour le trafic de retour ?","explain":"Si l'entrée est autorisée, la réponse sortante correspondante est automatiquement autorisée, sans règle explicite — le SG retient l'état de la connexion.","accept":["automatiquement autorisé","pas besoin de règle sortante","se souvient"]},
  {"id":"j2-5","lvl":4,"dom":"AWS","q":"Une NACL est 'stateless'. Si elle autorise l'entrée sur le port 443, que faut-il ajouter en plus pour que la réponse fonctionne ?","explain":"Une règle de sortie explicite couvrant les ports éphémères (typiquement 1024-65535), car la NACL ne retient aucun état — chaque sens du trafic doit être autorisé séparément.","accept":["règle de sortie","port éphémère","1024-65535","sortie explicite"]},
  {"id":"j2-6","lvl":5,"dom":"AWS","q":"Security Group : niveau instance ou niveau subnet ?","explain":"Security Group = niveau instance (ENI). NACL = niveau subnet.","accept":["instance"]},
  {"id":"j2-7","lvl":6,"dom":"AWS","q":"Une NACL peut-elle contenir des règles 'Deny' explicites, contrairement à un Security Group ?","explain":"Oui — les NACL supportent Allow ET Deny, avec des règles numérotées évaluées dans l'ordre. Un Security Group ne peut QUE autoriser (allow), jamais refuser explicitement.","accept":["oui"]},
  {"id":"j2-8","lvl":4,"dom":"AWS","q":"Qu'est-ce qu'une AMI ?","explain":"Amazon Machine Image : le template de départ d'une instance (OS + logiciels préinstallés). On peut créer sa propre AMI (golden image) pour déployer des instances identiques rapidement.","accept":["template","image machine","os préinstallé","golden image"]},
  {"id":"j2-9","lvl":5,"dom":"AWS","q":"Un script user_data s'exécute-t-il à nouveau après un simple <code>reboot</code> de l'instance ?","explain":"Non — user_data ne s'exécute qu'une seule fois, au tout premier démarrage. Le script doit donc être auto-suffisant en une passe ; pour du répétitif, utiliser systemd ou cron.","accept":["non"]},
  {"id":"j2-10","lvl":6,"dom":"AWS","q":"Dans un type d'instance comme <code>t3.micro</code>, que signifie la lettre <code>t</code> ?","explain":"t = burstable/économique (crédits CPU). m = général équilibré, c = compute-optimized, r = RAM-optimized.","accept":["burstable","économique"]},
  {"id":"j2-11","lvl":4,"dom":"AWS","q":"Tu perds ta clé privée SSH d'une instance EC2. Peux-tu encore te connecter en SSH directement avec la clé publique seule ?","explain":"Non — seule la clé privée permet l'authentification. Sans elle, plus d'accès SSH direct (il faudrait passer par un autre mécanisme comme EC2 Instance Connect ou reconfigurer via un volume détaché).","accept":["non"]},
  {"id":"j2-12","lvl":5,"dom":"AWS","q":"Pourquoi chmod 400 (et pas 600) est souvent recommandé pour un fichier .pem téléchargé une seule fois ?","explain":"400 = lecture seule pour le propriétaire, aucune écriture même pour lui-même — encore plus restrictif que 600, adapté à une clé qu'on ne modifie jamais après création.","accept":["lecture seule","pas d'écriture","plus restrictif"]},
  {"id":"j2-13","lvl":6,"dom":"AWS","q":"Dans une architecture VPC->EC2, dans quel ordre doit-on DÉTRUIRE les ressources (subnet, route table, IGW, VPC) ?","explain":"Du plus dépendant vers le plus général (inverse de la création) : instance -> route table -> subnet -> détacher IGW -> supprimer IGW -> VPC. Même logique que les role assignments Azure avant les role definitions.","accept":["du plus dépendant","spécifique vers général","inverse de la création"]}
]);
